INSERT INTO `events` VALUES (14, 1, '≪スマイルマルシェ≫ドライフラワーを使った雑貨づくり　4/2～ダンボールに飾ろう！～', 'ワークショップ', '予約制', '[{\"date\":\"2022-04-02\",\"time\":[660,960]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木地町木田', '2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659005310427.jpg,/imgs/events/172659006278528.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 50代以上向け, 夫婦+子供, 二世帯, 三世帯, 夫婦のみ, DIY', '<figure class=\"image\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172659015555327.jpg\" width=\"1024\" height=\"768\"></figure><p>​</p><p><span style=\"background-color:hsl(0, 0%, 100%);color:hsl(0, 0%, 0%);\">講師：nagano　megumi先生</span></p><p>&nbsp;</p><p><i>予約枠：①11:00～　　先着5組限定</i></p><p>&nbsp;</p><p><i>　　　　②14:00～　　先着5組限定</i></p><p>&nbsp;</p><p><i>費用：1500円</i></p><p>&nbsp;</p><p>&nbsp;</p><h4><span style=\"color:hsl(0, 0%, 0%);\">スマイルビルダーズならではの特典もあり！</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">下記「キャンペーン情報」をご覧ください♪</span></h4><p>​</p><p>&nbsp;</p><p><i>-スマイルマルシェとは…？-&nbsp; &nbsp;</i></p><p>「地域」でご活躍されているクリエイターさんたちと「地域」で活躍するスマイルビルダーズのコラボレーション企画！</p><p>つくる楽しさ、動く楽しさ、観る楽しさ、味わう楽しさ。これらは暮らしで大切なこと。ぜひご体感ください♪</p><p>&nbsp;</p><figure class=\"image\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172659032320628.jpg\" width=\"1024\" height=\"768\"></figure><p>&nbsp;</p><p>&nbsp;</p><h4><span style=\"background-color:#ffffcc;color:hsl(0, 0%, 0%);\">雑貨販売・お菓子販売</span><span style=\"color:hsl(0, 0%, 0%);\">も同日開催しておりますので、</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">ぜひ足をお運びください☆</span></h4><p><span style=\"color:hsl(0, 0%, 0%);\">​</span></p>', '<h4><span style=\"color:hsl(0, 0%, 0%);\">公式ホームページ予約者特典！</span></h4><h4><span style=\"color:#e74c3c;\"><strong>展示場モデルハウス3棟以上ご見学</strong></span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">された方は無料でワークショップが体験できます。</span></h4><p>&nbsp;</p><p>&nbsp;</p><h4><span style=\"color:hsl(0, 0%, 0%);\">≪無料体験の流れ≫</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">①このホームページから体験してみたい</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">　ワークショップを予約しよう！</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">②ワークショップがはじまる１～２時間前までに</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">　総合案内所受付で「スタンプカード」を受け取ろう！</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">③気になる工務店の展示場モデルハウスを3棟見学して、</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">　スタンプを３つ集めよう！</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">④ワークショップの時間になったら</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">　会場（総合案内所内）に集まろう！</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">⑤ワークショップを無料で楽しもう！</span></h4><p>&nbsp;</p><h4><span style=\"color:hsl(0, 0%, 0%);\">みなさまのご予約を、心よりお待ちしております。</span></h4><p>&nbsp;</p><h4><span style=\"color:hsl(0, 0%, 0%);\">※マックカードは、各展示場モデルハウスの見学を公式HPからご予約いただいた方の先着順になり、</span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\">　このキャンペーンについてはマックカードの対象ではありませんのでご注意ください。</span></h4>', '設定しない', '2024-09-18 01:12:20', '2024-11-28 10:21:59', NULL, 1);
INSERT INTO `events` VALUES (15, 1, '≪スマイルマルシェ≫　お絵描き教室　4/3のみ', 'ワークショップ', '予約制', '[{\"date\":\"2022-04-03\",\"time\":[660,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木地町木田', '2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659078712629.jpg,/imgs/events/172659079129230.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 50代以上向け, 夫婦+子供, 二世帯, 三世帯, 夫婦のみ, DIY', '<figure class=\"image\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172659084685829.jpg\" width=\"1024\" height=\"768\"></figure><p>講師：mionakahara 先生</p><p>&nbsp;</p><p><i>予約枠：①11:00～　　先着5組限定</i></p><p>&nbsp;</p><p><i>　　　　②14:00～　　先着5組限定</i></p><p>&nbsp;</p><p><i>費用：1500円</i></p><p>&nbsp;</p><p>スマイルビルダーズならではの<span style=\"color:#c0392b;\">特典</span>もあり！</p><p>下記「キャンペーン情報」をご覧ください♪</p><p>&nbsp;</p><p><i>-スマイルマルシェとは…？-&nbsp; &nbsp;</i></p><p>「地域」でご活躍されているクリエイターさんたちと「地域」で活躍するスマイルビルダーズのコラボレーション企画！</p><p>つくる楽しさ、動く楽しさ、観る楽しさ、味わう楽しさ。これらは暮らしで大切なこと。ぜひご体感ください♪</p><p>&nbsp;</p><figure class=\"image\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172659092122630.jpg\" width=\"1024\" height=\"768\"></figure><p>&nbsp;</p><p><span style=\"background-color:#ffffcc;\">雑貨販売・お菓子販売</span>も同日開催しておりますので、</p><p>ぜひ足をお運びください☆</p>', '<p><br><strong>公式ホームページ予約者特典！</strong></p><p><span style=\"color:#e74c3c;\"><strong>展示場モデルハウス3棟以上ご見学</strong></span></p><p><strong>された方は無料でワークショップが体験できます。</strong></p><p>&nbsp;</p><p><strong>≪無料体験の流れ≫</strong></p><p><strong>①このホームページから体験してみたい</strong></p><p><strong>　ワークショップを予約しよう！</strong></p><p><strong>②ワークショップがはじまる１～２時間前までに</strong></p><p><strong>　総合案内所受付で「スタンプカード」を受け取ろう！</strong></p><p><strong>③気になる工務店の展示場モデルハウスを3棟見学して、</strong></p><p><strong>　スタンプを３つ集めよう！</strong></p><p><strong>④ワークショップの時間になったら</strong></p><p><strong>　会場（総合案内所内）に集まろう！</strong></p><p><strong>⑤ワークショップを無料で楽しもう！</strong></p><p>&nbsp;</p><p><strong>みなさまのご予約を、心よりお待ちしております。</strong></p><p>&nbsp;</p><p><strong>※マックカードは、各展示場モデルハウスの見学を公式HPからご予約いただいた方の先着順になり、</strong></p><p><strong>　このキャンペーンについてはマックカードの対象ではありませんのでご注意ください。</strong></p>', '設定しない', '2024-09-18 01:30:10', '2024-11-28 10:22:00', NULL, 1);
INSERT INTO `events` VALUES (16, 1, '≪スマイルマルシェ≫　親子でできる体操教室　4/2・4/3', 'ワークショップ', '予約制', '[{\"date\":\"2022-04-02\",\"time\":[660,1020]},{\"date\":\"2022-04-03\",\"time\":[660,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木地町木田', '2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659123897531.jpg,/imgs/events/172659124284632.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 50代以上向け, 夫婦+子供, 二世帯, 三世帯, 夫婦のみ, DIY', '<figure class=\"image\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172659130318031.jpg\" width=\"1024\" height=\"768\"></figure><p>&nbsp;</p><p>講師：iwamotomegumi515 先生</p><p>&nbsp;</p><p><i>予約枠：①11:00～　　先着5組限定</i></p><p>&nbsp;</p><p><i>　　　　②14:00～　　先着5組限定</i></p><p>&nbsp;</p><p><i>費用：500円</i></p><p>&nbsp;</p><p>スマイルビルダーズならではの<span style=\"color:#c0392b;\">特典</span>もあり！</p><p>下記「キャンペーン情報」をご覧ください♪</p><p>&nbsp;</p><p><i>-スマイルマルシェとは…？-&nbsp; &nbsp;</i></p><p>「地域」でご活躍されているクリエイターさんたちと「地域」で活躍するスマイルビルダーズのコラボレーション企画！</p><p>つくる楽しさ、動く楽しさ、観る楽しさ、味わう楽しさ。これらは暮らしで大切なこと。ぜひご体感ください♪</p><p>&nbsp;</p><figure class=\"image\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172659136223132.jpg\" width=\"1024\" height=\"768\"></figure><p>&nbsp;</p><p><span style=\"background-color:#ffffcc;\">雑貨販売・お菓子販売</span>も同日開催しておりますので、</p><p>&nbsp;</p><p>ぜひ足をお運びください☆</p>', '<p>&nbsp;</p><p><strong>公式ホームページ予約者特典！!</strong></p><p>&nbsp;</p><p><span style=\"color:#e74c3c;\"><strong>展示場モデルハウス3棟以上ご見学</strong></span></p><p><strong>された方は無料でワークショップが体験できます。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p><strong>≪無料体験の流れ≫</strong></p><p><strong>①このホームページから体験してみたい</strong></p><p><strong>　ワークショップを予約しよう！</strong></p><p><strong>②ワークショップがはじまる１～２時間前までに</strong></p><p><strong>　総合案内所受付で「スタンプカード」を受け取ろう！</strong></p><p><strong>③気になる工務店の展示場モデルハウスを3棟見学して、</strong></p><p><strong>　スタンプを３つ集めよう！</strong></p><p><strong>④ワークショップの時間になったら</strong></p><p><strong>　会場（総合案内所内）に集まろう！</strong></p><p><strong>⑤ワークショップを無料で楽しもう！</strong></p><p>&nbsp;</p><p><strong>みなさまのご予約を、心よりお待ちしております。</strong></p><p>&nbsp;</p><p><strong>※マックカードは、各展示場モデルハウスの見学を公式HPからご予約いただいた方の先着順になり、</strong></p><p><strong>　このキャンペーンについてはマックカードの対象ではありませんのでご注意ください。</strong></p><p>&nbsp;</p>', '設定しない', '2024-09-18 01:38:03', '2024-11-28 10:22:00', NULL, 1);
