INSERT INTO `events` VALUES (19, 1, 'おみせやさんごっこ！～キッズマネースクール～', '講座', '予約制', '[{\"date\":\"2023-03-19\",\"time\":[840,960]}]', 'お子様だけでの参加は不可でお願い致します。', '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659332998135.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 夫婦+子供, 二世帯, 駐車場あり, 子育て', '<figure class=\"image\"><img style=\"aspect-ratio:1024/729;\" src=\"/imgs/upload/172659355792335.jpg\" width=\"1024\" height=\"729\"></figure><h4 style=\"text-align:center;\"><span style=\"color:#2980b9;\"><strong>こども店長になって、</strong></span></h4><h2 style=\"text-align:center;\"><span style=\"color:#f39c12;\"><strong>お金のこと</strong></span><span style=\"color:#2980b9;\"><strong>を学ぼう!!</strong></span></h2><p style=\"text-align:center;\">教えようと思ったら大人でも案外むずかしくて学校でも教えてくれない、</p><p style=\"text-align:center;\">大切なお金のコト。お店屋さんごっこをしながら楽しく学べるよ♪</p><p style=\"text-align:center;\">おうちの方には『おこづかいの渡し方』を伝授!!</p><p style=\"text-align:center;\">親子で一緒にお金のお勉強しませんか？</p>', NULL, '設定しない', '2024-09-18 02:02:49', '2024-11-28 10:22:02', NULL, 1);
