INSERT INTO `events` VALUES (30, 1, '【無料】親子で聞きたいお片付け教室　講師：整理収納アドバイザー・ 遠藤陽子さん', 'その他', '予約制', '[{\"date\":\"2024-02-04\",\"time\":[660,690,840,870]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659631354845.jpg', 0, '/imgs/events/172659641995145.jpg', NULL, '<p><span style=\"color:#2980b9;\"><strong>整理収納アドバイザー・遠藤陽子さんによる</strong></span></p><h3><span style=\"color:#2ecc71;\"><strong>親子で聞きたい！</strong></span></h3><h3><span style=\"color:#2ecc71;\"><strong>お片付け教室!!</strong></span></h3><p><span style=\"color:#2980b9;\"><strong>子供たちにおかたづけ上手になってもらうためのお話を、親子で一緒に聞いてみませんか～？？</strong></span></p><p><span style=\"color:#2980b9;\"><strong>▽▼詳細はこちらにも▽▼</strong></span></p><p><a href=\"https://www.myufm.jp/info/lalala240204/\">シュフシェア！LaLaLa in スマイル・ビルダーズ 姶良総合住宅展示場 | インフォメーション | エフエム鹿児島 ミューエフエム (myufm.jp)</a></p>', NULL, '設定しない', '2024-09-18 03:03:18', '2024-11-28 10:22:08', NULL, 1);
