INSERT INTO `events` VALUES (35, 1, 'キッズダンス体験イベント', 'その他', '予約制', '[{\"date\":\"2024-06-30\",\"time\":[690,900]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659748919248.png', 0, NULL, NULL, '<p><span style=\"color:#e67e22;\"><strong>小学生以下対象、参加無料!!</strong></span></p><p><span style=\"color:#27ae60;\">経験不問！</span></p><p><span style=\"color:#27ae60;\">体を動かしてダンスを楽しもう♪</span></p><p><span style=\"color:#27ae60;\">超・初心者でも、超・楽しく踊れる♪</span></p><p>&nbsp;</p><p><span style=\"color:#e67e22;\">講師：若林慶さん</span></p><p><span style=\"color:#27ae60;\">（EXILEの元バックダンサー、現在TicTokダンサー）</span></p><h2><span style=\"color:#ff66cc;\"><strong>午前の部</strong></span></h2><h4><span style=\"color:hsl(0, 0%, 0%);\"><strong>11:30～</strong></span></h4><h2><span style=\"color:#3498db;\"><strong>午後の部</strong></span></h2><h4><span style=\"color:hsl(0, 0%, 0%);\"><strong>14：00～</strong></span></h4><p>各回定員<span style=\"color:#e74c3c;\">20名</span>まで!!</p><p>※定員に達した場合は募集を締め切らせていただきます！</p><p>◎約１時間程度を予定しております。</p><p>&nbsp;</p><p>動きやすい服＆靴で参加してね!!（サンダルNG）</p><p>お飲み物、タオル、帽子をお忘れなく!!<br>雨天の場合は案内所内で実施！！土足になります</p>', NULL, '設定しない', '2024-09-18 03:23:10', '2024-11-28 10:22:11', NULL, 1);
INSERT INTO `events` VALUES (36, 1, '第2回キッズダンス（5歳～小学2年生コース）', 'その他', '予約制', '[{\"date\":\"2024-08-18\",\"time\":[600,870]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659772225649.png', 0, NULL, NULL, '<h3><span style=\"color:#e67e22;\"><strong>5歳～小学生2年生コース</strong></span></h3><p><span style=\"color:#e67e22;\"><strong>参加無料!!</strong></span></p><p><span style=\"color:#27ae60;\">経験不問！</span></p><p><span style=\"color:#27ae60;\">体を動かしてダンスを楽しもう♪</span></p><p><span style=\"color:#27ae60;\">超・初心者でも、超・楽しく踊れる♪</span></p><p>&nbsp;</p><p><span style=\"color:#e67e22;\">講師：若林慶さん</span></p><p><span style=\"color:#27ae60;\">（EXILEの元バックダンサー、現在TikTokダンサー）</span></p><h2><span style=\"color:#ff66cc;\"><strong>午前の部</strong></span></h2><h3><span style=\"color:hsl(0, 0%, 0%);\"><strong>10:00～11:00</strong></span></h3><h2><span style=\"color:#3498db;\"><strong>午後の部</strong></span></h2><h3><span style=\"color:hsl(0, 0%, 0%);\"><strong>13:30～14：30</strong></span></h3><p>各回定員<span style=\"color:#e74c3c;\">15名</span>まで!!</p><p>※定員に達した場合は募集を締め切らせていただきます！</p><p>◎約１時間程度を予定しております。</p><p>&nbsp;</p><p>動きやすい服＆靴で参加してね!!（サンダルNG）</p><p>お飲み物、タオルをお忘れなく!!<br>&nbsp;</p><p><span style=\"color:#e74c3c;\">開始時刻の10分前に会場にお越しください♪</span></p>', NULL, '設定しない', '2024-09-18 03:27:02', '2024-11-28 10:22:12', NULL, 1);
INSERT INTO `events` VALUES (37, 1, 'ベビーマッサージ教室', 'イベント', 'オープン制', '[{\"date\":\"2024-08-17\",\"time\":[600,660,690,750,810,870,900,960]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659800362250.png', 0, NULL, NULL, '<p>熊本在中の講師&nbsp;</p><p>&nbsp;</p><p><strong>HeyoHeyobaby山本ゆかりさん</strong>による&nbsp;</p><figure class=\"image\"><img style=\"aspect-ratio:620/1102;\" src=\"/imgs/upload/172659806723051.jpg\" width=\"620\" height=\"1102\"></figure><h3>今回だけの特別価格！！</h3><h4><span style=\"color:#f39c12;\"><strong>1000円</strong></span><span style=\"color:hsl(0, 0%, 0%);\">でベビーマッサージ教室が受講できます！</span></h4><p>&nbsp;</p><h3><strong>各回4組ずつ</strong></h3><p><strong>持ち物：バスタオル、飲み物、お子様のお気に入りのおもちゃ?</strong></p><p><strong>注意事項：予防接種後24時間はマッサージを受けられません。</strong></p><p><strong>　　　　　ベビーオイルを使用します。</strong></p><p><strong>　　　　　心配な方はパッチテストを行うか、普段お使いのものを持って</strong></p><p><strong>　　　　　来られても大丈夫です。</strong></p>', NULL, '設定しない', '2024-09-18 03:31:18', '2024-11-28 10:22:12', NULL, 1);
INSERT INTO `events` VALUES (38, 1, 'みろく夜市inスマイル・ビルダーズ‼', 'イベント', '予約制', '[{\"date\":\"2024-08-17\",\"time\":[1080,1290]},{\"date\":\"2024-08-18\",\"time\":[1080,1290]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659839653652.png', 0, NULL, NULL, '<h2 style=\"text-align:center;\"><strong>みろく夜市</strong></h2><p style=\"text-align:center;\">～ジャズを身近に楽しめるイベント♪～</p><h4 style=\"text-align:center;\"><span style=\"color:#3498db;\"><strong>8月17日（土）・18日（日）</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#3498db;\"><strong>18：00～21：30</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#f39c12;\"><strong>イベント無料</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#f39c12;\"><strong>30名（両日で60名）</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#f39c12;\"><strong>募集期間：</strong><s><strong>8月4日（日）</strong></s><strong>まで</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#e74c3c;\"><strong>席の追加にて8月12日（月）まで</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#e74c3c;\"><strong>延長決定！！！</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#f39c12;\"><strong>当落発表：８月８日（木）順次メールにて</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#c0392b;\"><strong>※同一名での複数の応募は無効とさせていただきます。</strong></span></h4><h4 style=\"text-align:center;\"><span style=\"color:#000000;\"><strong>東京を拠点に活動している</strong></span><br><span style=\"color:#000000;\"><strong>MALIYAさんをお呼びして</strong></span><br><span style=\"color:#000000;\"><strong>美味しいご飯を食べながら</strong></span><br><span style=\"color:#000000;\"><strong>音楽を楽しもう♪♪</strong></span></h4><figure class=\"media\"><oembed url=\"https://www.youtube.com/embed/zum1YgkzBsQ\"></oembed></figure><p>Keys//Yoshi Kodate<br>Bass//山本 連</p><p>Drums//Desire Nealy</p><p>&nbsp;</p><p>夏の夜を、美味しい食べ物とジャズの音色で彩りましょう??</p><p>ご来場をお待ちしております</p><p>&nbsp;</p><p><span style=\"color:#c0392b;\">※　会場への食べ物の持ち込みは禁止とさせていただきます。</span></p>', NULL, '設定しない', '2024-09-18 03:36:56', '2024-11-28 10:22:14', NULL, 1);
INSERT INTO `events` VALUES (39, 1, '第2回キッズダンス（小学3年生～中学3年生コース）', 'その他', '予約制', '[{\"date\":\"2024-08-18\",\"time\":[690,960]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659885133455.png', 0, NULL, '30代向け, 40代向け, 三世帯', '<h3><span style=\"color:#e67e22;\"><strong>小学生3年生～中学3年生コース</strong></span></h3><p><span style=\"color:#e67e22;\"><strong>参加無料!!</strong></span></p><p><span style=\"color:#27ae60;\">経験不問！</span></p><p><span style=\"color:#27ae60;\">体を動かしてダンスを楽しもう♪</span></p><p><span style=\"color:#27ae60;\">超・初心者でも、超・楽しく踊れる♪</span></p><p>&nbsp;</p><p><span style=\"color:#e67e22;\">講師：若林慶さん</span></p><p><span style=\"color:#27ae60;\">（EXILEの元バックダンサー、現在TicTokダンサー）</span></p><h2><span style=\"color:#ff66cc;\"><strong>午前の部</strong></span></h2><h3><span style=\"color:hsl(0, 0%, 0%);\"><strong>11:30～12:30</strong></span></h3><h2><span style=\"color:#3498db;\"><strong>午後の部</strong></span></h2><h3><span style=\"color:hsl(0, 0%, 0%);\"><strong>15:00～16：00</strong></span></h3><p>各回定員<span style=\"color:#e74c3c;\">15名</span>まで!!</p><p>※定員に達した場合は募集を締め切らせていただきます！</p><p>◎約１時間程度を予定しております。</p><p>&nbsp;</p><p>動きやすい服＆靴で参加してね!!（サンダルNG）</p><p>お飲み物、タオルをお忘れなく!!</p><p><span style=\"color:#e74c3c;\">開始時刻の10分前に会場にお越しください♪</span></p>', NULL, '設定しない', '2024-09-18 03:46:03', '2024-11-28 10:22:14', NULL, 1);
INSERT INTO `events` VALUES (40, 1, '【2周年祭】ワークショップ', 'その他', '予約制', '[{\"date\":\"2024-04-21\",\"time\":[600,960]},{\"date\":\"2024-11-29\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659910106456.png', 0, NULL, NULL, '<h2><span style=\"color:#ff66cc;\"><strong>2周年祭✨</strong></span><span style=\"color:#3498db;\"><strong>特別企画!!</strong></span></h2><h3><span style=\"color:#27ae60;\"><strong>ワークショップ</strong></span>を開催！</h3><p>人気のワークショップ♪</p><p>バルーンアートやアクセサリー、</p><p>キーホルダーなど自分だけの作品を作ろう！</p><p>&nbsp;</p><p>事前予約で<span style=\"color:#e74c3c;\"><strong>先着20組</strong></span>に(1家族1枚かぎり）</p><p>当日ワークショップで使える</p><p><span style=\"color:#e74c3c;\"><strong>500﻿円分チケット</strong></span>をプレゼントしちゃいます！</p><p>ぜひ自分だけの素敵な作品を作りましょう?</p><p>お申し込みはお早めに✨✨✨</p>', '<h4><span style=\"color:#e74c3c;\">先着20組限定（1家族1枚かぎり）?✨</span></h4><h4><span style=\"color:#e74c3c;\">ワークショップで使える</span></h4><h4><span style=\"color:#e74c3c;\">500円分のチケットプレゼント?</span></h4>', '設定しない', '2024-09-18 03:50:15', '2024-11-28 10:22:15', NULL, 1);
INSERT INTO `events` VALUES (41, 1, '第６回赤ちゃんハイハイ大会', 'イベント', '予約制', '[{\"date\":\"2024-09-08\",\"time\":[600,660,810,870]}]', NULL, '公開', 0, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659935268857.png', 0, NULL, NULL, '<h2><strong>第6回　赤ちゃんハイハイ大会✨??</strong></h2><h3><span style=\"color:#e67e22;\"><strong>各回３０名</strong></span></h3><p><strong>午前の部　【受付】9：45～　【開始】10：00</strong></p><p><strong>午後の部　【受付】13：15～　【開始】13：30</strong></p><p>&nbsp;</p><p>参加費無料♪</p><p>参加賞もあります?✨</p><p>&nbsp;</p><p><span style=\"color:hsl(0, 75%, 60%);\"><strong>エントリーの締め切りは9月6日（金）まで！</strong></span></p><p><span style=\"color:#e74c3c;\"><strong>※募集人数に達し次第、締め切らせていただきますのでご了承ください。</strong></span></p>', NULL, '設定しない', '2024-09-18 03:54:05', '2024-11-28 10:22:20', NULL, 1);
INSERT INTO `events` VALUES (42, 1, '第2回カタカタレース大会', 'イベント', '予約制', '[{\"date\":\"2024-09-08\",\"time\":[690,750,900,960]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659956117258.png', 0, NULL, NULL, '<h2><strong>第2回　カタカタレース大会✨??</strong></h2><h3><span style=\"color:#e67e22;\"><strong>各回３０名</strong></span></h3><p><span style=\"color:#e67e22;\">午前の部　</span></p><p><span style=\"color:#e67e22;\">【受付】11：15～　【開始】11：30</span></p><p><span style=\"color:#e67e22;\">午後の部</span></p><p><span style=\"color:#e67e22;\">【受付】14：45～　【開始】15：00</span></p><p>&nbsp;</p><p>参加費無料♪</p><p>参加賞もあります?✨</p><p>&nbsp;</p><h4><span style=\"color:#e74c3c;\"><strong>エントリーの締め切りは</strong></span></h4><h4><span style=\"color:#e74c3c;\"><strong>9月6日（金）まで！</strong></span></h4><h4><span style=\"color:#e74c3c;\"><strong>※募集人数に達し次第、</strong></span></h4><h4><span style=\"color:#e74c3c;\"><strong>締め切らせていただきますのでご了承ください。</strong></span></h4>', NULL, '設定しない', '2024-09-18 03:57:46', '2024-11-28 10:22:21', NULL, 1);
INSERT INTO `events` VALUES (43, 1, '逆バンジージャンプ', 'イベント', '予約制', '[{\"date\":\"2024-09-08\",\"time\":[600,960]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', '「3-6-5」', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172659979565159.png', 0, NULL, NULL, '<h4><span style=\"color:#c0392b;\"><strong>※お子様お1人につき1回の予約！</strong></span></h4><h4><span style=\"color:#c0392b;\"><strong>　まとめての予約は無効となります！</strong></span></h4><p>&nbsp;</p><p>住宅展示場を空から見学！？?️</p><h3><strong>逆バンジージャンプに挑戦しよう！！</strong><br><span style=\"color:#e74c3c;\"><strong>対象年齢5歳～12歳まで！</strong></span></h3><h4><span style=\"color:#e74c3c;\"><strong>参加費３００円　</strong></span></h4><h4><span style=\"color:#e74c3c;\"><strong>※　特典：300円のキッチンカーで使えるチケットプレゼント</strong></span></h4><h4><span style=\"color:#e74c3c;\"><strong>雨天の場合は中止となります。</strong></span></h4><h4><span style=\"color:#e67e22;\"><strong>１時間ごとに予約枠を設けます。</strong></span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\"><strong>先着順となる為、人数に達し次第締め切らせていただきます。</strong></span></h4>', NULL, '設定しない', '2024-09-18 04:01:27', '2024-11-28 10:22:22', NULL, 1);
INSERT INTO `events` VALUES (44, 2, '【サンプル】予約制完成見学会｜自然素材が心地よい家', '完成見学会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今', '3/16/2005', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172830939541860.jpeg,/imgs/events/172830941934461.png,/imgs/events/172830942700362.png,/imgs/events/172830943658863.png,/imgs/events/172830944331664.jpeg', 0, '/imgs/events/172830959527165.png', NULL, '<h3>​<strong>自然素材が心地よい家</strong></h3><p>&nbsp;</p><p>自然素材が心地よい家では、お客様のご要望を多数取り入れ、<br>心地よさとデザイン性を高次元で両立した家です。<br>&nbsp;<br>実際に触れて、見て、感じていただき、<br>新しい住まいについてのイメージを膨らませていただけます。<br>この機会に、ぜひご家族でお越しください。<br>&nbsp;<br>■お施主様の情報<br>・ご家族構成　ご夫婦、お子様1人<br>・敷地面積　〇〇〇.〇〇（〇〇坪）<br>・延床面性　〇〇〇.〇〇（〇〇坪）</p><p>&nbsp;</p><h3><strong>くつろげる広々リビング</strong></h3><p>&nbsp;</p><p>リビングはテレビや音響機器を設置して、好きな映画や音楽を楽しむスペースを。ホームシアターやステレオシステムを導入することで、くつろぎの時間が一層充実。またリビング、キッチンが一体化し、明るく広々とした空間を作っています。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOUl4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--24e9d345b100789e7266cdf2768cae410fe17a41/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaV2tDYkFJPSIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--051c3c6dc4c4ae37ab3e6d54202554899ecffbca/event_description_image_path6.png\" alt=\"\" width=\"1024\" height=\"768\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728309483050image.gif\" width=\"15\" height=\"15\"></span>​</p><h3><strong>すっきりした清潔なキッチン</strong></h3><p>&nbsp;</p><p>不必要なものを取り除き、シンプルなデザインに仕上げました。<br>カウンタートップや壁面にあまり物を置かず、必要最小限のアイテムで。<br>引き出しや戸棚、パントリーなどを効果的に使って収納を工夫しております。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOU14RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--1f4dc15e7986493257b2f447b04f3828bee71bee/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaV2tDYkFJPSIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--051c3c6dc4c4ae37ab3e6d54202554899ecffbca/event_description_image_path7.png\" alt=\"\" width=\"1024\" height=\"768\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728309483050image.gif\" width=\"15\" height=\"15\"></span>​</p><h3><strong>作業に集中できる仕事部屋</strong></h3><p>&nbsp;</p><p>自然光が取り入れられる明るく快適な仕事部屋。仕事に専念できるように、自分の好みや趣味を反映させたパーソナルスペースを実現。<br>落ち着いた色調や仕事に適したカラーパレットを選ぶことで、リラックス感をもたらし、集中力を向上させます。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOVF4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--f833fc5ace8d441fa5528b5da02800ccbe704e16/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaV2tDYkFJPSIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--051c3c6dc4c4ae37ab3e6d54202554899ecffbca/event_description_image_path8.png\" alt=\"\" width=\"1024\" height=\"768\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728309483050image.gif\" width=\"15\" height=\"15\"></span>​</p><h3><strong>完成見学会はお子様連れ歓迎</strong></h3><p>完成見学会はお子様連れのご家族も大歓迎！キッズスペースをご用意しておりますので、安心してご覧になれます。&nbsp;</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOUF4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--f775cfd060b2c207e62173c5115eee2c65ccab2b/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/event_description_image_path4.jpeg\" alt=\"\" width=\"1440\" height=\"1080\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728309483050image.gif\" width=\"15\" height=\"15\"></span>​</p><p>​</p>', NULL, '設定しない', '2024-06-04 17:20:00', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (47, 2, '【サンプル】※先着10組限定※500万円以上差が出る！住宅ローン相談会', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今', '3/16/2005', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172831108085165.jpeg,/imgs/events/172831108539866.png,/imgs/events/172831108902967.png,/imgs/events/172831109290368.jpeg,/imgs/events/172831109918269.jpeg', 0, NULL, NULL, '<h3>​<strong> ＼ 住宅ローン相談会を開催！／</strong><br>&nbsp;</h3><p>プロのお金の悩みを、プロのファイナンシャルプランナーから無料でご案内しています。住宅ローン控除や補助金を活用することで、<strong>家賃並みの支払いで一戸建てを購入できた方</strong>もいます。是非ご相談にお越しください。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBODB4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--4d711892180511f987e3e3751cc054ab4401b70b/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/event_description_image_path1.jpeg\" alt=\"\" width=\"620\" height=\"465\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728311122813image.gif\" width=\"15\" height=\"15\"></span>​</p><h3><strong>こんな人にお勧め&nbsp;</strong></h3><p><span style=\"background-color:#f1c40f;\"><strong>&nbsp;1&nbsp;</strong></span> 住宅購入を検討し始めたばかりで、お金のことについて知りたい<br>&nbsp;<br><span style=\"background-color:#f1c40f;\">&nbsp;<strong>2&nbsp;</strong></span> 少しでもお得に住宅ローンを組みたい<br>&nbsp;<br><span style=\"background-color:#f1c40f;\">&nbsp;<strong>3&nbsp;</strong></span>&nbsp;自分の年収で購入できる、家の金額を知りたい<br>&nbsp;<br><span style=\"background-color:#f1c40f;\">&nbsp;<strong>4&nbsp;</strong></span>&nbsp;住宅ローン控除の変更点をまだ知らない<br>&nbsp;<br><span style=\"background-color:#f1c40f;\">&nbsp;<strong>5&nbsp;</strong></span>&nbsp;家を建てたいけれど、教育費や旅行費も貯めたい</p><h3><strong>ファイナンシャルプランナーに相談できる</strong></h3><p>100組以上の資金計画の相談に乗ってきた、<span style=\"color:#f39c12;\"><strong>FP1級の資格を持つ担当</strong></span>にご相談いただけます。家族構成や、収入・支出に合わせた支払い計画の相談に乗らせていただきます。</p><p><br>&nbsp;<img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBODR4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--5a2a554c5e76b9309783f62504f025ac95d53920/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/event_description_image_path2.jpeg\" alt=\"\" width=\"620\" height=\"413\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728311122813image.gif\" width=\"15\" height=\"15\"></span>​<br>&nbsp;</p><p><strong>【担当プロフィール】</strong><br>・ビズ・クリエイション代表　・FP1級<br>・100組以上の資金計画の相談対応実績<br>※記入内容はイメージです</p><h3><strong>赤ちゃん・お子様連れ歓迎</strong></h3><p>赤ちゃん・お子様連れ大歓迎です。<br>見守りスタッフも常駐しておりますので、<strong><u>ご家族でお気軽にご来場ください！</u></strong></p><p><br><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBODh4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--a73fb5311e1f0b00da3cd655e498cb97a0173a61/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/event_description_image_path3.jpeg\" alt=\"\" width=\"1440\" height=\"1080\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728311122813image.gif\" width=\"15\" height=\"15\"></span>​</p><p>​</p>', '<p>​</p><p>ご予約の上ご来場いただいた方に、<span style=\"color:#f39c12;\"><strong>ギフトカード5000円分</strong></span>をプレゼント！</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOHd4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--5805a112863be389595f187b55024cc40411edfb/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/announcement_image_path.jpeg\" alt=\"\" width=\"1440\" height=\"1080\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728311192832image.gif\" width=\"15\" height=\"15\"></span>​</p><p>​</p>', '設定しない', '2024-06-04 17:20:00', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (48, 2, '【サンプル】予約制完成見学会｜自然素材が心地よい家', '完成見学会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今', '3/16/2005', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172830939541860.jpeg,/imgs/events/172830941934461.png,/imgs/events/172830942700362.png,/imgs/events/172830943658863.png,/imgs/events/172830944331664.jpeg', 0, NULL, NULL, '<h3>​<strong>自然素材が心地よい家</strong></h3><p>&nbsp;</p><p>自然素材が心地よい家では、お客様のご要望を多数取り入れ、<br>心地よさとデザイン性を高次元で両立した家です。<br>&nbsp;<br>実際に触れて、見て、感じていただき、<br>新しい住まいについてのイメージを膨らませていただけます。<br>この機会に、ぜひご家族でお越しください。<br>&nbsp;<br>■お施主様の情報<br>・ご家族構成　ご夫婦、お子様1人<br>・敷地面積　〇〇〇.〇〇（〇〇坪）<br>・延床面性　〇〇〇.〇〇（〇〇坪）</p><p>&nbsp;</p><h3><strong>くつろげる広々リビング</strong></h3><p>&nbsp;</p><p>リビングはテレビや音響機器を設置して、好きな映画や音楽を楽しむスペースを。ホームシアターやステレオシステムを導入することで、くつろぎの時間が一層充実。またリビング、キッチンが一体化し、明るく広々とした空間を作っています。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOUl4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--24e9d345b100789e7266cdf2768cae410fe17a41/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaV2tDYkFJPSIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--051c3c6dc4c4ae37ab3e6d54202554899ecffbca/event_description_image_path6.png\" alt=\"\" width=\"1024\" height=\"768\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728309483050image.gif\" width=\"15\" height=\"15\"></span>​</p><h3><strong>すっきりした清潔なキッチン</strong></h3><p>&nbsp;</p><p>不必要なものを取り除き、シンプルなデザインに仕上げました。<br>カウンタートップや壁面にあまり物を置かず、必要最小限のアイテムで。<br>引き出しや戸棚、パントリーなどを効果的に使って収納を工夫しております。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOU14RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--1f4dc15e7986493257b2f447b04f3828bee71bee/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaV2tDYkFJPSIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--051c3c6dc4c4ae37ab3e6d54202554899ecffbca/event_description_image_path7.png\" alt=\"\" width=\"1024\" height=\"768\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728309483050image.gif\" width=\"15\" height=\"15\"></span>​</p><h3><strong>作業に集中できる仕事部屋</strong></h3><p>&nbsp;</p><p>自然光が取り入れられる明るく快適な仕事部屋。仕事に専念できるように、自分の好みや趣味を反映させたパーソナルスペースを実現。<br>落ち着いた色調や仕事に適したカラーパレットを選ぶことで、リラックス感をもたらし、集中力を向上させます。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOVF4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--f833fc5ace8d441fa5528b5da02800ccbe704e16/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaV2tDYkFJPSIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--051c3c6dc4c4ae37ab3e6d54202554899ecffbca/event_description_image_path8.png\" alt=\"\" width=\"1024\" height=\"768\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728309483050image.gif\" width=\"15\" height=\"15\"></span>​</p><h3><strong>完成見学会はお子様連れ歓迎</strong></h3><p>完成見学会はお子様連れのご家族も大歓迎！キッズスペースをご用意しておりますので、安心してご覧になれます。&nbsp;</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOUF4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--f775cfd060b2c207e62173c5115eee2c65ccab2b/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/event_description_image_path4.jpeg\" alt=\"\" width=\"1440\" height=\"1080\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728309483050image.gif\" width=\"15\" height=\"15\"></span>​</p><p>​</p>', NULL, '設定しない', '2024-06-04 17:20:00', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (49, 2, '【サンプル】※先着10組限定※500万円以上差が出る！住宅ローン相談会', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今', '3/16/2005', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172831108085165.jpeg,/imgs/events/172831108539866.png,/imgs/events/172831108902967.png,/imgs/events/172831109290368.jpeg,/imgs/events/172831109918269.jpeg', 0, NULL, NULL, '<h3>​<strong> ＼ 住宅ローン相談会を開催！／</strong><br>&nbsp;</h3><p>プロのお金の悩みを、プロのファイナンシャルプランナーから無料でご案内しています。住宅ローン控除や補助金を活用することで、<strong>家賃並みの支払いで一戸建てを購入できた方</strong>もいます。是非ご相談にお越しください。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBODB4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--4d711892180511f987e3e3751cc054ab4401b70b/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/event_description_image_path1.jpeg\" alt=\"\" width=\"620\" height=\"465\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728311122813image.gif\" width=\"15\" height=\"15\"></span>​</p><h3><strong>こんな人にお勧め&nbsp;</strong></h3><p><span style=\"background-color:#f1c40f;\"><strong>&nbsp;1&nbsp;</strong></span> 住宅購入を検討し始めたばかりで、お金のことについて知りたい<br>&nbsp;<br><span style=\"background-color:#f1c40f;\">&nbsp;<strong>2&nbsp;</strong></span> 少しでもお得に住宅ローンを組みたい<br>&nbsp;<br><span style=\"background-color:#f1c40f;\">&nbsp;<strong>3&nbsp;</strong></span>&nbsp;自分の年収で購入できる、家の金額を知りたい<br>&nbsp;<br><span style=\"background-color:#f1c40f;\">&nbsp;<strong>4&nbsp;</strong></span>&nbsp;住宅ローン控除の変更点をまだ知らない<br>&nbsp;<br><span style=\"background-color:#f1c40f;\">&nbsp;<strong>5&nbsp;</strong></span>&nbsp;家を建てたいけれど、教育費や旅行費も貯めたい</p><h3><strong>ファイナンシャルプランナーに相談できる</strong></h3><p>100組以上の資金計画の相談に乗ってきた、<span style=\"color:#f39c12;\"><strong>FP1級の資格を持つ担当</strong></span>にご相談いただけます。家族構成や、収入・支出に合わせた支払い計画の相談に乗らせていただきます。</p><p><br>&nbsp;<img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBODR4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--5a2a554c5e76b9309783f62504f025ac95d53920/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/event_description_image_path2.jpeg\" alt=\"\" width=\"620\" height=\"413\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728311122813image.gif\" width=\"15\" height=\"15\"></span>​<br>&nbsp;</p><p><strong>【担当プロフィール】</strong><br>・ビズ・クリエイション代表　・FP1級<br>・100組以上の資金計画の相談対応実績<br>※記入内容はイメージです</p><h3><strong>赤ちゃん・お子様連れ歓迎</strong></h3><p>赤ちゃん・お子様連れ大歓迎です。<br>見守りスタッフも常駐しておりますので、<strong><u>ご家族でお気軽にご来場ください！</u></strong></p><p><br><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBODh4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--a73fb5311e1f0b00da3cd655e498cb97a0173a61/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/event_description_image_path3.jpeg\" alt=\"\" width=\"1440\" height=\"1080\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728311122813image.gif\" width=\"15\" height=\"15\"></span>​</p><p>​</p>', '<h3><strong>ご来場特典</strong><br>&nbsp;</h3><p>ご予約の上ご来場いただいた方に、<span style=\"color:#f39c12;\"><strong>ギフトカード5000円分</strong></span>をプレゼント！</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOHd4RXc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--5805a112863be389595f187b55024cc40411edfb/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/announcement_image_path.jpeg\" alt=\"\" width=\"1440\" height=\"1080\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728311192832image.gif\" width=\"15\" height=\"15\"></span>​</p><p>​</p>', '設定しない', '2024-06-04 17:20:00', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (50, 3, '【サンプル】いくら借りれる?! 資金計画相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834408960370.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりの前から資金計画や住宅ローンのご相談を頂ける「資金計画相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>実績のある住まいのプロが住宅ローンや資金計画の悩みを解消致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物総額でいくらまでなら不安なく払えるのか知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分はいくら借りることが出来るのかローン金額を知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■大きな買い物なので色々相談したいけど、誰に聞けば良いのか分からない方</strong></span></p><p><span style=\"color:#000000;\">家づくりには大きなお金がかかります。だからこそ住宅ローンや資金計画についての不安や悩みは誰もが抱えています。</span></p><p><span style=\"color:#000000;\">住宅ローンの選択やその金利の検討、借入額の検討や毎月の支払額。建ててから後悔しない為に、失敗しない準備が大切です。</span></p><p><span style=\"color:#000000;\">ですが、誰に相談すればよいか分からない、特定の銀行に聞きに行ってもいいものなのか、、、</span></p><p><span style=\"color:#000000;\">そこで頼りになるのが、これまで多くの住宅建築に関わった私たち工務店です。</span></p><p><span style=\"color:#000000;\">私たちは、理想の住まいを実現するために住宅を設計し建築するのが仕事ですが、お客様からいつもお金の悩みも伺います。</span></p><p><span style=\"color:#000000;\">どの銀行にも属さない私たちだからこそ、お話しできることをお伝えし、不安を払拭して頂く為に相談会を開催しています。</span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅のプロがお客様の理想のイメージを元に総額をお答えします</strong></span></p><p><span style=\"color:#000000;\">家づくりの検討初期から銀行にローンの相談に行く方はほとんどいません。自分たちの理想の住まいがいくらくらいかかるか分からないからです。</span></p><p><span style=\"color:#000000;\">まずはお客様の理想の住まいのイメージ（立地や建築プラン、仕様等）を伺い、概算の総額をお答えします。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅ローンあっせんや保険加入が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">私たちは工務店として住宅建築を行う会社ですので、ローンのあっせんや生命保険のかけ替えによる利益はございません。</span></p><p><span style=\"color:#000000;\">お客様の不安が解消され、当社のプランを気に入って頂いた場合に限り、建築請負契約を締結しお仕事をさせて頂ければと思っております（もちろん強引な営業はいたしません）</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;これまで理想の住まいを実現された他の方の事例をご紹介します</strong></span></p><p><span style=\"color:#000000;\">お客様とご年齢や家族構成が近いお客様の事例をご紹介することができますので、その方々の総額や住宅ローンなどについても可能な限り共有させて頂くことが可能です。</span></p><p><span style=\"color:#000000;\">同じような不安を持たれたていた別のお客様の事例をお知りいただくことで、イメージが沸きやすくなると、大変好評です。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#2980b9;\"><strong>資金計画相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2023-12-14 13:44:35', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (51, 3, '【サンプル】一緒に探します！理想の土地探し相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834431370472.png,/imgs/events/172834432070071.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、土地探しから家づくりのご相談を頂ける「土地探し相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望の住まいに適した土地をご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物を一緒にご相談されたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■建売分譲等とは異なり、自分たちだけの理想の家を考えている方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:rgb(231,76,60);color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを共有しながら土地探しを無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社へご相談へお越しの7割以上が、土地探しからご相談頂くお客様です。</span></p><p><span style=\"color:#000000;\">エリア内の土地をご紹介できる不動会社と連携し、お客様に最適な土地をご提案してきた実績がございますので、是非まずはご予約の上ご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;不動産販売が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">土地探しからのご相談の場合でも、理想の住まいを建築させて頂くことを生業としているのが私たち工務店です。</span></p><p><span style=\"color:#000000;\">設計の視点も取り入れ、土地に理想の建築プランがしっかり納まるように、サポートさせて頂くことが可能です。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地は良くないかな？」と思う前に、まず私たちにご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。土地情報だけでなく、学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#e74c3c;\"><strong>土地探し相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2023-12-14 13:44:40', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (52, 3, '【サンプル】家族の理想の間取りプラン相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834467887973.png,/imgs/events/172834468434574.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりのご相談の一環としてる「間取りプラン相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望のイメージをもとにこれまで手掛けた間取り事例や３Dパースをご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■こんな土地だけどどんな間取りで建てればいいの？と考えている方</strong></span></p><p><span style=\"color:#000000;\"><strong>■地震に強い、性能の良い家ってどんな間取りなの？という方</strong></span></p><p><span style=\"color:#000000;\"><strong>■子育て・家事をスムーズにする間取りを知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■間取り設計の基本を知りたい方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを伺いながら間取り検討を無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社は工務店として多くのお客様の理想の住まいを叶えてきました。</span></p><p><span style=\"color:#000000;\">お客様の理想の暮らしのイメージをお教え頂きながら、事例をご覧頂いたり、手描きの間取りをお見せしたりしながら、イメージを固めるお手伝いをいたします。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;間取りプランニングは無料を行いますのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">プランニングをする段階で当社は費用を頂くことは一切ございません。</span></p><p><span style=\"color:#000000;\">ですが、お客様に理想の家を叶えて頂くため、一生懸命親身にお話しをお伺いさせて頂きますので、是非お気軽に相談会にお越しください。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地だったらどうだろう？」と思う土地がおありでしたら、是非物件資料をお持ちください。プランをご提案させて頂きます。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#16a085;\"><strong>間取りプラン相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2023-12-14 13:44:45', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (53, 3, '【サンプル】※先着10組限定※500万円以上差が出る！住宅ローン相談会', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834479659565.jpeg,/imgs/events/172834480105966.png,/imgs/events/172834480541067.png,/imgs/events/172834480899868.jpeg,/imgs/events/172834481227869.jpeg', 0, NULL, NULL, NULL, '<h3>​<strong> ご来場特典</strong><br>&nbsp;</h3><p>ご予約の上ご来場いただいた方に、<span style=\"color:#f39c12;\"><strong>ギフトカード5000円分</strong></span>をプレゼント！</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBMll2REE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--b0b1e6cfa3b64a4fca7424046f9f700e8cf8f715/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZwQW13QyIsImV4cCI6bnVsbCwicHVyIjoidmFyaWF0aW9uIn19--ac92b851ff4e1fffe1b2b9e91bdb7040e0599588/announcement_image1.jpeg\" alt=\"\" width=\"1440\" height=\"1080\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728344833967image.gif\" width=\"15\" height=\"15\"></span>​</p><p><br>&nbsp;</p><p>​</p>', '設定しない', '2023-12-22 18:40:00', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (54, 3, '【サンプル】予約制完成見学会｜自然素材が心地よい家', '完成見学会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834492942060.jpeg,/imgs/events/172834493331661.png,/imgs/events/172834493713562.png,/imgs/events/172834494197463.png,/imgs/events/172834494663264.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2023-12-22 18:40:04', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (55, 3, 'モデルハウス予約', '展示場', '予約制', '[{\"date\":\"2024-08-01\",\"time\":[600,1080]},{\"date\":\"2024-08-25\",\"time\":[600,1080]},{\"date\":\"2024-08-29\",\"time\":[600,1080]},{\"date\":\"2024-08-30\",\"time\":[600,1080]},{\"date\":\"2024-08-31\",\"time\":[600,1080]}]', '齋藤', '公開', 1, 0, '鹿児島県', '姶良市', NULL, '加治木町木田2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834511607575.png', 0, NULL, NULL, '<p>「ギネス世界記録・3年連続3部門認定」　　　　　　　　　世界に認められた”家づくりをご体感ください。</p>', '<p>展示場へのご来場は「ご来場予約」がおトクです</p><p>WEB予約でご来場＆クイズに答えてクオカード</p><p><strong><u>最大６０００円分進呈！！！！！</u></strong></p>', '設定しない', '2024-08-01 08:50:00', '2024-11-28 10:22:32', NULL, 1);
INSERT INTO `events` VALUES (56, 4, '【サンプル】いくら借りれる?! 資金計画相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834408960370.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりの前から資金計画や住宅ローンのご相談を頂ける「資金計画相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>実績のある住まいのプロが住宅ローンや資金計画の悩みを解消致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物総額でいくらまでなら不安なく払えるのか知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分はいくら借りることが出来るのかローン金額を知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■大きな買い物なので色々相談したいけど、誰に聞けば良いのか分からない方</strong></span></p><p><span style=\"color:#000000;\">家づくりには大きなお金がかかります。だからこそ住宅ローンや資金計画についての不安や悩みは誰もが抱えています。</span></p><p><span style=\"color:#000000;\">住宅ローンの選択やその金利の検討、借入額の検討や毎月の支払額。建ててから後悔しない為に、失敗しない準備が大切です。</span></p><p><span style=\"color:#000000;\">ですが、誰に相談すればよいか分からない、特定の銀行に聞きに行ってもいいものなのか、、、</span></p><p><span style=\"color:#000000;\">そこで頼りになるのが、これまで多くの住宅建築に関わった私たち工務店です。</span></p><p><span style=\"color:#000000;\">私たちは、理想の住まいを実現するために住宅を設計し建築するのが仕事ですが、お客様からいつもお金の悩みも伺います。</span></p><p><span style=\"color:#000000;\">どの銀行にも属さない私たちだからこそ、お話しできることをお伝えし、不安を払拭して頂く為に相談会を開催しています。</span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅のプロがお客様の理想のイメージを元に総額をお答えします</strong></span></p><p><span style=\"color:#000000;\">家づくりの検討初期から銀行にローンの相談に行く方はほとんどいません。自分たちの理想の住まいがいくらくらいかかるか分からないからです。</span></p><p><span style=\"color:#000000;\">まずはお客様の理想の住まいのイメージ（立地や建築プラン、仕様等）を伺い、概算の総額をお答えします。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅ローンあっせんや保険加入が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">私たちは工務店として住宅建築を行う会社ですので、ローンのあっせんや生命保険のかけ替えによる利益はございません。</span></p><p><span style=\"color:#000000;\">お客様の不安が解消され、当社のプランを気に入って頂いた場合に限り、建築請負契約を締結しお仕事をさせて頂ければと思っております（もちろん強引な営業はいたしません）</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;これまで理想の住まいを実現された他の方の事例をご紹介します</strong></span></p><p><span style=\"color:#000000;\">お客様とご年齢や家族構成が近いお客様の事例をご紹介することができますので、その方々の総額や住宅ローンなどについても可能な限り共有させて頂くことが可能です。</span></p><p><span style=\"color:#000000;\">同じような不安を持たれたていた別のお客様の事例をお知りいただくことで、イメージが沸きやすくなると、大変好評です。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#2980b9;\"><strong>資金計画相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2023-12-14 13:44:35', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (57, 4, '【サンプル】一緒に探します！理想の土地探し相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834431370472.png,/imgs/events/172834432070071.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、土地探しから家づくりのご相談を頂ける「土地探し相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望の住まいに適した土地をご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物を一緒にご相談されたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■建売分譲等とは異なり、自分たちだけの理想の家を考えている方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:rgb(231,76,60);color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを共有しながら土地探しを無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社へご相談へお越しの7割以上が、土地探しからご相談頂くお客様です。</span></p><p><span style=\"color:#000000;\">エリア内の土地をご紹介できる不動会社と連携し、お客様に最適な土地をご提案してきた実績がございますので、是非まずはご予約の上ご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;不動産販売が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">土地探しからのご相談の場合でも、理想の住まいを建築させて頂くことを生業としているのが私たち工務店です。</span></p><p><span style=\"color:#000000;\">設計の視点も取り入れ、土地に理想の建築プランがしっかり納まるように、サポートさせて頂くことが可能です。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地は良くないかな？」と思う前に、まず私たちにご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。土地情報だけでなく、学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#e74c3c;\"><strong>土地探し相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2023-12-14 13:44:40', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (58, 4, '【サンプル】家族の理想の間取りプラン相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834467887973.png,/imgs/events/172834468434574.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりのご相談の一環としてる「間取りプラン相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望のイメージをもとにこれまで手掛けた間取り事例や３Dパースをご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■こんな土地だけどどんな間取りで建てればいいの？と考えている方</strong></span></p><p><span style=\"color:#000000;\"><strong>■地震に強い、性能の良い家ってどんな間取りなの？という方</strong></span></p><p><span style=\"color:#000000;\"><strong>■子育て・家事をスムーズにする間取りを知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■間取り設計の基本を知りたい方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを伺いながら間取り検討を無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社は工務店として多くのお客様の理想の住まいを叶えてきました。</span></p><p><span style=\"color:#000000;\">お客様の理想の暮らしのイメージをお教え頂きながら、事例をご覧頂いたり、手描きの間取りをお見せしたりしながら、イメージを固めるお手伝いをいたします。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;間取りプランニングは無料を行いますのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">プランニングをする段階で当社は費用を頂くことは一切ございません。</span></p><p><span style=\"color:#000000;\">ですが、お客様に理想の家を叶えて頂くため、一生懸命親身にお話しをお伺いさせて頂きますので、是非お気軽に相談会にお越しください。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地だったらどうだろう？」と思う土地がおありでしたら、是非物件資料をお持ちください。プランをご提案させて頂きます。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#16a085;\"><strong>間取りプラン相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2023-12-14 13:44:45', '2024-10-29 10:18:43', NULL, 1);
INSERT INTO `events` VALUES (59, 4, '【サンプル】※先着10組限定※500万円以上差が出る！住宅ローン相談会', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834479659565.jpeg,/imgs/events/172834480105966.png,/imgs/events/172834480541067.png,/imgs/events/172834480899868.jpeg,/imgs/events/172834481227869.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2023-12-22 18:40:00', '2024-10-29 10:18:43', NULL, 1);
