INSERT INTO `events` VALUES (62, 4, '【サンプル】予約制完成見学会｜自然素材が心地よい家', '完成見学会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834492942060.jpeg,/imgs/events/172834493331661.png,/imgs/events/172834493713562.png,/imgs/events/172834494197463.png,/imgs/events/172834494663264.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2023-12-22 18:40:04', '2024-10-29 10:18:44', NULL, 1);
INSERT INTO `events` VALUES (63, 4, '【旭住宅】”木っずいす” 作り体験', 'モデルハウス', '予約制', '[{\"date\":\"2024-01-13\",\"time\":[600,1020]},{\"date\":\"2024-01-14\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '薩摩川内市', '天辰町329-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834668507172.jpg,/imgs/events/172834668929773.jpg,/imgs/events/172834669300574.jpg,/imgs/events/172834669678575.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 子育て, 木造住宅', '<p>​</p><p><strong>できるかな？　”木っずいす”&nbsp;</strong></p><p><strong>みんなでつくってみよう！</strong></p><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:620/434;\" src=\"/imgs/upload/172834687542776.jpg\" width=\"620\" height=\"434\"></figure><p>&nbsp;</p><p>～ お子様とご一緒に ”木っずいす” をつくってみませんか？ ～</p><p>自然素材に囲まれた空間で、</p><p>きれいな空気と木材の香りを感じながらお子様と一緒に楽しい工作を♪</p><p>旭住宅の「健康住宅」をぜひ体感してみてください。</p><p>【参加費無料】</p><p>・１家族様１脚限り</p><p>・家づくりをご検討中でアンケートご記入の方</p><p>・各日４組（２日間で８組限定）</p><p>開催日時：１月１３日（土）～１月１４日（日）</p><p>　　　　　１０：００　～　１７：００　※薩摩川内モデルにて開催</p><p>”木っずいす”作りは先着順とさせていただきます。事前にご予約をおすすめいたします。</p><p>見学の来場には予約は必要ありませんので、お気軽にお立ち寄りください。</p><p>​</p>', NULL, '設定しない', '2024-10-08 09:15:00', '2024-11-28 10:22:34', NULL, 1);
INSERT INTO `events` VALUES (64, 4, '【オーナーズハウス完成見学会】', 'モデルハウス', '予約制', '[{\"date\":\"2024-01-27\",\"time\":[600,1020]},{\"date\":\"2024-01-28\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', 'いちき串木野市', '大里（市来駅付近）', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834735808877.jpg,/imgs/events/172834736158178.jpg,/imgs/events/172834736611579.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 木造住宅, 完成見学会, オープンハウス', '<h4>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></h4><h4><span style=\"color:#27ae60;\"><strong>オーナーズハウス完成見学会　1/27-28</strong></span></h4><figure class=\"image\"><img style=\"aspect-ratio:1024/546;\" src=\"/imgs/upload/172834748088477.jpg\" width=\"1024\" height=\"546\"></figure><p>​</p><p>いちき串木野市大里にてオーナーズハウス完成見学会を開催いたします♬</p><p>今回の見学会場は今までの「健康住宅」とは一味違うお家となっております。</p><p>　<span style=\"color:#2980b9;\">°˖✧　みどころ　✧˖°</span></p><p>★屋根と外壁にガルバリウム鋼板を使用したスタイリッシュな外観</p><p>★柱が見えない工法（大壁工法）</p><p>★所々で木を現すことで、メリハリのあるおしゃれな空間</p><p>★ドアは既製品を使用し、大壁とも相まってモダンな雰囲気に！&nbsp;</p><p>★奥様こだわりのＬ型リビングダイニングはラクラク家事動線</p><p>★応接間には”黒の漆喰”を使用</p><p>普段の「健康住宅」の見学会では見られないポイントがたくさん詰まっているお宅です。</p><p>ぜひご来場して家づくりのご参考にしてください♪</p><p>開催日時：１月２７日（土）～２８日（日）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：いちき串木野市大里（市来駅付近）</p><p><a href=\"https://maps.app.goo.gl/N1ybF2uEM16DUjsa6\">https://maps.app.goo.gl/N1ybF2uEM16DUjsa6</a></p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>ご来場に予約は必要ありませんので、お気軽にお問い合わせください。</p><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:1024/683;\" src=\"/imgs/upload/172834753101678.jpg\" width=\"1024\" height=\"683\"></figure><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:1024/683;\" src=\"/imgs/upload/172834753676779.jpg\" width=\"1024\" height=\"683\"></figure><p><br>&nbsp;</p><p>​</p>', NULL, '設定しない', '2024-10-08 09:25:00', '2024-11-28 10:22:35', NULL, 1);
INSERT INTO `events` VALUES (65, 4, '【完成見学会】', '完成見学会', '予約制', '[{\"date\":\"2024-06-22\",\"time\":[600,1020]},{\"date\":\"2024-06-23\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '霧島市', '隼人町小田', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834779711980.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材,  自然素材, 子育て, 木造住宅, 完成見学会, きれいな空気, 平屋, 真壁づくり', '<h4>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></h4><h4><span style=\"color:#27ae60;\"><strong>完成見学会　6/22 - 6/23</strong></span></h4><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:620/311;\" src=\"/imgs/upload/172834792493981.jpg\" width=\"620\" height=\"311\"></figure><p>霧島市隼人町小田にて完成見学会を開催いたします♬</p><p>今回は家事がしやすい動線の4ＬＤＫの平屋となっております。</p><p>　<span style=\"color:#2980b9;\">°˖✧　みどころ　✧˖°</span></p><p>★家族みんなが集まるリビングは開放的で広々空間。</p><p>★リビングにつながる癒しの和室。</p><p>★おしゃれな造作洗面台。</p><p>★家事がしやすい動線にゆったりと使える水回り。</p><p>ぜひ、来場して体感してみてください。</p><p>開催日時：６月２２日（土）～２３日（日）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：霧島市隼人町小田</p><p>https://maps.app.goo.gl/YFsBUFdN1wYnPdHq7</p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>また、ご来場に予約は必要ございませんので、お気軽にお立ち寄りください。</p><p>​</p>', NULL, '設定しない', '2024-10-08 09:34:00', '2024-11-28 10:22:35', NULL, 1);
INSERT INTO `events` VALUES (66, 4, '【オーナーズハウス完成見学会】', '完成見学会', '予約制', '[{\"date\":\"2024-02-17\",\"time\":[600,1020]},{\"date\":\"2024-02-18\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '阿久根市', '赤瀬川（ヤマダ電機テックランド阿久根店様付近）', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172835017368782.jpg,/imgs/events/172835017768983.jpg,/imgs/events/172835018132784.jpg,/imgs/events/172835018502485.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 子育て, 木造住宅, 完成見学会, オープンハウス', '<h4>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></h4><h4><span style=\"color:#27ae60;\"><strong>オーナーズハウス完成見学会　2/17-18</strong></span></h4><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:620/878;\" src=\"/imgs/upload/172835032369686.jpg\" width=\"620\" height=\"878\"></figure><figure class=\"image\"><img style=\"aspect-ratio:620/930;\" src=\"/imgs/upload/172835033552787.jpg\" width=\"620\" height=\"930\"></figure><p>​</p><p>阿久根市赤瀬川にてオーナーズハウス完成見学会を開催いたします♬</p><p>今回は阿久根大島や東シナ海を一望できる岡の上に建つ４LDKのお宅になります。</p><p>°˖✧　みどころ　✧˖°</p><p>★「陶器瓦」の落ち着いた屋根</p><p>★「幻の漆喰そとかべ」で仕上げたオリジナリティあふれる外観</p><p>★プライベート空間のダイニングルームと、来客が予想されるリビングルームを完全に区分けした間取りでストレスフリー</p><p>★約５メートルもある吹き抜け天井のあるリビング</p><p>★ダイニングからの海の眺めは最高！</p><p>眺めの良いウッドデッキで、海を見ながらおしゃべりしたり、本を読んだり、お酒を交わしたり…。</p><p>ぜひご来場して体感してみてください。</p><p>開催日時：２月１７日（土）～２月１８日（日）</p><p>　　　　　１０：００　～　１７：００</p><p>開催場所：阿久根市赤瀬川（ヤマダ電機テックランド阿久根店様付近）</p><p>https://maps.app.goo.gl/xx4bh78UzZP4t6rj7</p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>また、見学会の来場には予約は必要ありませんので、お気軽にお問い合わせください。</p><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:620/878;\" src=\"/imgs/upload/172835034888888.jpg\" width=\"620\" height=\"878\"></figure><p>​</p><p><br>&nbsp;</p><p>​</p>', NULL, '設定しない', '2024-10-08 10:10:00', '2024-11-28 10:22:36', NULL, 1);
INSERT INTO `events` VALUES (67, 4, '【2/23・2/24・2/25 完成見学会】', '完成見学会', '予約制', '[{\"date\":\"2024-02-23\",\"time\":[600,1020]},{\"date\":\"2024-02-24\",\"time\":[600,1020]},{\"date\":\"2024-02-25\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', 'いちき串木野市', '上名2966-1付近', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172835069658001.jpeg,/imgs/events/172835070689002.jpg,/imgs/events/172835071085603.jpg,/imgs/events/172835071473104.jpg,/imgs/events/172835071814605.jpg', 0, NULL, '健康住宅,  音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 子育て, 木造住宅, 完成見学会, きれいな空気', '<p>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></p><h4><span style=\"color:#27ae60;\"><strong>オーナーズハウス完成見学会　2/23 - 2/25</strong></span></h4><figure class=\"image\"><img style=\"aspect-ratio:620/686;\" src=\"/imgs/upload/172835080220306.jpg\" width=\"620\" height=\"686\"></figure><p>​​</p><figure class=\"image\"><img style=\"aspect-ratio:620/877;\" src=\"/imgs/upload/172835083999107.jpg\" width=\"620\" height=\"877\"></figure><p>いちき串木野市上名にてオーナーズハウス完成見学会を3日間開催いたします♬</p><p>今回は大きい勾配天井の広々ゆったり暮らせる5LDKの健康住宅です。</p><p>　<span style=\"color:#2980b9;\">°˖✧　みどころ　✧˖°</span></p><p>★幻の漆喰で仕上げた外壁</p><p>★本物の木を張ることで高級感のある外観の玄関</p><p>★勾配天井で開放的なLDK</p><p>★音響熟成木材の黒を使用した和室</p><p>★お施主様こだわり！収納の多さがポイント！</p><p>無駄のない間取り、音響熟成木材の香り、幻の漆喰でつくる心地良い空気。</p><p>健康住宅の魅力を最大限に感じていただけるお家となっていますので、ぜひご来場して体感してみてください。</p><p>開催日時：２月２３日（金）～２５日（日）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：いちき串木野市上名2966-1付近</p><p>https://maps.app.goo.gl/aaS6f9kwRGFv72fd8</p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>また、ご来場に予約は必要ございませんので、お気軽にお立ち寄りください。</p><figure class=\"image\"><img style=\"aspect-ratio:1024/683;\" src=\"/imgs/upload/172835085534203.jpg\" width=\"1024\" height=\"683\"></figure><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:1024/683;\" src=\"/imgs/upload/172835086219405.jpg\" width=\"1024\" height=\"683\"></figure><p><br>&nbsp;</p><p>​</p>', NULL, '設定しない', '2024-10-08 10:20:00', '2024-11-28 10:22:36', NULL, 1);
INSERT INTO `events` VALUES (68, 4, '【オーナーズハウス完成見学会】', '完成見学会', '予約制', '[{\"date\":\"2024-03-09\",\"time\":[600,1020]},{\"date\":\"2024-03-10\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '出水市', '下鯖町274-11付近', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172835120848708.png,/imgs/events/172835121218009.png,/imgs/events/172835121749410.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 子育て, 木造住宅, 完成見学会, オープンハウス, きれいな空気, 平屋', '<p>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></p><h4><span style=\"color:#27ae60;\"><strong>オーナーズハウス完成見学会　3/9 - 3/10</strong></span></h4><figure class=\"image\"><img style=\"aspect-ratio:620/675;\" src=\"/imgs/upload/172835130117911.png\" width=\"620\" height=\"675\"></figure><p>出水市下鯖町にてオーナーズハウス完成見学会を開催いたします♬</p><p>今回はお二人暮らしの「シンプルかつ暮らしやすい」3LDKの健康住宅です。</p><p>　<span style=\"color:#2980b9;\">°˖✧　みどころ　✧˖°</span></p><p>★雨に濡れない広々としたインナーガレージ</p><p>★お子様連れのベビーカーや、将来車いすが必要になった時に便利なスロープの玄関まわり</p><p>★「くるくる動線」を意識し家事も効率的でラクラク</p><p>★洗面脱衣室には折り畳み作業台があり、洗う→干す→畳むが全て完結</p><p>無駄のない間取りで、花粉が少しずつ増加しているこの時期こそ、健康住宅の良さを実感していただけると思いますので、ぜひご来場して体感してみてください。</p><p>開催日時：３月９日（土）～１０日（日）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：出水市下鯖町274-11付近</p><p>https://maps.app.goo.gl/BWK7EpmxfUWMRA5Q7</p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>また、ご来場に予約は必要ございませんので、お気軽にお立ち寄りください。</p><figure class=\"image\"><img style=\"aspect-ratio:620/321;\" src=\"/imgs/upload/172835142129512.png\" width=\"620\" height=\"321\"></figure><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:912/768;\" src=\"/imgs/upload/172835142576110.jpg\" width=\"912\" height=\"768\"></figure><p>​</p><p><br>&nbsp;</p><p>​</p>', NULL, '設定しない', '2024-10-08 10:29:00', '2024-11-28 10:22:37', NULL, 1);
INSERT INTO `events` VALUES (69, 4, '【 鹿児島市 】オーナーズハウス見学会', '完成見学会', '予約制', '[{\"date\":\"2024-04-06\",\"time\":[600,1020]},{\"date\":\"2024-04-07\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '鹿児島市', '石谷町（石谷簡易郵便局から車で２分）', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172835175394911.jpg,/imgs/events/172835175775412.jpg,/imgs/events/172835176110013.jpg,/imgs/events/172835176459114.jpg,/imgs/events/172835176855915.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 子育て, 木造住宅, 完成見学会, オープンハウス, きれいな空気, 平屋', '<p>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></p><h4><span style=\"color:#27ae60;\"><strong>オーナーズハウス完成見学会　4/6 - 4/7</strong></span></h4><figure class=\"image\"><img style=\"aspect-ratio:620/878;\" src=\"/imgs/upload/172835190842816.jpg\" width=\"620\" height=\"878\"></figure><p>鹿児島市石谷町にてオーナーズハウス完成見学会を開催いたします♬</p><p>今回のお宅は、左官職人が丹精込めて仕上げた「幻の漆喰そとかべ」の光り輝く外観が目に飛び込んでくる、３LDKの平屋のお家です。</p><p>　<span style=\"color:#2980b9;\">°˖✧　みどころ　✧˖°</span></p><p>★幻の漆喰で仕上げた外壁</p><p>★広々とした土間スペースには趣味のアウトドア用品を収納</p><p>★ペットバスも土間スペースに完備しており、ワンちゃん達も快適生活♪</p><p>★タイルと照明がかわいいオリジナル洗面化粧台</p><p>★お客様と何度も何度も打合せをして決めたキッチン周り</p><p>ご夫婦のこだわりがつまった、見どころ満載のお家となっております。</p><p>開催日時：４月６日（土）～７日（日）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：鹿児島市石谷町（石谷簡易郵便局から車で２分）</p><p><a href=\"https://maps.app.goo.gl/JQtdxsx1AGzGibkF7\">https://maps.app.goo.gl/JQtdxsx1AGzGibkF7</a></p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>また、ご来場に予約は必要ございませんので、お気軽にお立ち寄りください。</p><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:620/296;\" src=\"/imgs/upload/172835193560917.jpg\" width=\"620\" height=\"296\"></figure><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:620/620;\" src=\"/imgs/upload/172835194141118.jpg\" width=\"620\" height=\"620\"></figure><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:1024/682;\" src=\"/imgs/upload/172835195088912.jpg\" width=\"1024\" height=\"682\"></figure><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172835195672815.jpg\" width=\"1024\" height=\"768\"></figure><p><br>&nbsp;</p><p>​</p>', NULL, '設定しない', '2024-10-08 10:38:00', '2024-11-28 10:22:38', NULL, 1);
INSERT INTO `events` VALUES (70, 4, '【GWイベント】木っずいすプレゼント＆構造見学会', '構造見学会', '予約制', '[{\"date\":\"2024-05-03\",\"time\":[600,1020]},{\"date\":\"2024-05-04\",\"time\":[600,1020]},{\"date\":\"2024-05-05\",\"time\":[600,1020]},{\"date\":\"2024-05-06\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '薩摩川内市', '天辰町329-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172836727374619.jpg,/imgs/events/172836727949520.jpg,/imgs/events/172836728369421.jpg,/imgs/events/172836729509774.jpg,/imgs/events/172836730351622.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 子育て, 木造住宅, きれいな空気, 平屋, 二世帯住宅, 構造見学会', '<h4><span style=\"color:hsl(0, 0%, 0%);\">​<strong> 「木っずいす」プレゼント＆構造見学会イベント開催</strong></span></h4><p><strong>​</strong></p><figure class=\"image\"><img style=\"aspect-ratio:620/775;\" src=\"/imgs/upload/172836741866523.jpg\" width=\"620\" height=\"775\"></figure><p>薩摩川内モデルハウスにて「木っずいす」プレゼント?＆構造見学会を開催いたします♬</p><p>モデルハウスと一緒に、隣で建築中のお宅も見学できるお得な4日間となっています✨</p><p>°˖✧　イベント内容　✧˖°</p><p>★薩摩川内モデルハウス</p><p>　モデルハウスを見学された方に「木っずいす」をプレゼント?</p><p>　※今回初めてのご来場の方で、次回打合せのご予約をいただけた方</p><p>★構造見学会</p><p>　普段は見ることのできない家づくりの構造部分。</p><p>　家づくりの「キホン」となるとても大事な骨格部分をご覧いただけます。</p><p>開催日時：５月３日（金）～５月６日（月）</p><p>　　　　　１０：００　～　１７：００</p><p>開催場所：薩摩川内市天辰町３２９-１</p><p>https://maps.app.goo.gl/bqDbGvYviAdFnuWC7</p><p>ご来場に予約は必要ございませんので、お気軽にお立ち寄りください。</p><p>皆様のご来場お待ちしております。</p><p>会場近くではアイタウンにて「うきうきフェア」も開催されています。</p><p>お近くにお越しの際は薩摩川内モデルハウスの木の香りでゆっくりお寛ぎください。</p><figure class=\"image\"><img style=\"aspect-ratio:1024/717;\" src=\"/imgs/upload/172836744414721.jpg\" width=\"1024\" height=\"717\"></figure><p>​</p><p>​</p>', NULL, '設定しない', '2024-10-08 14:57:00', '2024-11-28 10:22:38', NULL, 1);
INSERT INTO `events` VALUES (71, 4, '【完成見学会】', '完成見学会', '予約制', '[{\"date\":\"2024-06-22\",\"time\":[600,1020]},{\"date\":\"2024-06-23\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '薩摩川内市', '青山町', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172834779711980.jpg', 0, NULL, NULL, '<h4>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></h4><h4><span style=\"color:#27ae60;\"><strong>完成見学会　6/22 - 6/23</strong></span></h4><p>​</p><figure class=\"image\"><img style=\"aspect-ratio:620/498;\" src=\"/imgs/upload/172836814579024.jpg\" width=\"620\" height=\"498\"></figure><p>薩摩川内市青山町にて完成見学会を開催いたします♬</p><p>今回はプライベートエリアと来客エリアをきっちり分けて過ごしやすく、すっきりした間取りの平屋となっております。</p><p>　<span style=\"color:#2980b9;\">°˖✧　みどころ　✧˖°</span></p><p>★寄棟の屋根が機能性と趣を演出。</p><p>★ご夫婦の趣味である音楽室は音漏れにも配慮して、内壁にもサーモウールを施工。</p><p>★通路を兼ねたフリースペースがとっても便利。</p><p>★こだわりの手造り木製洗面化粧台は必見！</p><p>★車を降りてほぼ濡れずに軒の深い玄関へ…ストレスフリー。</p><p>ご夫婦のこだわりがいっぱいの見どころ満載のお家となっております。</p><p>開催日時：６月２２日（土）～２３日（日）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：薩摩川内市青山町</p><p><a href=\"https://maps.app.goo.gl/42AAWMYvjgoAT3am8\">https://maps.app.goo.gl/42AAWMYvjgoAT3am8</a></p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>また、ご来場に予約は必要ございませんので、お気軽にお立ち寄りください。</p>', NULL, '設定しない', '2024-10-08 09:34:00', '2024-11-28 10:22:39', NULL, 1);
INSERT INTO `events` VALUES (72, 4, '新ブランド 「 イシンスタイル　モデルハウス」 グランドオープン', 'モデルハウス', '予約制', '[{\"date\":\"2024-07-13\",\"time\":[600,1020]},{\"date\":\"2024-07-14\",\"time\":[600,1020]},{\"date\":\"2024-07-15\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '姶良市', '松原町２丁目28-18', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172836854142025.jpg,/imgs/events/172836854533326.jpg,/imgs/events/172836854897927.jpg', 0, NULL, '木造住宅, モデルハウスグランドオープン, 駐車場有り, 家事動線, 長期優良住宅 , 耐震等級3, 高気密, 高断熱, デザイン住宅, 省エネ住宅, 住宅ローン相談可', '<h4>​<span style=\"color:#e74c3c;\"><strong> 新ブランド 「イシンスタイル モデルハウス」</strong></span></h4><h4><span style=\"color:#e74c3c;\"><strong>GRAND　OPEN！</strong></span>　<span style=\"color:#e74c3c;\"><strong>7/13 - 7/15</strong></span></h4><p>姶良市松原町にてイシンスタイルモデルハウスがついにグランドオープン☆</p><p>7/13-7/15の期間、来場イベントを開催いたします♬</p><figure class=\"image\"><img style=\"aspect-ratio:620/877;\" src=\"/imgs/upload/172836859684328.jpg\" width=\"620\" height=\"877\"></figure><p>​</p><p>今回のモデルハウスのコンセプトは、「広々としたLDKで就寝時までしっかり体を休められる家」となっております。</p><p>　<span style=\"color:#2980b9;\">°˖✧　みどころ　✧˖°</span></p><p>★無駄のないデザイン重視の30坪の平屋。</p><p>★小上がりの寝室は漆喰仕上げ。</p><p>★寝室からは坪庭が眺められ、日々の疲れを癒してくれます。</p><p>★家事動線がスムーズ。</p><p>★余裕ができた時間でリラックスができる間取り。</p><p><span style=\"color:#e74c3c;\"><strong>来場特典</strong></span></p><p>特典１　500円QUOカードプレゼント</p><p>　　　　※インスタフォロー・LINE登録・メルアド登録を全てされた方</p><p>特典２　銀座ブルーミッシュグランリュクスプレゼント</p><p>　　　　※電話・ネット・SNS（インスタDM）からご予約してご来場の方</p><p>開催日時：７月１３日（土）～１５日（月）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：姶良市松原町２丁目２８－１８</p><p><a href=\"https://maps.app.goo.gl/9NaRLpEq2HQ8eZAc6\">https://maps.app.goo.gl/9NaRLpEq2HQ8eZAc6</a></p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>また、見学会の来場にはご予約は必要ありませんので、お気軽にお立ち寄りください。</p><p>&nbsp;</p>', NULL, '設定しない', '2024-10-08 15:17:00', '2024-11-28 10:22:41', NULL, 1);
INSERT INTO `events` VALUES (73, 4, '旭住宅　＜完成見学会＞', '完成見学会', '予約制', '[{\"date\":\"2024-07-20\",\"time\":[600,1020]},{\"date\":\"2024-07-21\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '薩摩川内市', '宮崎町', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172836909214129.jpg,/imgs/events/172836909539330.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 木造住宅, 完成見学会, きれいな空気, 平屋, 真壁づくり', '<h4>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></h4><h4><span style=\"color:#27ae60;\"><strong>完成見学会　7/20 - 7/21</strong></span></h4><figure class=\"image\"><img style=\"aspect-ratio:1024/514;\" src=\"/imgs/upload/172836912235630.jpg\" width=\"1024\" height=\"514\"></figure><h4>​<span style=\"color:#27ae60;\"><strong>◎存在感抜群！ドンと構える７寸柱がある平屋</strong></span></h4><p>☑高い勾配天井のLDK+和室で家族みんなが集まっても広々！</p><p>☑ご主人こだわりの和室の天井には、焼杉を使って「ほっ」と落ち着ける空間に。</p><p>☑コンパクトな敷地でありながら、設計の工夫でゆったりした平屋暮らしを実現。</p><p>☑アウトドア好きなご夫婦のための広々外部倉庫。</p><p>☑軒が深く濡れないウッドデッキでアウトドアライフを快適に楽しめます♪</p><p>開催日時：７月２０日（土）～２１日（日）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：薩摩川内市宮崎町（はんえいラーメンさん付近）</p><p>https://maps.app.goo.gl/XuJ5XcM2pxYDjbBK6</p><p>&nbsp;</p><p>当日は会場近隣の案内看板をたよりに安全運転でご来場ください。</p><p>また、ご来場に予約は必要ございませんので、お気軽にお立ち寄りください。</p><p><br>&nbsp;</p><p>​</p>', NULL, '設定しない', '2024-10-08 15:26:00', '2024-11-28 10:22:42', NULL, 1);
INSERT INTO `events` VALUES (74, 4, '旭住宅　＜完成見学会＞', '完成見学会', '予約制', '[{\"date\":\"2024-07-27\",\"time\":[600,1020]},{\"date\":\"2024-07-28\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '薩摩川内市', '東郷町鳥丸', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172836940540731.jpg,/imgs/events/172836941275732.jpeg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 木造住宅, 完成見学会, きれいな空気, 平屋, 真壁づくり', '<h4>​<span style=\"color:#27ae60;\"><strong> 【旭住宅】</strong></span></h4><h4><span style=\"color:#27ae60;\"><strong>完成見学会　7/2７ - 7/2８</strong></span></h4><figure class=\"image\"><img style=\"aspect-ratio:1024/516;\" src=\"/imgs/upload/172836945249732.jpeg\" width=\"1024\" height=\"516\"></figure><p><img src=\"/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBMkZJRkE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--d8736009b318f59e7d5b72b5b621430b740d5d26/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lKYW5CbFp3WTZCa1ZVT2d0eVpYTnBlbVZKSWdnMk1qQUdPd1pVIiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--cae4cf997c4b45657d922f95ccb952d155f2701c/%E5%AE%87%E9%83%BD%E7%BF%94%E4%BA%BA%E6%A7%98%E3%83%BB%E6%99%BA%E7%B5%B5%E6%A7%98%E9%82%B8-1-1024x516%E9%B3%A5%E4%B8%B8.jpeg\" alt=\"\">​</p><p><span style=\"color:#27ae60;\"><strong>◎緑いっぱい、開放感いっぱいの、</strong></span></p><p><span style=\"color:#27ae60;\"><strong>　先祖から受け継いだ土地に建つ４LDKのゆったりした平屋</strong></span></p><p>☑玄関入口の丸窓と、玄関ホールの間接照明が和モダンの雰囲気に。</p><p>☑フルオープンのリビングサッシでさらに開放的。</p><p>☑ご主人こだわりの和室には音響熟成木材「黒」を使用。</p><p>☑奥様こだわりのランドリールームはみどころ満載！</p><p>☑大きめの造作洗面化粧台は複数人でもストレスフリー。</p><p>開催日時：７月２７日（土）～２８日（日）</p><p>　　　　　１０：００～１７：００</p><p>開催場所：薩摩川内市東郷町鳥丸</p><p>https://maps.app.goo.gl/XzzbtAtYVE3ms8zHA</p><p>&nbsp;</p><p>健康住宅の芳醇な木の香り、すっきりした空気、気持ちの良い肌触りをぜひ体感しにお越しください。</p><p>また、ご来場に予約は必要ございませんので、お気軽にお立ち寄りください。</p><p><br>&nbsp;</p><p>​</p>', NULL, '設定しない', '2024-10-08 15:33:00', '2024-11-28 10:22:42', NULL, 1);
INSERT INTO `events` VALUES (75, 4, '旭住宅　薩摩川内モデルハウス', 'モデルハウス', '予約制', '[{\"date\":\"2024-01-11\",\"time\":[600,1020]},{\"date\":\"2024-12-01\",\"time\":[600,1020]},{\"date\":\"2024-12-02\",\"time\":[600,1020]},{\"date\":\"2024-12-03\",\"time\":[600,1020]},{\"date\":\"2024-12-05\",\"time\":[600,1020]},{\"date\":\"2024-12-06\",\"time\":[600,1020]},{\"date\":\"2024-12-07\",\"time\":[600,1020]},{\"date\":\"2024-12-08\",\"time\":[600,1020]},{\"date\":\"2024-12-09\",\"time\":[600,1020]},{\"date\":\"2024-12-10\",\"time\":[600,1020]},{\"date\":\"2024-12-12\",\"time\":[600,1020]},{\"date\":\"2024-12-13\",\"time\":[600,1020]},{\"date\":\"2024-12-14\",\"time\":[600,1020]},{\"date\":\"2024-12-15\",\"time\":[600,1020]},{\"date\":\"2024-12-16\",\"time\":[600,1020]},{\"date\":\"2024-12-17\",\"time\":[600,1020]},{\"date\":\"2024-12-19\",\"time\":[600,1020]},{\"date\":\"2024-12-20\",\"time\":[600,1020]},{\"date\":\"2024-12-21\",\"time\":[600,1020]},{\"date\":\"2024-12-22\",\"time\":[600,1020]},{\"date\":\"2024-12-23\",\"time\":[600,1020]},{\"date\":\"2024-12-24\",\"time\":[600,1020]},{\"date\":\"2024-12-26\",\"time\":[600,1020]},{\"date\":\"2024-12-27\",\"time\":[600,1020]},{\"date\":\"2024-12-28\",\"time\":[600,1020]},{\"date\":\"2024-12-29\",\"time\":[600,1020]},{\"date\":\"2024-12-30\",\"time\":[600,1020]},{\"date\":\"2024-12-31\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '薩摩川内市', '天辰町329-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172836977567832.jpg,/imgs/events/172836977994433.jpg,/imgs/events/172836978343134.jpg,/imgs/events/172836978673135.jpg,/imgs/events/172836979076136.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 木造住宅', '<p>素材にこだわった旭住宅の「健康住宅」</p><p>空気の違いをぜひご体感ください。</p>', NULL, '設定しない', '2024-10-08 15:38:00', '2024-11-28 10:22:43', NULL, 1);
INSERT INTO `events` VALUES (76, 4, '至福の平屋。＜完成見学会＞', '完成見学会', 'オープン制', '[{\"date\":\"2024-08-31\",\"time\":[600,1020]},{\"date\":\"2024-09-01\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '霧島市', '溝辺町麓', '2279-2', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172836997475937.jpg', 0, NULL, '健康住宅, 幻の漆喰, 自然素材, 平屋, 薪ストーブ', '<p>8/31(土)、9/1(日)の二日間、霧島市溝辺町麓にて完成見学会を開催します。</p><p>&nbsp;</p><p>今回の住まいは、薪ストーブのある和モダンの寄棟平屋。<br>忙しい日々の中でも、窓から見える贅沢な風景がほっと一息つける、くつろぎの時間を演出します。</p><p>&nbsp;</p><p>休日は薪割りをしたり、工作したり、車をいじったり、リビングで家族とくつろいだり。<br>自然を眺めながら、自然を愛でながら、家族が癒やされる幸せなひと時を。</p><p>&nbsp;</p><p>家族の暮らしの移り変わりにもしっかり寄り添える、永く住み継ぐ平屋のお家です。</p><p>&nbsp;</p><p>普段の暮らしをいちばんの贅沢に。<br>旭住宅とお客様で、心地よい空間と暮らしをとことん追求した住まい。</p><p>&nbsp;</p><p>みなさんの住まいづくりの参考になると思いますので、是非ご来場下さい。</p>', NULL, '設定しない', '2024-10-08 15:44:00', '2024-11-28 10:22:48', NULL, 1);
INSERT INTO `events` VALUES (77, 4, '旭住宅　展示場モデルハウス「源」', 'モデルハウス', '予約制', '[{\"date\":\"2024-09-06\",\"time\":[600,1020]},{\"date\":\"2025-01-28\",\"time\":[600,1020]},{\"date\":\"2025-01-30\",\"time\":[600,1020]},{\"date\":\"2025-01-31\",\"time\":[600,1020]},{\"date\":\"2025-02-01\",\"time\":[600,1020]},{\"date\":\"2025-02-02\",\"time\":[600,1020]},{\"date\":\"2025-02-03\",\"time\":[600,1020]},{\"date\":\"2025-02-04\",\"time\":[600,1020]},{\"date\":\"2025-02-06\",\"time\":[600,1020]},{\"date\":\"2025-02-07\",\"time\":[600,1020]},{\"date\":\"2025-02-08\",\"time\":[600,1020]}]', NULL, '公開', 0, 0, '鹿児島県', '姶良市', '加治木町木田2515-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837032481338.jpg,/imgs/events/172837033036239.jpg,/imgs/events/172837033394740.jpg,/imgs/events/172837033805841.jpg,/imgs/events/172837034193642.jpg,/imgs/events/172837034514743.jpg,/imgs/events/172837034828444.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 木造住宅', '<p>素材にこだわった旭住宅の「健康住宅」</p><p>空気の違いをぜひご体感ください。</p>', NULL, '設定しない', '2024-10-08 15:48:00', '2024-11-28 10:22:44', NULL, 1);
INSERT INTO `events` VALUES (78, 4, '旭住宅の新ブランド～ishin style～', 'モデルハウス', '予約制', '[{\"date\":\"2024-10-08\",\"time\":[600,1020]},{\"date\":\"2024-10-10\",\"time\":[600,1020]},{\"date\":\"2024-10-11\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '姶良市松原町２丁目28-18', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837603807145.jpg', 0, NULL, NULL, '<p>旭住宅の考えた新ブランド<br>その名も・・・<br>「ishin style」<br><br>こだわりの性能や断熱を是非体感しにお越しください！！</p>', '<p>ご予約の方に５００円のQUOカードプレゼント！<br>インスタフォロー・アンケート記入でさらに500円QUOカードプレゼント実施中です！</p>', '設定しない', '2024-10-08 15:53:00', '2024-11-28 10:22:52', NULL, 1);
INSERT INTO `events` VALUES (79, 4, '＜完成見学会＞ゆるやかにつながる平屋。', '完成見学会', '予約制', '[{\"date\":\"2024-10-12\",\"time\":[600,1020]},{\"date\":\"2024-10-13\",\"time\":[600,1020]},{\"date\":\"2024-10-14\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '薩摩川内市', '隈之城町', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837642442446.jpg,/imgs/events/172837642827647.jpg,/imgs/events/172837643282948.jpg', 0, NULL, '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 木造住宅, 完成見学会, オープンハウス, きれいな空気, 平屋', '<h4><span style=\"color:hsl(0, 0%, 0%);\">​<strong>【薩摩川内市隈之城町】</strong></span></h4><h4><span style=\"color:hsl(0, 0%, 0%);\"><strong>～ゆるやかにつながる平屋～</strong></span></h4><p>&nbsp;</p><p>10/12(土)～14(月祝)の3日間、薩摩川内市隈之城町にて完成見学会を開催します。</p><p>今回の住まいは、どこにいても家族のつながりを感じられる、落ち着きのある寄棟平屋。</p><p>気持ちの良い景色を眺めながら癒される、幸せなひと時を。<br>家族の暮らしの変化にもしっかり寄り添える、永く住み継ぐ平屋のお家です。</p><p>旭住宅とお客様で、心地よい空間と暮らしをとことん追求した住まい。</p><p>みなさんの住まいづくりの参考になると思いますので、是非ご来場下さい。</p><p>&nbsp;</p><p><strong>みどころ</strong></p><p><strong>■幻の漆喰「そとかべ」をつかった手仕上げの美しい外壁。</strong><br><strong>■キッチンから見える南側の気持ちの良い景色。</strong><br><strong>■勝手口に繋がるカーポートは、雨に濡れず移動できてストレスフリー。</strong><br><strong>■暮らしに合わせて使いやすい、平屋ならではの間取り。</strong></p><p>&nbsp;</p><figure class=\"image\"><img style=\"aspect-ratio:620/413;\" src=\"/imgs/upload/172837649666049.png\" width=\"620\" height=\"413\"></figure><p>※写真は薩摩川内モデルの一部です。</p><p>&nbsp;</p><p>健康住宅の芳醇な木の香り、すっきりした空気、気持ちの良い肌触りをぜひご体感ください。<br>皆様のご来場を心よりお待ちしております。</p><p>​</p>', NULL, '設定しない', '2024-10-08 17:29:00', '2024-11-02 00:51:58', NULL, 1);
INSERT INTO `events` VALUES (80, 6, '【サンプル】いくら借りれる?! 資金計画相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837990302570.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりの前から資金計画や住宅ローンのご相談を頂ける「資金計画相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>実績のある住まいのプロが住宅ローンや資金計画の悩みを解消致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物総額でいくらまでなら不安なく払えるのか知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分はいくら借りることが出来るのかローン金額を知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■大きな買い物なので色々相談したいけど、誰に聞けば良いのか分からない方</strong></span></p><p><span style=\"color:#000000;\">家づくりには大きなお金がかかります。だからこそ住宅ローンや資金計画についての不安や悩みは誰もが抱えています。</span></p><p><span style=\"color:#000000;\">住宅ローンの選択やその金利の検討、借入額の検討や毎月の支払額。建ててから後悔しない為に、失敗しない準備が大切です。</span></p><p><span style=\"color:#000000;\">ですが、誰に相談すればよいか分からない、特定の銀行に聞きに行ってもいいものなのか、、、</span></p><p><span style=\"color:#000000;\">そこで頼りになるのが、これまで多くの住宅建築に関わった私たち工務店です。</span></p><p><span style=\"color:#000000;\">私たちは、理想の住まいを実現するために住宅を設計し建築するのが仕事ですが、お客様からいつもお金の悩みも伺います。</span></p><p><span style=\"color:#000000;\">どの銀行にも属さない私たちだからこそ、お話しできることをお伝えし、不安を払拭して頂く為に相談会を開催しています。</span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅のプロがお客様の理想のイメージを元に総額をお答えします</strong></span></p><p><span style=\"color:#000000;\">家づくりの検討初期から銀行にローンの相談に行く方はほとんどいません。自分たちの理想の住まいがいくらくらいかかるか分からないからです。</span></p><p><span style=\"color:#000000;\">まずはお客様の理想の住まいのイメージ（立地や建築プラン、仕様等）を伺い、概算の総額をお答えします。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅ローンあっせんや保険加入が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">私たちは工務店として住宅建築を行う会社ですので、ローンのあっせんや生命保険のかけ替えによる利益はございません。</span></p><p><span style=\"color:#000000;\">お客様の不安が解消され、当社のプランを気に入って頂いた場合に限り、建築請負契約を締結しお仕事をさせて頂ければと思っております（もちろん強引な営業はいたしません）</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;これまで理想の住まいを実現された他の方の事例をご紹介します</strong></span></p><p><span style=\"color:#000000;\">お客様とご年齢や家族構成が近いお客様の事例をご紹介することができますので、その方々の総額や住宅ローンなどについても可能な限り共有させて頂くことが可能です。</span></p><p><span style=\"color:#000000;\">同じような不安を持たれたていた別のお客様の事例をお知りいただくことで、イメージが沸きやすくなると、大変好評です。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#2980b9;\"><strong>資金計画相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:31:00', '2024-10-29 10:18:44', NULL, 1);
INSERT INTO `events` VALUES (81, 6, '【サンプル】一緒に探します！理想の土地探し相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837999542172.png,/imgs/events/172838000251571.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、土地探しから家づくりのご相談を頂ける「土地探し相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望の住まいに適した土地をご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物を一緒にご相談されたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■建売分譲等とは異なり、自分たちだけの理想の家を考えている方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:rgb(231,76,60);color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを共有しながら土地探しを無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社へご相談へお越しの7割以上が、土地探しからご相談頂くお客様です。</span></p><p><span style=\"color:#000000;\">エリア内の土地をご紹介できる不動会社と連携し、お客様に最適な土地をご提案してきた実績がございますので、是非まずはご予約の上ご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;不動産販売が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">土地探しからのご相談の場合でも、理想の住まいを建築させて頂くことを生業としているのが私たち工務店です。</span></p><p><span style=\"color:#000000;\">設計の視点も取り入れ、土地に理想の建築プランがしっかり納まるように、サポートさせて頂くことが可能です。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地は良くないかな？」と思う前に、まず私たちにご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。土地情報だけでなく、学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#e74c3c;\"><strong>土地探し相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:33:00', '2024-10-29 10:18:44', NULL, 1);
INSERT INTO `events` VALUES (82, 6, '【サンプル】家族の理想の間取りプラン相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838005477173.png,/imgs/events/172838005854374.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりのご相談の一環としてる「間取りプラン相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望のイメージをもとにこれまで手掛けた間取り事例や３Dパースをご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■こんな土地だけどどんな間取りで建てればいいの？と考えている方</strong></span></p><p><span style=\"color:#000000;\"><strong>■地震に強い、性能の良い家ってどんな間取りなの？という方</strong></span></p><p><span style=\"color:#000000;\"><strong>■子育て・家事をスムーズにする間取りを知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■間取り設計の基本を知りたい方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを伺いながら間取り検討を無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社は工務店として多くのお客様の理想の住まいを叶えてきました。</span></p><p><span style=\"color:#000000;\">お客様の理想の暮らしのイメージをお教え頂きながら、事例をご覧頂いたり、手描きの間取りをお見せしたりしながら、イメージを固めるお手伝いをいたします。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;間取りプランニングは無料を行いますのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">プランニングをする段階で当社は費用を頂くことは一切ございません。</span></p><p><span style=\"color:#000000;\">ですが、お客様に理想の家を叶えて頂くため、一生懸命親身にお話しをお伺いさせて頂きますので、是非お気軽に相談会にお越しください。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地だったらどうだろう？」と思う土地がおありでしたら、是非物件資料をお持ちください。プランをご提案させて頂きます。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#16a085;\"><strong>間取りプラン相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:34:00', '2024-10-29 10:18:44', NULL, 1);
INSERT INTO `events` VALUES (83, 6, '株式会社ウッドペッカー 【 BEBE AND BUDDY 】', '展示場', 'オープン制', '[{\"date\":\"2022-04-23\",\"time\":[600,1020]},{\"date\":\"2022-04-24\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1 スマイルビルダーズ 内', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838772674549.jpg', 0, NULL, NULL, '<h3>株式会社ウッドペッカー　グランドオープンイベント！！</h3><h3>POP UP STORE【 <strong>BEBE AND BUDDY</strong> 】</h3><p>本社にて、愛犬のお洋服やおもちゃ等販売している</p><p>「 BEBE AND BUDDY &nbsp;」べべアンドバディ</p><p>モデルハウス入口にて、<span style=\"color:#9b59b6;\">4/23・4/24 2日間限定</span>オープン致します。</p><p>こども服を１点ずつリメイクした、他にはないアイテムに出会えます❤︎</p><p>当日は、インスタグラムで人気のドライブベットも販売予定!!</p><p>弊社をご見学されたお客様限定で、ドックランをご利用できます。</p><p>愛犬とご一緒にお待ちしています。</p><p><a href=\"https://www.instagram.com/bebebuddy2020/\"><span style=\"color:#3498db;\">BEBE AND BUDDY</span></a></p>', NULL, '設定しない', '2024-10-08 18:35:00', '2024-11-28 10:23:05', NULL, 1);
INSERT INTO `events` VALUES (84, 6, '【サンプル】※先着10組限定※500万円以上差が出る！住宅ローン相談会', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838793856965.jpeg,/imgs/events/172838794269566.png,/imgs/events/172838794645567.png,/imgs/events/172838795032468.jpeg,/imgs/events/172838795534169.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2024-10-08 20:44:00', '2024-10-29 10:18:44', NULL, 1);
INSERT INTO `events` VALUES (85, 6, '【サンプル】予約制完成見学会｜自然素材が心地よい家', '完成見学会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838804708560.jpeg,/imgs/events/172838805171461.png,/imgs/events/172838805571162.png,/imgs/events/172838805948963.png,/imgs/events/172838806471364.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2024-10-08 20:46:00', '2024-10-29 10:18:44', NULL, 1);
INSERT INTO `events` VALUES (86, 6, '株式会社ウッドペッカー　展示場モデルハウス『路地裏』', '展示会', '予約制', '[{\"date\":\"2024-10-10\",\"time\":[600,1020]},{\"date\":\"2024-10-11\",\"time\":[600,1020]},{\"date\":\"2024-10-12\",\"time\":[600,1020]},{\"date\":\"2024-10-13\",\"time\":[600,1020]},{\"date\":\"2024-10-14\",\"time\":[600,1020]},{\"date\":\"2025-01-28\",\"time\":[600,1020]},{\"date\":\"2025-01-29\",\"time\":[600,1020]},{\"date\":\"2025-01-30\",\"time\":[600,1020]},{\"date\":\"2025-01-31\",\"time\":[600,1020]},{\"date\":\"2025-02-01\",\"time\":[600,1020]},{\"date\":\"2025-02-02\",\"time\":[600,1020]},{\"date\":\"2025-02-03\",\"time\":[600,1020]},{\"date\":\"2025-02-04\",\"time\":[600,1020]},{\"date\":\"2025-02-05\",\"time\":[600,1020]},{\"date\":\"2025-02-06\",\"time\":[600,1020]},{\"date\":\"2025-02-07\",\"time\":[600,1020]},{\"date\":\"2025-02-08\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838824461650.jpg,/imgs/events/172838824842251.jpg,/imgs/events/172838825206552.jpeg', 0, NULL, '20代向け, 30代向け, 40代向け, 夫婦+子供, 3K/DK/LDK, 4K/DK/LDK, ガレージあり, 2,000万円～2,500万円, 2,500万円～3,000万円, 木造住宅, デザイン住宅, 住宅ローン相談可, 南欧スタイル, ヴィンテージ, 免震住宅, 制震住宅, 耐震住宅', '<p>遊びごころ満載のモデルハウス！！</p><p>え～何ここ！！見たことない！！</p><p>他とは違う空間をぜひ体験してください！！</p>', NULL, '設定しない', '2024-10-08 20:48:00', '2024-11-28 10:23:06', NULL, 1);
INSERT INTO `events` VALUES (87, 9, '【サンプル】一緒に探します！理想の土地探し相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837999542172.png,/imgs/events/172838000251571.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、土地探しから家づくりのご相談を頂ける「土地探し相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望の住まいに適した土地をご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物を一緒にご相談されたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■建売分譲等とは異なり、自分たちだけの理想の家を考えている方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:rgb(231,76,60);color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを共有しながら土地探しを無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社へご相談へお越しの7割以上が、土地探しからご相談頂くお客様です。</span></p><p><span style=\"color:#000000;\">エリア内の土地をご紹介できる不動会社と連携し、お客様に最適な土地をご提案してきた実績がございますので、是非まずはご予約の上ご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;不動産販売が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">土地探しからのご相談の場合でも、理想の住まいを建築させて頂くことを生業としているのが私たち工務店です。</span></p><p><span style=\"color:#000000;\">設計の視点も取り入れ、土地に理想の建築プランがしっかり納まるように、サポートさせて頂くことが可能です。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地は良くないかな？」と思う前に、まず私たちにご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。土地情報だけでなく、学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#e74c3c;\"><strong>土地探し相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:33:00', '2024-10-29 10:18:45', NULL, 1);
INSERT INTO `events` VALUES (88, 9, '【サンプル】家族の理想の間取りプラン相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838005477173.png,/imgs/events/172838005854374.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりのご相談の一環としてる「間取りプラン相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望のイメージをもとにこれまで手掛けた間取り事例や３Dパースをご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■こんな土地だけどどんな間取りで建てればいいの？と考えている方</strong></span></p><p><span style=\"color:#000000;\"><strong>■地震に強い、性能の良い家ってどんな間取りなの？という方</strong></span></p><p><span style=\"color:#000000;\"><strong>■子育て・家事をスムーズにする間取りを知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■間取り設計の基本を知りたい方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを伺いながら間取り検討を無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社は工務店として多くのお客様の理想の住まいを叶えてきました。</span></p><p><span style=\"color:#000000;\">お客様の理想の暮らしのイメージをお教え頂きながら、事例をご覧頂いたり、手描きの間取りをお見せしたりしながら、イメージを固めるお手伝いをいたします。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;間取りプランニングは無料を行いますのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">プランニングをする段階で当社は費用を頂くことは一切ございません。</span></p><p><span style=\"color:#000000;\">ですが、お客様に理想の家を叶えて頂くため、一生懸命親身にお話しをお伺いさせて頂きますので、是非お気軽に相談会にお越しください。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地だったらどうだろう？」と思う土地がおありでしたら、是非物件資料をお持ちください。プランをご提案させて頂きます。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#16a085;\"><strong>間取りプラン相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:34:00', '2024-10-29 10:18:45', NULL, 1);
INSERT INTO `events` VALUES (89, 9, '後悔しないための賢い家づくり勉強会', '勉強会', '予約制', '[{\"date\":\"2023-10-01\",\"time\":[780,960]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511　スマイルビルダーズ住宅総合展示場　クオリティホームモデルハウス内', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838884900552.jpg', 0, NULL, NULL, '<h3 style=\"text-align:center;\"><span style=\"color:#f39c12;\">後悔しないための</span><br><span style=\"color:#f39c12;\">賢い家づくり勉強会</span></h3><p>R+house鹿児島南より、毎回好評いただいております<br>「賢い家づくり勉強会」開催のご案内です。</p><p>☆参加特典☆<br>・ご参加いただいた皆様に</p><p>　「個性をカタチに、賢い家づくり。」ブックをプレゼント！<br>・じゃんけん大会で１位になられたお客様には</p><p>　「スターバックスコーヒー商品券」を贈呈！</p><p>家づくりが「まだまだ」の人も「そろそろ」の人も。</p><p>家づくりをする前に知っておいた方がいい内容となっております。</p><p>毎回大変ご好評を頂いている勉強会ですのでぜひお気軽にご参加ください！</p>', NULL, '設定しない', '2024-10-08 20:59:00', '2024-11-28 10:23:07', NULL, 1);
INSERT INTO `events` VALUES (90, 9, '《姶良市加治木町》完成見学会', '完成見学会', '予約制', '[{\"date\":\"2023-09-09\",\"time\":[600,1020]},{\"date\":\"2023-09-10\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838902143953.jpg', 0, NULL, NULL, '<h3 style=\"text-align:center;\"><span style=\"color:#f39c12;\">完成見学会</span></h3><h4><span style=\"color:#f1c40f;\">姶良市加治木町に、カッコイイお家が完成しました☆</span></h4><p>R+house鹿児島南・霧島姶良より、完成見学会のご案内です。</p><p>今回、お施主様のご厚意により、完成見学会を開催することになりました！</p><p>夏は涼しく、冬は暖かい「高気密・高断熱」の高性能住宅をぜひご体感ください。</p><p>また、パッシブデザイン等を考え抜かれたアトリエ建築家のデザイン力にも注目です！</p>', NULL, '設定しない', '2024-10-08 21:02:00', '2024-11-28 10:23:08', NULL, 1);
INSERT INTO `events` VALUES (91, 9, '【サンプル】※先着10組限定※500万円以上差が出る！住宅ローン相談会', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838793856965.jpeg,/imgs/events/172838794269566.png,/imgs/events/172838794645567.png,/imgs/events/172838795032468.jpeg,/imgs/events/172838795534169.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2024-10-08 20:44:00', '2024-10-29 10:18:45', NULL, 1);
INSERT INTO `events` VALUES (92, 9, '【サンプル】予約制完成見学会｜自然素材が心地よい家', '完成見学会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838804708560.jpeg,/imgs/events/172838805171461.png,/imgs/events/172838805571162.png,/imgs/events/172838805948963.png,/imgs/events/172838806471364.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2024-10-08 20:46:00', '2024-10-29 10:18:45', NULL, 1);
INSERT INTO `events` VALUES (93, 9, '後悔しないための賢い家づくり勉強会', '勉強会', '予約制', '[{\"date\":\"2024-02-04\",\"time\":[780,900]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', NULL, '加治木町木田2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838935321254.jpg,/imgs/events/172838935735655.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 高気密・高断熱, 高性能住宅', '<p style=\"text-align:center;\"><span style=\"background-color:#f39c12;\"><strong>後悔しないための賢い家づくり勉強会</strong></span></p><p style=\"text-align:center;\"><strong>まだまだの人も、そろそろの人も</strong></p><p style=\"text-align:center;\"><strong>後悔しないために知っておいてもらいたい…</strong></p><p style=\"text-align:center;\"><strong>こんなことを勉強できます！</strong></p><p style=\"text-align:center;\"><strong>◎10年後に後悔しないためのチェックポイント</strong></p><p style=\"text-align:center;\"><strong>◎お得にお家を建てる方法</strong></p><p style=\"text-align:center;\"><strong>◎マイホーム購入のタイミング　　などなど…</strong></p><p style=\"text-align:center;\"><strong>住宅コンサルタントの方が、今のお家づくりについて分かりやすく解説いたします！</strong></p><p style=\"text-align:center;\"><strong>皆さまにとって、お家づくりに大切な一つのものさしを見つけてください！</strong></p>', '<p>◎抽選でスターバックス商品券プレゼント！</p><p>◎参加者全員に、「暮らしやすい家づくりアイデアbook100」をプレゼント！</p>', '設定しない', '2024-10-08 21:07:00', '2024-11-28 10:23:09', NULL, 1);
INSERT INTO `events` VALUES (94, 9, 'お金の知識を身につける３０分集中セミナー（無料）', 'セミナー', '予約制', NULL, NULL, '非公開', 0, 0, '鹿児島県', '姶良市', '加治木町木田', '2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838956812670.png,/imgs/events/172838957870856.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 夫婦+子供, 夫婦のみ, 2,000万円～2,500万円, 2,500万円～3,000万円, 3,000万円～3,500万円, 3,500万円～4,000万円, 住宅ローン相談可, 補助金相談可', '<p><span style=\"color:#000000;\">みなさんこんにちは。クオリティホームです。</span></p><p><span style=\"color:#000000;\">毎週末【マイホーム検討のためのお金の知識を身につける３０分集中セミナー】を姶良住宅総合展示場スマイルビルダーズのクオリティホームモデルハウス内にて開催します！</span></p><p><span style=\"color:#000000;\">（動画セミナーとなっております）</span></p><p><br><strong>※別のお時間や平日のご希望がありましたらお気軽にお申し付けください。</strong></p><hr><p><span style=\"color:#2ecc71;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物総額でいくらまでなら不安なく払えるのか知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分はいくら借りることが出来るのかローン金額を知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分たちの「適正予算」ってどれくらいなんだろう？</strong></span></p><p><span style=\"color:#000000;\"><strong>■大きな買い物なので色々相談したいけど、誰に聞けば良いのか分からない方</strong></span></p><p><span style=\"color:#000000;\">家づくりには大きなお金がかかります。だからこそ住宅ローンや資金計画についての不安や悩みは誰もが抱えています。</span></p><p><span style=\"color:#000000;\">住宅ローンの選択やその金利の検討、借入額の検討や毎月の支払額。建ててから後悔しない為に、失敗しない準備が大切です。</span></p><p><span style=\"color:#000000;\">お家づくりを進めていくうえでとても大事な『お金のこと』を聞いてみませんか？</span></p><p><span style=\"color:#2980b9;\"><strong>資金計画相談会は随時受付中。お気軽にお声掛けください。</strong></span></p>', NULL, '設定しない', '2024-10-08 21:11:00', '2024-10-29 10:18:45', NULL, 1);
INSERT INTO `events` VALUES (95, 9, '株式会社クオリティホーム　展示場モデルハウス', '展示会', '予約制', '[{\"date\":\"2024-10-10\",\"time\":[600,1020]},{\"date\":\"2024-10-11\",\"time\":[600,1020]},{\"date\":\"2024-10-12\",\"time\":[600,1020]},{\"date\":\"2024-10-13\",\"time\":[600,1020]},{\"date\":\"2024-10-14\",\"time\":[600,1020]},{\"date\":\"2024-11-01\",\"time\":[600,1020]},{\"date\":\"2024-11-02\",\"time\":[600,1020]},{\"date\":\"2024-11-03\",\"time\":[600,1020]},{\"date\":\"2024-11-04\",\"time\":[600,1020]},{\"date\":\"2024-11-05\",\"time\":[600,1020]},{\"date\":\"2024-11-07\",\"time\":[600,1020]},{\"date\":\"2024-11-08\",\"time\":[600,1020]},{\"date\":\"2024-11-09\",\"time\":[600,1020]},{\"date\":\"2024-11-10\",\"time\":[600,1020]},{\"date\":\"2024-11-11\",\"time\":[600,1020]},{\"date\":\"2024-11-12\",\"time\":[600,1020]},{\"date\":\"2024-11-14\",\"time\":[600,1020]},{\"date\":\"2024-11-15\",\"time\":[600,1020]},{\"date\":\"2024-11-16\",\"time\":[600,1020]},{\"date\":\"2024-11-17\",\"time\":[600,1020]},{\"date\":\"2024-11-18\",\"time\":[600,1020]},{\"date\":\"2024-11-19\",\"time\":[600,1020]},{\"date\":\"2024-11-21\",\"time\":[600,1020]},{\"date\":\"2024-11-22\",\"time\":[600,1020]},{\"date\":\"2024-11-23\",\"time\":[600,1020]},{\"date\":\"2024-11-24\",\"time\":[600,1020]},{\"date\":\"2024-11-25\",\"time\":[600,1020]},{\"date\":\"2024-11-26\",\"time\":[600,1020]},{\"date\":\"2024-11-28\",\"time\":[600,1020]},{\"date\":\"2024-11-29\",\"time\":[600,1020]},{\"date\":\"2024-11-30\",\"time\":[600,1020]}]', NULL, '公開', 1, 1, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838991771657.jpg,/imgs/events/172838992118358.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 住宅ローン相談可, 補助金相談可, 平屋, 建築家住宅, デザイン住宅, 高気密・高断熱, 高性能住宅, 省エネ住宅, 健康住宅', '<h4><span style=\"background-color:hsl(0, 0%, 100%);color:hsl(0, 0%, 0%);\"><strong>CONNECTING HOUSE</strong>～自然と、自然に、豊かに暮らす～</span></h4><p>緑の木々を抜けた柔らかな風が吹き込み、温かな太陽の陽ざしが差し込む室内。<br>窓を開けて、自然の恩恵をたっぷり取り入れてみよう。</p><p>庭と室内の空間が直接的、間接的に絡み合う設計により、家族の気配がどこにいても感じられ、だんらんの場所やプライベート空間も全てが庭とつながる豊かな暮らしが、ここにはあります。</p><p>これから始まる新しい生活スタイル様式に様々な変化を与えていく、新しい住まいのカタチ。</p><p>庭で育った採れたての野菜をキッチンで料理し、疲れた体をお風呂で癒しながら紅葉に目を向け、シンボルツリーの桜が咲く頃には庭でお花見をしたりと、家での家族時間が我が家の思い出と共に作られていくことでしょう。</p><p>さらに、自然エネルギーを最大限に活かしたパッシブデザイン。太陽の光、熱、そして風といったこれからの未来の暮らしを考え自然と上手につながりながら、住宅の性能（気密性・断熱性・耐震性）を両立することが人々の暮らしを支え最も重要で大切な家づくりだと考えています。</p>', NULL, '設定しない', '2024-10-08 21:14:00', '2024-11-28 10:23:11', NULL, 1);
INSERT INTO `events` VALUES (96, 11, '【サンプル】いくら借りれる?! 資金計画相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837990302570.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりの前から資金計画や住宅ローンのご相談を頂ける「資金計画相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>実績のある住まいのプロが住宅ローンや資金計画の悩みを解消致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物総額でいくらまでなら不安なく払えるのか知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分はいくら借りることが出来るのかローン金額を知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■大きな買い物なので色々相談したいけど、誰に聞けば良いのか分からない方</strong></span></p><p><span style=\"color:#000000;\">家づくりには大きなお金がかかります。だからこそ住宅ローンや資金計画についての不安や悩みは誰もが抱えています。</span></p><p><span style=\"color:#000000;\">住宅ローンの選択やその金利の検討、借入額の検討や毎月の支払額。建ててから後悔しない為に、失敗しない準備が大切です。</span></p><p><span style=\"color:#000000;\">ですが、誰に相談すればよいか分からない、特定の銀行に聞きに行ってもいいものなのか、、、</span></p><p><span style=\"color:#000000;\">そこで頼りになるのが、これまで多くの住宅建築に関わった私たち工務店です。</span></p><p><span style=\"color:#000000;\">私たちは、理想の住まいを実現するために住宅を設計し建築するのが仕事ですが、お客様からいつもお金の悩みも伺います。</span></p><p><span style=\"color:#000000;\">どの銀行にも属さない私たちだからこそ、お話しできることをお伝えし、不安を払拭して頂く為に相談会を開催しています。</span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅のプロがお客様の理想のイメージを元に総額をお答えします</strong></span></p><p><span style=\"color:#000000;\">家づくりの検討初期から銀行にローンの相談に行く方はほとんどいません。自分たちの理想の住まいがいくらくらいかかるか分からないからです。</span></p><p><span style=\"color:#000000;\">まずはお客様の理想の住まいのイメージ（立地や建築プラン、仕様等）を伺い、概算の総額をお答えします。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅ローンあっせんや保険加入が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">私たちは工務店として住宅建築を行う会社ですので、ローンのあっせんや生命保険のかけ替えによる利益はございません。</span></p><p><span style=\"color:#000000;\">お客様の不安が解消され、当社のプランを気に入って頂いた場合に限り、建築請負契約を締結しお仕事をさせて頂ければと思っております（もちろん強引な営業はいたしません）</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;これまで理想の住まいを実現された他の方の事例をご紹介します</strong></span></p><p><span style=\"color:#000000;\">お客様とご年齢や家族構成が近いお客様の事例をご紹介することができますので、その方々の総額や住宅ローンなどについても可能な限り共有させて頂くことが可能です。</span></p><p><span style=\"color:#000000;\">同じような不安を持たれたていた別のお客様の事例をお知りいただくことで、イメージが沸きやすくなると、大変好評です。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#2980b9;\"><strong>資金計画相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:31:00', '2024-10-29 10:18:45', NULL, 1);
INSERT INTO `events` VALUES (97, 11, '【サンプル】一緒に探します！理想の土地探し相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837999542172.png,/imgs/events/172838000251571.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、土地探しから家づくりのご相談を頂ける「土地探し相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望の住まいに適した土地をご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物を一緒にご相談されたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■建売分譲等とは異なり、自分たちだけの理想の家を考えている方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:rgb(231,76,60);color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを共有しながら土地探しを無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社へご相談へお越しの7割以上が、土地探しからご相談頂くお客様です。</span></p><p><span style=\"color:#000000;\">エリア内の土地をご紹介できる不動会社と連携し、お客様に最適な土地をご提案してきた実績がございますので、是非まずはご予約の上ご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;不動産販売が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">土地探しからのご相談の場合でも、理想の住まいを建築させて頂くことを生業としているのが私たち工務店です。</span></p><p><span style=\"color:#000000;\">設計の視点も取り入れ、土地に理想の建築プランがしっかり納まるように、サポートさせて頂くことが可能です。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地は良くないかな？」と思う前に、まず私たちにご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。土地情報だけでなく、学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#e74c3c;\"><strong>土地探し相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:33:00', '2024-10-29 10:18:45', NULL, 1);
INSERT INTO `events` VALUES (98, 11, '【サンプル】家族の理想の間取りプラン相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838005477173.png,/imgs/events/172838005854374.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりのご相談の一環としてる「間取りプラン相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望のイメージをもとにこれまで手掛けた間取り事例や３Dパースをご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■こんな土地だけどどんな間取りで建てればいいの？と考えている方</strong></span></p><p><span style=\"color:#000000;\"><strong>■地震に強い、性能の良い家ってどんな間取りなの？という方</strong></span></p><p><span style=\"color:#000000;\"><strong>■子育て・家事をスムーズにする間取りを知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■間取り設計の基本を知りたい方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを伺いながら間取り検討を無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社は工務店として多くのお客様の理想の住まいを叶えてきました。</span></p><p><span style=\"color:#000000;\">お客様の理想の暮らしのイメージをお教え頂きながら、事例をご覧頂いたり、手描きの間取りをお見せしたりしながら、イメージを固めるお手伝いをいたします。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;間取りプランニングは無料を行いますのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">プランニングをする段階で当社は費用を頂くことは一切ございません。</span></p><p><span style=\"color:#000000;\">ですが、お客様に理想の家を叶えて頂くため、一生懸命親身にお話しをお伺いさせて頂きますので、是非お気軽に相談会にお越しください。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地だったらどうだろう？」と思う土地がおありでしたら、是非物件資料をお持ちください。プランをご提案させて頂きます。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#16a085;\"><strong>間取りプラン相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:34:00', '2024-10-29 10:18:45', NULL, 1);
INSERT INTO `events` VALUES (99, 11, '【サンプル】※先着10組限定※500万円以上差が出る！住宅ローン相談会', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838793856965.jpeg,/imgs/events/172838794269566.png,/imgs/events/172838794645567.png,/imgs/events/172838795032468.jpeg,/imgs/events/172838795534169.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2024-10-08 20:44:00', '2024-10-29 10:18:45', NULL, 1);
