INSERT INTO `events` VALUES (102, 5, 'NEOデザインホーム姶良支店　利益還元　住まいづくり決算フェア', '展示会', '予約制', '[{\"date\":\"2022-09-10\",\"time\":[600,1080]},{\"date\":\"2022-09-11\",\"time\":[600,1080]},{\"date\":\"2022-09-12\",\"time\":[600,1080]},{\"date\":\"2022-09-13\",\"time\":[600,1080]},{\"date\":\"2022-09-15\",\"time\":[600,1080]},{\"date\":\"2022-09-16\",\"time\":[600,1080]},{\"date\":\"2022-09-17\",\"time\":[600,1080]},{\"date\":\"2022-09-18\",\"time\":[600,1080]},{\"date\":\"2022-09-19\",\"time\":[600,1080]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1　スマイルビルダーズ内', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172839376878070.jpg', 0, NULL, NULL, '<p>​</p><figure class=\"image image_resized\" style=\"width:20.22%;\"><img style=\"aspect-ratio:1074/224;\" src=\"/imgs/upload/172839382314650.png\" width=\"1074\" height=\"224\"></figure><p style=\"text-align:center;\"><span style=\"background-color:#f1c40f;color:#000000;\"><strong>利益還元　住まいづくり決算フェア</strong></span><span style=\"color:#d35400;\"><strong>　</strong></span><strong>を行います！</strong></p><p><strong>イベント期間：9/10（土）～9/19（祝・月）　10時～18時</strong></p><p>　　　　　　　　　　※9/14（水）は定休日です</p><p>★&nbsp;<span style=\"color:#c0392b;\"><strong>来場特典も多数ご用意&nbsp;</strong></span>★</p><p><strong>【ご来場特典①】</strong></p><p><strong>土・日・祝　限定！　</strong><span style=\"color:#c0392b;\"><strong>ハコスのパンセット</strong></span><strong>?　　　（各日　8組）</strong></p><p><strong>　　平日　　限定！　</strong><span style=\"color:#c0392b;\"><strong>マックカード　1,000円分</strong></span><strong>?（各日　3組）</strong></p><p><strong>【ご来場特典➁】</strong></p><p>　　　<strong>お子様限定！　</strong><span style=\"color:#c0392b;\"><strong>お菓子の詰め合わせ</strong></span><strong>プレゼント</strong>?<strong>（お一人様 １袋限り）</strong></p><p><strong>&nbsp;さらに、ご見学・ご来場アンケートへご協力いただいた方には、</strong></p><p><span style=\"color:#c0392b;\"><strong>&nbsp;空きくじなしのお楽しみ抽選会</strong></span><strong>をフェア期間中、毎日開催✨　</strong></p><p><span style=\"background-color:#f1c40f;color:#000000;\"><strong>◆NEOデザインホームの公式ホームページからの事前予約がお得です！！</strong></span></p><p>　NEOデザインホームの<span style=\"color:#c0392b;\"><strong>公式ホームページ</strong></span>からご予約いただいたお客様に限り、</p><p>　<span style=\"color:#c0392b;\"><strong>最大5,000円分</strong></span>のアマゾンギフト券をプレゼント！！</p><p>　※前日13時までにNEOデザインホーム公式HPより、ご来場予約された方が対象となります</p><p>　　<u>スマイルビルダーズHPからの来場予約は対象外</u>となります</p><p>　※また、初めてNEOデザインホームへご来場いただく方に限ります</p><p>（予約来場：2,000円＋事前アンケート：1,000円＋ご家族でのご来場：1,000円＋</p><p>　プラン提案、事前審査：1,000円分）</p><p><span style=\"color:#000000;\"><strong>　こちらをクリック</strong>▶</span><a href=\"https://neo-dhome.com/\"><span style=\"color:#c0392b;\"><strong>NEOデザインホーム　公式ホームページ</strong></span></a></p><p><span style=\"color:#000000;\"><strong>　是非、ご家族お揃いでご来場下さい?　</strong></span></p><p>　※全ての特典には限りがございますので、なくなり次第終了とさせていただきます。<br>&nbsp;</p>', NULL, '設定しない', '2024-10-08 22:19:00', '2024-11-28 10:23:14', NULL, 1);
