INSERT INTO `events` VALUES (104, 5, '3店舗合同　NEOデザインホーム１周年感謝祭', 'モデルハウス', '予約制', '[{\"date\":\"2022-10-08\",\"time\":[600,1080]},{\"date\":\"2022-10-09\",\"time\":[600,1080]},{\"date\":\"2022-10-10\",\"time\":[600,1080]},{\"date\":\"2022-10-11\",\"time\":[600,1080]},{\"date\":\"2022-10-12\",\"time\":[600,1080]},{\"date\":\"2022-10-13\",\"time\":[600,1080]},{\"date\":\"2022-10-14\",\"time\":[600,1080]},{\"date\":\"2022-10-15\",\"time\":[600,1080]},{\"date\":\"2022-10-16\",\"time\":[600,1080]},{\"date\":\"2022-10-17\",\"time\":[600,1080]},{\"date\":\"2022-10-18\",\"time\":[600,1080]},{\"date\":\"2022-10-19\",\"time\":[600,1080]},{\"date\":\"2022-10-20\",\"time\":[600,1080]},{\"date\":\"2022-10-21\",\"time\":[600,1080]},{\"date\":\"2022-10-22\",\"time\":[600,1080]},{\"date\":\"2022-10-23\",\"time\":[600,1080]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1　スマイルビルダーズ内', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172839439712589.jpg', 0, NULL, NULL, '<p style=\"text-align:center;\"><span style=\"color:#000000;\"><strong>＼</strong></span><span style=\"background-color:#f1c40f;color:#000000;\"><strong>3店舗合同　NEOデザインホーム1周年感謝祭</strong></span><span style=\"color:#000000;\"><strong>／</strong></span></p><p style=\"text-align:center;\"><span style=\"color:#c0392b;\"><strong>総額3,000万円</strong></span><span style=\"color:#000000;\"><strong>キャンペーン！！</strong></span></p><p><strong>イベント期間：10/8（土）～10/23（日）　10時～18時</strong></p><p>　　　　　　　　　※12日（水）・19日（水）は定休日になります</p><p><strong>★</strong><span style=\"color:#c0392b;\"><strong>来場特典も多数ご用意</strong></span><strong>★</strong></p><p><strong>【ご来場特典①】</strong></p><p><strong>土・日・祝 限定！&nbsp;</strong><span style=\"color:#c0392b;\"><strong>danken　ﾎｯﾄｻﾝﾄﾞ3種詰め合わせ</strong></span><strong>（各日先着10組）</strong></p><p><strong>　　　　　　　　 ・ハムチーズ　・ツナチーズ　・ミート＆チーズ</strong></p><p><strong>　　平日　 限定！&nbsp;</strong><span style=\"color:#c0392b;\"><strong>マックカード　1,000円分</strong></span><strong>　　&nbsp; &nbsp;（各日先着３組）</strong></p><p><strong>【ご来場特典➁】</strong></p><p><strong>