INSERT INTO `events` VALUES (130, 5, 'NEOデザインホーム姶良支店　グランドオープンフェア！', '展示会', '予約制', '[{\"date\":\"2022-04-09\",\"time\":[600,1080]},{\"date\":\"2022-04-10\",\"time\":[600,1080]},{\"date\":\"2022-04-11\",\"time\":[600,1080]},{\"date\":\"2022-04-12\",\"time\":[600,1080]},{\"date\":\"2022-04-14\",\"time\":[600,1080]},{\"date\":\"2022-04-15\",\"time\":[600,1080]},{\"date\":\"2022-04-16\",\"time\":[600,1080]},{\"date\":\"2022-04-17\",\"time\":[600,1080]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1　スマイルビルダーズ内', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172843621099716.jpg,/imgs/events/172843621411817.jpg', 0, NULL, NULL, '<p>NEOデザインホーム2店舗目となる姶良支店のオープンを記念し、</p><p>グランドオープンオープニングフェアを行います！</p><p><strong>イベント期間：4/9（土）～4/17（日）</strong></p><p><span style=\"color:#e74c3c;\"><strong>来場特典も多数ご用意！</strong></span></p><p>さらにご見学、ご来場アンケートへご協力いただいた方には</p><p><span style=\"color:#e74c3c;\"><strong>空くじなしのお楽しみ抽選会を毎日開催</strong></span>☆</p><p><span style=\"color:#e74c3c;\"><strong>NEOデザインホームの公式ホームページからの事前予約がお得です☆</strong></span></p><p>　※事前予約特典は初めてNEOデザインホームへご来場いただく方に限ります。</p><p>　※スマイルビルダーズの来場予約特典との重複はできません。</p><p>　※スマイルビルダーズHPからの来場予約は対象外となります。</p><p>　　（スマイルビルダーズの予約特典は受けられます）</p><p>是非、ご家族様お揃いでご来場ください！</p><p>※全ての特典には数に限りがございますので、なくなり次第終了とさせていただきます。</p>', NULL, '設定しない', '2024-10-09 10:07:00', '2024-11-28 10:23:37', NULL, 1);
INSERT INTO `events` VALUES (131, 5, 'NEOデザインホーム姶良支店　グランドオープンフェア第２弾！！', '展示会', '予約制', '[{\"date\":\"2022-05-14\",\"time\":[600,1080]},{\"date\":\"2022-05-15\",\"time\":[600,1080]},{\"date\":\"2022-05-16\",\"time\":[600,1080]},{\"date\":\"2022-05-17\",\"time\":[600,1080]},{\"date\":\"2022-05-19\",\"time\":[600,1080]},{\"date\":\"2022-05-20\",\"time\":[600,1080]},{\"date\":\"2022-05-21\",\"time\":[600,1080]},{\"date\":\"2022-05-22\",\"time\":[600,1080]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1　スマイルビルダーズ内', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172843646126518.jpg', 0, NULL, NULL, '<p>ご好評につき、NEOデザインホーム姶良支店　グランドオープンフェア</p><p><span style=\"color:#c0392b;\"><strong>第２弾</strong></span>を行います！</p><p><strong>イベント期間：5/14（土）～5/22（日）　１０時～１８時</strong></p><p><strong>★</strong><span style=\"color:#c0392b;\"><strong>来場特典も多数ご用意</strong></span><strong>★</strong></p><p>さらに、ご見学・ご来場アンケートへご協力いただいた方には</p><p><span style=\"color:#c0392b;\"><strong>空くじなしのお楽しみ抽選会</strong></span>を毎日開催<strong>✨</strong></p><p><span style=\"background-color:#f39c12;color:#000000;\"><strong>NEOデザインホームの公式ホームページからの事前予約がお得です！！</strong></span></p><p>♦NEOデザインホームの<strong>公式ホームページ</strong>からご予約いただいた</p><p>　お客様に限り、<span style=\"color:#c0392b;\"><strong>最大4000円分</strong></span>のアマゾンギフト券をプレゼント！！</p><p>　　※前日13時までにご来場予約された方が対象となります</p><p>　（予約来場：2000円分<strong>＋</strong>事前アンケート：1000円<strong>＋</strong>ご家族でのご来場：1000円）</p><p><strong>こちらをクリック▶</strong><a href=\"https://neo-dhome.com/event/578\"><span style=\"color:#c0392b;\"><strong>NEOデザインホーム　公式ホームページ</strong></span></a></p><p>※事前予約特典は、初めてNEOデザインホームへご来場いただく方に　</p><p>　限ります。</p><p>※スマイルビルダーズの来場予約特典との重複はできません。</p><p>※スマイルビルダーズHPからの来場予約は対象外となります。</p><p>　（スマイルビルダーズの予約特典は受けられます）</p><p><strong>是非、ご家族お揃いでご来場ください！</strong></p><p>※全ての特典には限りがございますので、なくなり次第終了とさせていただきます。</p>', NULL, '設定しない', '2024-10-09 10:11:00', '2024-11-28 10:23:38', NULL, 1);
INSERT INTO `events` VALUES (132, 5, '《霧島市　国分清水》　平屋の完成見学会', '完成見学会', '予約制', '[{\"date\":\"2022-05-21\",\"time\":[600,1020]},{\"date\":\"2022-05-22\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '霧島市', '国分清水', '1丁目21-22', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172843665329819.jpg', 0, NULL, NULL, '<p>お施主様のこだわりが詰まったステキな家です！</p><p>参考になること間違いなしです★</p><p>&nbsp;</p><p>※2日間限定、<span style=\"color:#c0392b;\"><strong>完全予約制</strong></span>になります。</p>', NULL, '設定しない', '2024-10-09 10:15:00', '2024-11-28 10:23:41', NULL, 1);
INSERT INTO `events` VALUES (133, 5, '《鹿児島市吉野町》　平屋の完成見学会', '完成見学会', '予約制', '[{\"date\":\"2022-05-14\",\"time\":[600,1020]},{\"date\":\"2022-05-15\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '鹿児島市', '吉野町', '6423-3', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172843683445620.jpg', 0, NULL, NULL, '<p>&nbsp;高低差のある敷地を活かし、プライバシーと開放感を両立した</p><p>スキップフロアのあるオシャレな平屋となっております！！</p><p><img src=\"https://photos.google.com/photo/AF1QipOgtkUD7hLEb3QrteK_wu_N3lJyT-88d980Q-br\" alt=\"\"></p>', NULL, '設定しない', '2024-10-09 10:18:00', '2024-11-28 10:23:41', NULL, 1);
INSERT INTO `events` VALUES (134, 5, 'NEOデザインホーム　展示場モデルハウス', '展示会', '予約制', '[{\"date\":\"2024-09-08\",\"time\":[600,1080]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172843719858921.jpg,/imgs/events/172843720198122.jpg,/imgs/events/172843720563923.jpg,/imgs/events/172843720907024.jpg,/imgs/events/172843721254825.jpg,/imgs/events/172843721630226.jpg,/imgs/events/172843721937527.jpg,/imgs/events/172843722353028.jpg,/imgs/events/172843722708029.jpg', 0, NULL, NULL, '<p style=\"text-align:center;\">​</p><figure class=\"image image_resized\" style=\"width:16.44%;\"><img style=\"aspect-ratio:1074/224;\" src=\"/imgs/upload/172843732286101.png\" width=\"1074\" height=\"224\"></figure><p style=\"text-align:center;\"><strong>ライフスタイルにあわせた</strong></p><p style=\"text-align:center;\"><strong>理想の空間をデザイン</strong></p><p style=\"text-align:center;\"><strong>＜空間を</strong><i><strong>有効活用</strong></i><strong>した平屋のモデルハウス＞</strong></p><p style=\"text-align:center;\"><strong><u>■吹き抜けのある広々としたリビング</u></strong></p><p style=\"text-align:center;\">自然光を取り込みやすく</p><p style=\"text-align:center;\">明るくて開放的な空間になっております！</p><figure class=\"image image_resized\" style=\"width:18.22%;\"><img style=\"aspect-ratio:620/413;\" src=\"/imgs/upload/172843741074830.jpg\" width=\"620\" height=\"413\"></figure><p style=\"text-align:center;\">°˖✧　風通しのよいインナーテラス付き　✧˖°</p><figure class=\"image image_resized\" style=\"width:18.03%;\"><img style=\"aspect-ratio:6700/4467;\" src=\"/imgs/upload/172843743990231.jpg\" width=\"6700\" height=\"4467\"></figure><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\"><strong><u>■GRAFTEKTのオープンキッチン</u></strong></p><p style=\"text-align:center;\">機能・性能はもちろん、デザイン性にもこだわった</p><p style=\"text-align:center;\">おしゃれなキッチンは必見です！</p><figure class=\"image image_resized\" style=\"width:17.96%;\"><img style=\"aspect-ratio:6700/4467;\" src=\"/imgs/upload/172843749472332.jpg\" width=\"6700\" height=\"4467\"></figure><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\"><strong><u>■大容量の収納スペース</u></strong></p><p style=\"text-align:center;\">長靴やブーツ、レインコートなど</p><p style=\"text-align:center;\">季節ものの靴や衣類も収納可能！</p><figure class=\"image image_resized\" style=\"width:13.44%;\"><img style=\"aspect-ratio:4467/6700;\" src=\"/imgs/upload/172843753881533.jpg\" width=\"4467\" height=\"6700\"></figure><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">収納力抜群のパントリー！</p><figure class=\"image image_resized\" style=\"width:13.27%;\"><img style=\"aspect-ratio:4467/6700;\" src=\"/imgs/upload/172843758816534.jpg\" width=\"4467\" height=\"6700\"></figure><p style=\"text-align:center;\">​<br>&nbsp;</p><p style=\"text-align:center;\">​</p>', NULL, '設定しない', '2024-10-09 10:22:00', '2024-11-28 10:23:44', NULL, 1);
INSERT INTO `events` VALUES (135, 5, '《霧島市》完成見学会', '完成見学会', '予約制', '[{\"date\":\"2024-08-03\",\"time\":[600,1020]},{\"date\":\"2024-08-04\",\"time\":[600,1020]}]', NULL, '非公開', 0, 1, '鹿児島県', '霧島市', '隼人町東郷', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172843776383835.jpg', 0, NULL, NULL, '<p style=\"text-align:center;\"><span style=\"background-color:#c0392b;color:#ffffff;\"><strong>　NEOデザインホーム　</strong></span></p><h4 style=\"text-align:center;\"><span style=\"color:hsl(0, 0%, 0%);\"><strong>《霧島市》完成見学会</strong></span></h4><p style=\"text-align:center;\"><strong>開催日：8/3（</strong><span style=\"color:#2980b9;\"><strong>土</strong></span><strong>）・8/4（</strong><span style=\"color:#c0392b;\"><strong>日</strong></span><strong>）</strong></p><p style=\"text-align:center;\"><strong>&nbsp;時間　：10時～17時</strong></p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">お施主様のご厚意により、お引渡し前のお宅を見学させていただけることになりました</p><p style=\"text-align:center;\"><span style=\"color:#27ae60;\"><strong>二世帯住宅</strong></span>をお考えの方必見の見学会です✨</p><p style=\"text-align:center;\">お施主様のこだわりが詰まったお家を、実際にご覧いただけます。</p><p style=\"text-align:center;\">ご希望の方は下記フォームよりお申し込みください。</p><p style=\"text-align:center;\"><strong>ご予約はこちらから▷▶▷</strong><a href=\"http://neo-dhome.com/event/3484\"><span style=\"color:#c0392b;\"><strong>NEOデザインホーム公式HP</strong></span></a></p>', NULL, '設定しない', '2024-10-09 10:34:00', '2024-10-29 10:18:47', NULL, 1);
INSERT INTO `events` VALUES (136, 8, '【サンプル】いくら借りれる?! 資金計画相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837990302570.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりの前から資金計画や住宅ローンのご相談を頂ける「資金計画相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>実績のある住まいのプロが住宅ローンや資金計画の悩みを解消致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物総額でいくらまでなら不安なく払えるのか知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分はいくら借りることが出来るのかローン金額を知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■大きな買い物なので色々相談したいけど、誰に聞けば良いのか分からない方</strong></span></p><p><span style=\"color:#000000;\">家づくりには大きなお金がかかります。だからこそ住宅ローンや資金計画についての不安や悩みは誰もが抱えています。</span></p><p><span style=\"color:#000000;\">住宅ローンの選択やその金利の検討、借入額の検討や毎月の支払額。建ててから後悔しない為に、失敗しない準備が大切です。</span></p><p><span style=\"color:#000000;\">ですが、誰に相談すればよいか分からない、特定の銀行に聞きに行ってもいいものなのか、、、</span></p><p><span style=\"color:#000000;\">そこで頼りになるのが、これまで多くの住宅建築に関わった私たち工務店です。</span></p><p><span style=\"color:#000000;\">私たちは、理想の住まいを実現するために住宅を設計し建築するのが仕事ですが、お客様からいつもお金の悩みも伺います。</span></p><p><span style=\"color:#000000;\">どの銀行にも属さない私たちだからこそ、お話しできることをお伝えし、不安を払拭して頂く為に相談会を開催しています。</span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅のプロがお客様の理想のイメージを元に総額をお答えします</strong></span></p><p><span style=\"color:#000000;\">家づくりの検討初期から銀行にローンの相談に行く方はほとんどいません。自分たちの理想の住まいがいくらくらいかかるか分からないからです。</span></p><p><span style=\"color:#000000;\">まずはお客様の理想の住まいのイメージ（立地や建築プラン、仕様等）を伺い、概算の総額をお答えします。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅ローンあっせんや保険加入が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">私たちは工務店として住宅建築を行う会社ですので、ローンのあっせんや生命保険のかけ替えによる利益はございません。</span></p><p><span style=\"color:#000000;\">お客様の不安が解消され、当社のプランを気に入って頂いた場合に限り、建築請負契約を締結しお仕事をさせて頂ければと思っております（もちろん強引な営業はいたしません）</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;これまで理想の住まいを実現された他の方の事例をご紹介します</strong></span></p><p><span style=\"color:#000000;\">お客様とご年齢や家族構成が近いお客様の事例をご紹介することができますので、その方々の総額や住宅ローンなどについても可能な限り共有させて頂くことが可能です。</span></p><p><span style=\"color:#000000;\">同じような不安を持たれたていた別のお客様の事例をお知りいただくことで、イメージが沸きやすくなると、大変好評です。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#2980b9;\"><strong>資金計画相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:31:00', '2024-10-29 10:18:47', NULL, 1);
INSERT INTO `events` VALUES (137, 8, '【サンプル】一緒に探します！理想の土地探し相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837999542172.png,/imgs/events/172838000251571.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、土地探しから家づくりのご相談を頂ける「土地探し相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望の住まいに適した土地をご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物を一緒にご相談されたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■建売分譲等とは異なり、自分たちだけの理想の家を考えている方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:rgb(231,76,60);color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを共有しながら土地探しを無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社へご相談へお越しの7割以上が、土地探しからご相談頂くお客様です。</span></p><p><span style=\"color:#000000;\">エリア内の土地をご紹介できる不動会社と連携し、お客様に最適な土地をご提案してきた実績がございますので、是非まずはご予約の上ご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;不動産販売が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">土地探しからのご相談の場合でも、理想の住まいを建築させて頂くことを生業としているのが私たち工務店です。</span></p><p><span style=\"color:#000000;\">設計の視点も取り入れ、土地に理想の建築プランがしっかり納まるように、サポートさせて頂くことが可能です。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地は良くないかな？」と思う前に、まず私たちにご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。土地情報だけでなく、学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#e74c3c;\"><strong>土地探し相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:33:00', '2024-10-29 10:18:47', NULL, 1);
INSERT INTO `events` VALUES (138, 8, '【サンプル】家族の理想の間取りプラン相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838005477173.png,/imgs/events/172838005854374.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりのご相談の一環としてる「間取りプラン相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望のイメージをもとにこれまで手掛けた間取り事例や３Dパースをご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■こんな土地だけどどんな間取りで建てればいいの？と考えている方</strong></span></p><p><span style=\"color:#000000;\"><strong>■地震に強い、性能の良い家ってどんな間取りなの？という方</strong></span></p><p><span style=\"color:#000000;\"><strong>■子育て・家事をスムーズにする間取りを知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■間取り設計の基本を知りたい方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを伺いながら間取り検討を無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社は工務店として多くのお客様の理想の住まいを叶えてきました。</span></p><p><span style=\"color:#000000;\">お客様の理想の暮らしのイメージをお教え頂きながら、事例をご覧頂いたり、手描きの間取りをお見せしたりしながら、イメージを固めるお手伝いをいたします。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;間取りプランニングは無料を行いますのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">プランニングをする段階で当社は費用を頂くことは一切ございません。</span></p><p><span style=\"color:#000000;\">ですが、お客様に理想の家を叶えて頂くため、一生懸命親身にお話しをお伺いさせて頂きますので、是非お気軽に相談会にお越しください。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地だったらどうだろう？」と思う土地がおありでしたら、是非物件資料をお持ちください。プランをご提案させて頂きます。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#16a085;\"><strong>間取りプラン相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:34:00', '2024-10-29 10:18:47', NULL, 1);
INSERT INTO `events` VALUES (139, 8, '姶良総合住宅展示場　平屋モデルハウス', '相談会', '予約制', '[{\"date\":\"2022-04-10\",\"time\":[600,1020]}]', NULL, '非公開', 0, 0, '鹿児島県', '姶良市', '宮島町', '１１－４', '地図にピンを表示する', '住所を全て記載する', NULL, 0, NULL, NULL, NULL, NULL, '設定しない', '2024-10-09 11:16:00', '2024-10-29 10:18:47', NULL, 1);
INSERT INTO `events` VALUES (140, 8, 'お家づくりのための収納セミナー', 'セミナー', '予約制', '[{\"date\":\"2023-03-09\",\"time\":[600,720]},{\"date\":\"2023-03-11\",\"time\":[600,720]},{\"date\":\"2023-03-21\",\"time\":[600,720]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844045078402.png', 0, NULL, NULL, NULL, NULL, '設定しない', '2024-10-09 11:18:00', '2024-11-28 10:23:47', NULL, 1);
INSERT INTO `events` VALUES (141, 8, '【サンプル】※先着10組限定※500万円以上差が出る！住宅ローン相談会', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838793856965.jpeg,/imgs/events/172838794269566.png,/imgs/events/172838794645567.png,/imgs/events/172838795032468.jpeg,/imgs/events/172838795534169.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2024-10-08 20:44:00', '2024-10-29 10:18:47', NULL, 1);
INSERT INTO `events` VALUES (142, 8, '【サンプル】予約制完成見学会｜自然素材が心地よい家', '完成見学会', '予約制', NULL, NULL, '非公開', 0, 0, '岡山県', '岡山市北区', '今3-16-5', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172658874677621.jpeg,/imgs/events/172658875219722.png,/imgs/events/172658877140023.png,/imgs/events/172658877594724.png,/imgs/events/172658878214225.jpeg', 0, NULL, NULL, NULL, NULL, '設定しない', '2024-09-18 00:56:16', '2024-10-29 10:18:47', NULL, 1);
INSERT INTO `events` VALUES (143, 8, 'マシュマロアートワークショップ♪', 'ワークショップ', '予約制', '[{\"date\":\"2022-11-29\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田', '2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844085628736.jpg,/imgs/events/172844085998937.jpg,/imgs/events/172844086323938.jpg,/imgs/events/172844086665639.jpg,/imgs/events/172844087078340.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 50代以上向け, 夫婦+子供, 夫婦のみ, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 子育て, リフォーム住宅, リノベーション住宅', '<h3>健康塗料で調湿効果・消臭効果</h3><h3>のあるアートをつくろう！</h3><h3>マシュマロアートワークショップ✨</h3><p>&nbsp;</p><p><strong>しっくいでもない、珪藻土でもない、</strong></p><p><strong>当社標準仕様の健康塗り壁「友喜のしるし　マシュマロタッチ」</strong></p><p><strong>で絵を描いたり、アートをつくったりしながらご体感いただけます♪</strong></p><p><strong>見て、聞いて、触って、匂って、塗って、楽しみましょう！！</strong></p><p><strong>お子様連れでも楽しくご参加できますよ♪</strong></p><p><strong>皆様のご予約を心よりお待ちしております。</strong></p><p>◆8月30日まで毎日開催　午前の部：10時～　午後の部：14時～</p><p>　※日曜日、別の時間帯ご要望の場合は都度お問い合わせください。</p><p>◆場所：スマイルビルダーズ姶良総合住宅展示場　アイランドホームモデルハウス内</p><p>‐―――――――――――――――――――――――――――――――――――――――――――</p><p><strong>☆ワークショップ　カリキュラム　（所要時間約1時間半）☆</strong></p><p><strong>①アンケート記入後、マシュマロタッチのご紹介</strong></p><p><strong>②あなたの素手で触って、匂ってみましょう♪</strong></p><p><strong>③実際にアートをつくろう！</strong></p><p><strong>　</strong></p><p><strong>　当社でご用意させていただくキャンバスにマシュマロタッチと絵具、ドライフラワーを使って</strong></p><p><strong>　自分だけのアートを作ることができます☆</strong></p><p><strong>　ルールや縛りは一切ございません。自分が描きたいものやつくりたいものを作りましょう♪</strong></p><p><strong>　</strong></p><p><strong>　アートは乾いたらお持ち帰りいただけます。</strong></p><p><strong>　調湿効果、消臭効果やセラピー効果もあるのでトイレや寝室、勉強部屋等に置くのに最適です♪</strong></p><p><strong>　夏休みの宿題にも最適です！そのままアートを提出したり、絵日記などに使えますよ。</strong></p><p><strong>④アンケート記入にて終了</strong></p><p><strong>　最後にお飲み物をご提供させていただいております。</strong></p><p><strong>　お子様にもジュースやお茶などご用意してお待ちしております♪</strong></p><p>―――――――――――――――――――――――――――――――――――――――――――</p><p><strong>【準備物】</strong></p><p><strong>・タオル</strong></p><p><strong>・楽しむ気持ち♡</strong></p><p><strong>【注意点】</strong></p><p><strong>・夢中で楽しんでいるとマシュマロタッチや絵の具がお洋服についてしまうことがあります。</strong></p><p><strong>　水性になりますのでお洗濯で汚れは取ることができますが、高価なお洋服は控えましょう。</strong></p><p><strong>・1日二組のグループ（ご家族）限定になります。お友達と一緒に参加したい、団体で参加したい</strong></p><p><strong>　というご要望がありましたらアイランドホーム担当山口（080-4133-2543）まで事前に</strong></p><p><strong>　お電話、ご相談ください。</strong></p><p><strong>・日曜日や他の時間帯にご要望の方は、アイランドホーム担当山口（080-4133-2543）まで事前に</strong></p><p><strong>　お電話、ご相談ください。</strong></p><p><strong>完全予約制になりますので必ずご予約をお願い致します！</strong></p><p><strong>　</strong></p><p><br>&nbsp;</p>', NULL, '設定しない', '2024-10-09 11:24:00', '2024-11-28 10:23:49', NULL, 1);
INSERT INTO `events` VALUES (144, 8, 'マシュマロタッチアートワークショップ', 'ワークショップ', '予約制', '[{\"date\":\"2023-04-30\",\"time\":[600,1080]}]', NULL, '非公開', 0, 0, '鹿児島県', '姶良市', '加治木町木田2511-1　スマイルビルダーズ住宅総合展示場　案内所内', '2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844150226041.jpg', 0, NULL, '夫婦+子供, 自然素材使用, 北欧スタイル, シンプル, ナチュラル, 子育て', '<p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">&nbsp;お家の空間・空氣を整える「友喜のしるし　マシュマロタッチ」を使って</p><p style=\"text-align:center;\">世界に一つだけのアートをつくろう！！</p><h3 style=\"text-align:center;\"><span style=\"color:#e67e22;\">マシュマロタッチアートワークショップ</span></h3><p style=\"text-align:center;\">inスマイルビルダーズ姶良総合住宅展示場</p><p style=\"text-align:center;\">健康塗材・友喜のしるしマシュマロタッチと水性絵具を使って</p><p style=\"text-align:center;\">キャンパスにアート（絵）を描いていきます♪</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">マシュマロタッチは触って氣持ちがいいし、絵を描くのはもっと楽しい♪</p><p style=\"text-align:center;\">セラピー効果で癒されます。</p><p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">描いていただいたアートで個展も開けちゃうかも！？</p><p style=\"text-align:center;\">乾かした後、お持ち帰りいただけます。</p><p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">描いたアートは空間を整えてくれるので、</p><p style=\"text-align:center;\">調湿効果、消臭効果が期待できますよ♪</p><p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">日本でも当たり前になってきたアートセラピー。</p><p style=\"text-align:center;\">関東では8,000円もするアートスタジオもある中、</p><p style=\"text-align:center;\">なんと今回のイベントでは</p><p style=\"text-align:center;\">参加費は通常6,000円のところを一家族様、3,000円で体験できます。</p><p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">大人の方もお子様もみんな参加OKです！</p><p style=\"text-align:center;\">ぜひご体感お待ちしております。</p><p style=\"text-align:center;\">【詳細】</p><p style=\"text-align:center;\">主催：株式会社アイランドホーム＆NURIKAETAI</p><p style=\"text-align:center;\">日時:2023年4月30日　日曜日　午前の部10時〜 午後の部14時〜 各回10組限定</p><p style=\"text-align:center;\">会場:スマイルビルダーズ姶良総合住宅展示場総合案内所内</p><p style=\"text-align:center;\">参加費:通常金額<span style=\"color:#e74c3c;\">6,000</span>円→特別金額<span style=\"color:#3498db;\">3,000</span>円でご案内/ご家族1組様</p><p style=\"text-align:center;\">お問い合わせは担当：山口まで（080-4133-2543）</p><p style=\"text-align:center;\">【注意事項】</p><p style=\"text-align:center;\">※絵具等がついても大丈夫な格好でのご参加をおねがいします。</p><p style=\"text-align:center;\">※お支払いは現金のみとなっております。領収書を希望の場合はご予約の際、</p><p style=\"text-align:center;\">お伝えいただくかご予約フォームの備考欄に領収書希望とご記載ください。</p><p style=\"text-align:center;\">※手を拭く大きめのタオルやハンカチをお持ちください。</p><p style=\"text-align:center;\">※楽しむ心もお忘れなく♪</p><p style=\"text-align:center;\"><br>&nbsp;</p><p style=\"text-align:center;\">​</p>', NULL, '設定しない', '2024-10-09 11:35:00', '2024-10-29 10:18:47', NULL, 1);
INSERT INTO `events` VALUES (145, 8, 'マシュマロタッチアートワークショップ', 'ワークショップ', '予約制', '[{\"date\":\"2023-07-29\",\"time\":[600,1020]},{\"date\":\"2023-09-23\",\"time\":[600,1080]},{\"date\":\"2023-09-24\",\"time\":[600,1080]},{\"date\":\"2023-10-28\",\"time\":[600,1020]},{\"date\":\"2023-10-29\",\"time\":[600,1020]},{\"date\":\"2023-11-04\",\"time\":[600,1020]},{\"date\":\"2023-11-05\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1　スマイルビルダーズ住宅総合展示場　アイランドホームモデルハウス', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844192968903.png', 0, NULL, '夫婦+子供, 自然素材使用, 北欧スタイル, シンプル, ナチュラル, 子育て', '<p style=\"text-align:center;\">​</p><p style=\"text-align:center;\"><span style=\"background-color:#f39c12;\">&nbsp;お家の空間・空氣を整える「友喜のしるし　マシュマロタッチ」を使って</span></p><p style=\"text-align:center;\"><span style=\"background-color:#f39c12;\">世界に一つだけのアートをつくろう！！</span></p><h3 style=\"text-align:center;\"><span style=\"color:#e67e22;\">マシュマロタッチアートワークショップ</span></h3><p style=\"text-align:center;\">inスマイルビルダーズ姶良総合住宅展示場</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">健康塗材・友喜のしるしマシュマロタッチと水性絵具を使って</p><p style=\"text-align:center;\">キャンパスに素手で！アート（絵）を描きます♪</p><p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">​マシュマロタッチは触って氣持ちがいいし、絵を描くのはもっと楽しい♪</p><p style=\"text-align:center;\">セラピー効果で癒されます。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">描いていただいたアートで個展も開けちゃうかも！？</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">描いたアートは空間を整えてくれるので、</p><p style=\"text-align:center;\">調湿効果、消臭効果が期待できますよ♪</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">日本でも当たり前になってきたアートセラピー。</p><p style=\"text-align:center;\">関東では8,000円もするアートスタジオもある中、</p><p style=\"text-align:center;\">大人3,000円・こども1500円でご参加できます。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">アイランドホームは新築注文住宅、リフォームを通じて</p><p style=\"text-align:center;\"><span style=\"background-color:#e67e22;\">地球基準の清浄な空氣ある空間づくり</span></p><p style=\"text-align:center;\">をしています。</p><p style=\"text-align:center;\">友喜のしるしマシュマロタッチで</p><p style=\"text-align:center;\">どんなお家でも呼吸する空間にできるのです♪</p><p style=\"text-align:center;\">大人の方もお子様もみんな参加OKです！</p><p style=\"text-align:center;\">ぜひご体感お待ちしております。</p><p style=\"text-align:center;\">【詳細】</p><p style=\"text-align:center;\">主催：株式会社アイランドホーム</p><p style=\"text-align:center;\">日時:2023年10月28日(土）29日（日）</p><p style=\"text-align:center;\">2023年11月4日（土）5日(日）　</p><p style=\"text-align:center;\">10:00～17:00</p><p style=\"text-align:center;\">ご予約優先　自由参加OK</p><p style=\"text-align:center;\">会場:スマイルビルダーズ姶良総合住宅展示場</p><p style=\"text-align:center;\">アイランドホームモデルハウス</p><p style=\"text-align:center;\">参加費:大人1,500円/1名　こども700円/1名</p><p style=\"text-align:center;\">お問い合わせは担当：山口まで（080-4133-2543）</p><p style=\"text-align:center;\">【注意事項】</p><p style=\"text-align:center;\">※絵具等がついても問題ない格好でのご参加をおねがいします。</p><p style=\"text-align:center;\">※お支払いは現金のみとなっております。</p><p style=\"text-align:center;\">※手を拭く大きめのタオルやハンカチをお持ちください。</p><p style=\"text-align:center;\">※楽しむ心もお忘れなく♪</p>', NULL, '設定しない', '2024-10-09 11:43:00', '2024-11-28 10:23:50', NULL, 1);
INSERT INTO `events` VALUES (146, 8, '失敗しないための家づくり座談会in鹿児島市吉野町', '勉強会', '予約制', '[{\"date\":\"2023-02-26\",\"time\":[780,960]}]', NULL, '公開', 1, 0, '鹿児島県', '鹿児島市', '吉野町1250アイランドホーム吉野店４F ', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844237537004.png', 0, NULL, '20代向け, 30代向け, 夫婦+子供, 庭あり, 木造住宅, デザイン住宅, 住宅ローン相談可, 子育て, 家事動線, 収納', '<p style=\"text-align:center;\">家づくりで失敗しないために<br>幸せな家づくりをするために<br>座談会形式で学べるイベント<br>となっております♪</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">一級建築士のプロフェッショナルと<br>お金や土地、プランニングのこと<br>等知りたいことを知ることが<br>できます！</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">ぜひこの機会にたくさんの<br>夢や希望を語り合いながら<br>楽しく学びましょう☺️</p>', '<p style=\"text-align:center;\">✨ご参加特典✨<br>アマゾンギフトカード2000円分<br>プレゼント</p><p style=\"text-align:center;\">✨キッズルーム完備✨<br>お子様と一緒でも安心してご参加頂けます！</p>', '設定しない', '2024-10-09 11:48:00', '2024-11-28 10:23:52', NULL, 1);
INSERT INTO `events` VALUES (147, 8, '≪姶良市加治木町≫住宅体感会', '完成見学会', '予約承認制', '[{\"date\":\"2023-11-18\",\"time\":[600,1020]},{\"date\":\"2023-11-19\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田', '4605-31', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844433887642.jpg,/imgs/events/172844434221843.jpg', 0, NULL, '平屋住宅, デザイン住宅, ハイグレード住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 住宅ローン相談可, シンプル, 20代向け, 30代向け, 40代向け, 夫婦+子供, 子育て, 庭あり, 木造住宅, 家事動線, 収納, 耐震住宅, 駐車場あり', '<h3><strong>住宅体感会開催</strong></h3><p>&nbsp;</p><p>姶良市加治木町にて、建主様のご厚意で、完成体感会を開催することになりました。</p><p>建主様、誠にありがとうございます。私たちは、家づくりは人生づくり、</p><p>空間づくりをコンセプトに家づくりのお手伝いをさせていただいております。</p><p>&nbsp;</p><p><u>また「完成見学会」という言葉は住宅会社での広告でよく目にしますが、</u></p><p><u>私たちは「住宅体感会」と名付けさせて頂いています。</u></p><p><u>なぜなら、家づくりのとても大切な本質は目に見えないからです。</u></p><p><u>そして家庭とは完成がなく、これから人生がはじまるからです。</u></p><p><u>そしてこの目に見えないものを大切にされた建主様だからこそ、</u></p><p><u>お越しいただけるご縁があった方だからこそ、</u></p><p><u>体感を大切にしていただきたいとの想いで、「住宅体感会」と名付けています。</u></p><p>&nbsp;</p><p>建主様とは弊社のスマイルビルダーズ姶良総合住宅展示場のモデルハウスにお越しいただいた</p><p>ご縁がきっかけで、ここまで進めて参りました。</p><p>だからこそ、この完成体感会でも、</p><p>ご縁のある方にしか感じることのできない、それだけでなく</p><p>ご縁がなければ伝えることのできないことがあります。</p><p>&nbsp;</p><p>ここに足を運べんでいただけたらきっと、家づくりのお役に立てると存じます。</p><p>お会いできるのを心より楽しみにしております。</p><p>&nbsp;</p><p><strong>-みどころ-</strong></p><p><strong>・家づくりに至るまでのストーリー</strong></p><p><strong>・建主様の家づくりに対する想い</strong></p><p><strong>・建主様と職人さんが共に手掛けたお家</strong></p><p><strong>・唯一無二の空間、空氣</strong></p><p><strong>・土地の有効な使い方、豊かなプランニングについて</strong></p><p>&nbsp;</p><p>この体感会は完全予約制となっております。</p><p>何卒、よろしくお願いいたします。</p><p>&nbsp;</p><p>以上</p><p>&nbsp;</p>', '<p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">ご予約、ご来場いただいた方には「中洋水」のサンプルをプレゼントしています。</p><figure class=\"image image_resized\" style=\"width:19.67%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172844445546344.jpg\" width=\"620\" height=\"827\"></figure><p style=\"text-align:center;\">使い方や効果は現場で説明していますのでお楽しみに♪</p><p style=\"text-align:center;\">​</p>', '設定しない', '2024-10-09 11:56:00', '2024-11-28 10:23:52', NULL, 1);
INSERT INTO `events` VALUES (148, 8, '失敗しない土地の選び方セミナー', 'セミナー', '予約制', '[{\"date\":\"2023-08-25\",\"time\":[600,1020]},{\"date\":\"2023-08-26\",\"time\":[600,1020]},{\"date\":\"2023-08-27\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844517164645.jpg,/imgs/events/172844517491046.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 50代以上向け, 夫婦+子供, 二世帯, 戸建て・一軒家, 住宅ローン相談可, 保険相談可, 税金相談可, 仲介手数料相談可, 補助金相談可', '<h4><span style=\"color:hsl(0, 0%, 0%);\">失敗しない土地の選び方セミナー</span></h4><p>セミナー時間：1時間</p><p>場所：スマイルビルダーズ姶良総合住宅展示場　アイランドホームモデルハウス内</p><p>&nbsp;</p><p><strong>家づくりの大きなハードル「土地選び」こんな不安や心配はありませんか？？</strong></p><p>・希望のエリアに土地が全然見つからない…</p><p>・土地ってどれくらいの金額におさえればいいの？</p><p>・災害や治安が気になる…</p><p>・土地って誰と探せばいいの？</p><p>・土地ってどのように購入すればいいの？</p><p>・田んぼでもお家は作れるの？</p><p>・両親の土地に建てても大丈夫なのかな？</p><p>・土地の税金ってどうなっているの？？</p><p>・自分たちの理想の家が建てられるのかな？</p><p>&nbsp;</p><p>姶良市で不動産取引を年間100件以上している</p><p>アイランドホームだからこそ、</p><p>少しでも不安が解決できるような</p><p>土地選びの「基準」をお伝えしています♪</p><p>&nbsp;</p><p>お家を建てるなら土地選びはとても大切なこと。</p><p>後悔してほしくないし、失敗してほしくない！</p><p>だからこそお伝えしたい大切なことがあります。</p><p>&nbsp;</p><p>当社で建築希望の方でなくても参加していただいて大丈夫です。</p><p>&nbsp;</p><p>また個別にて売却相談や土地探しのご依頼も受け付けております。</p><p>未公開物件もありますよ♪</p><p>&nbsp;</p><p>ぜひお気軽にご予約ください。</p><p>&nbsp;</p><p>◆セミナー時間：1時間</p><p>◆場所：スマイルビルダーズ姶良総合住宅展示場　アイランドホームモデルハウス内</p><p>◆準備物：筆記用具</p><p><br>&nbsp;</p>', NULL, '設定しない', '2024-10-09 11:45:00', '2024-11-28 10:23:53', NULL, 1);
INSERT INTO `events` VALUES (149, 8, '≪姶良市蒲生町≫住宅体感会', '完成見学会', '予約制', '[{\"date\":\"2024-02-09\",\"time\":[570,1020]},{\"date\":\"2024-02-10\",\"time\":[570,1020]},{\"date\":\"2024-02-11\",\"time\":[570,1020]},{\"date\":\"2024-02-12\",\"time\":[570,1020]},{\"date\":\"2024-02-13\",\"time\":[570,1020]},{\"date\":\"2024-02-16\",\"time\":[570,1020]},{\"date\":\"2024-02-17\",\"time\":[540,1020]},{\"date\":\"2024-02-18\",\"time\":[540,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '蒲生町米丸', '515-2', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844566052647.jpg,/imgs/events/172844566402748.jpg', 0, NULL, '平屋住宅, デザイン住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 住宅ローン相談可, ナチュラル, 夫婦+子供, 家事動線, 収納', '<h4><span style=\"color:hsl(0, 0%, 0%);\">​<strong>住宅体感会開催</strong></span></h4><p>&nbsp;</p><p>姶良市蒲生町にて、建主様のご厚意で、新築住宅体感会を開催することになりました。</p><p>建主様、誠にありがとうございます。</p><p>私たちは、家づくりは人生づくり、空間づくり</p><p>をコンセプトに家づくりのお手伝いをさせていただいております。</p><p>​</p><figure class=\"image image_resized\" style=\"width:27.15%;\"><img style=\"aspect-ratio:620/349;\" src=\"/imgs/upload/172844581493149.jpg\" width=\"620\" height=\"349\"></figure><p><strong>-みどころ-</strong></p><p>&nbsp;</p><p><strong>・家づくりのストーリー</strong></p><p>&nbsp;</p><p><strong>・建主様と職人様、私たちが共に手掛けたお家</strong></p><p>&nbsp;</p><p><strong>・家族の健康を守る清浄な空氣、空間</strong></p><p>&nbsp;</p><p><strong>・ハイサイド窓や回廊、景色を活かした美術館のような空間</strong></p><p>&nbsp;</p><p><strong>・ガレージや趣味の動線</strong></p><p>&nbsp;</p><p><strong>・土地の有効な使い方、土地に合う豊かなプランニングについて</strong></p><p><u>また「完成見学会」という言葉は住宅会社での広告でよく目にしますが、</u></p><p><u>私たちは「住宅体感会」と名付けさせて頂いています。</u></p><p><u>なぜなら、家づくりのとても大切な本質は目に見えるものではないからです。</u></p><p><u>そして家庭とは完成がなく、これから人生がはじまるからです。</u></p><p><u>そしてこの目に見えないものを大切にされた建主様だからこそ、</u></p><p><u>お越しいただけるご縁があった方だからこそ、</u></p><p><u>体感を大切にしていただきたいとの想いで、「住宅体感会」と名付けています。</u></p><p>建主様とは弊社の家づくり勉強会にお越しいただいた</p><p>ご縁がきっかけでご依頼頂きました。</p><p>さまざまな紆余曲折があった中、対話を重ねながら、建主様と私たちの</p><p>共に歩んできたストーリーがあり、この竣工を迎えることができました。</p><p>だからこそ、この住宅体感会では</p><p>ご縁のある方にしか感じることのできないことがあります。</p><p>それだけでなく、</p><p>ご縁がなければ伝えることのできないことがあります。</p><p>ここに足を運べんでいただけたらきっと、家づくりのお役に立てると存じます。</p><p>お会いできるのを心より楽しみにしております。</p><p>&nbsp;</p><p><strong>-共にお家をつくりました-</strong></p><figure class=\"image image_resized\" style=\"width:23.48%;\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/172844586005750.jpg\" width=\"620\" height=\"465\"></figure><figure class=\"image image_resized\" style=\"width:23.28%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172844589254151.jpg\" width=\"620\" height=\"827\"></figure><p>&nbsp;</p><p>ご家族みんなで手掛けました。</p><p>アイランドホームの家から家族のお家へ塗り替える！</p><figure class=\"image image_resized\" style=\"width:23.47%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172844595776352.jpg\" width=\"620\" height=\"827\"></figure><p>&nbsp;</p><p>素手で塗るとわかりますがとても楽しい。</p><p>世界にひとつだけの空間になりました。</p><figure class=\"image image_resized\" style=\"width:23.23%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172844597670253.jpg\" width=\"620\" height=\"827\"></figure><p>​</p><p>スタッフも一緒に手掛けました。</p><p>塗るのは楽しいのです！！</p><p>&nbsp;</p><p>ぜひ想いのつまったお家、ご体感にお越しください。</p><p>&nbsp;</p><p>場所の詳細については、別途ご案内させていただきます。</p><p>駐車場もございますのでご安心ください。</p><p>またこの住宅体感会は完全予約制となっております。</p><p>何卒、よろしくお願いいたします。</p><p>&nbsp;</p><p>以上</p>', NULL, '設定しない', '2024-10-09 12:45:00', '2024-11-28 10:23:53', NULL, 1);
INSERT INTO `events` VALUES (150, 8, '≪霧島市溝辺町≫新築住宅体感会', '完成見学会', '予約制', '[{\"date\":\"2024-03-09\",\"time\":[600,1020]},{\"date\":\"2024-03-10\",\"time\":[600,1020]},{\"date\":\"2024-03-12\",\"time\":[600,1020]},{\"date\":\"2024-03-14\",\"time\":[600,1020]},{\"date\":\"2024-03-15\",\"time\":[600,1020]},{\"date\":\"2024-03-16\",\"time\":[600,1020]},{\"date\":\"2024-03-17\",\"time\":[600,1020]},{\"date\":\"2024-03-19\",\"time\":[600,1020]},{\"date\":\"2024-03-20\",\"time\":[600,1020]},{\"date\":\"2024-03-22\",\"time\":[600,1020]},{\"date\":\"2024-03-23\",\"time\":[600,1020]},{\"date\":\"2024-03-24\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '霧島市', '溝辺町麓5丁目', '127', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172844621047554.jpg,/imgs/events/172844621739755.jpg', 0, NULL, '平屋住宅, デザイン住宅, ハイグレード住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用,  住宅ローン相談可, シンプル, 20代向け, 30代向け, 40代向け, 夫婦+子供, 子育て, 庭あり, 家事動線', '<h4><span style=\"color:hsl(0, 0%, 0%);\"><strong>新築住宅体感会開催</strong></span></h4><p>&nbsp;</p><p>霧島市溝辺町にて、建主様のご厚意で、新築住宅体感会を開催することになりました。</p><p>建主様、誠にありがとうございます。</p><p>私たちは、家づくりは人生づくり、空間づくり</p><p>をコンセプトに家づくりのお手伝いをさせていただいております。</p><p>​</p><figure class=\"image image_resized\" style=\"width:22.71%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172844635388156.jpg\" width=\"620\" height=\"827\"></figure><p>&nbsp;</p><p><strong>-みどころ-</strong></p><p>&nbsp;</p><p><strong>・家づくりとは人生づくり</strong></p><p><strong>・建主様と職人様、私たちが共に手掛けたお家</strong></p><p><strong>・家族の健康を守る清浄な空氣、空間</strong></p><p><strong>・開放的で暮らしやすい、収納力もある「２３坪の平屋」</strong></p><p>&nbsp;</p><figure class=\"image image_resized\" style=\"width:31.2%;\"><img style=\"aspect-ratio:620/349;\" src=\"/imgs/upload/172844640032557.jpg\" width=\"620\" height=\"349\"></figure><figure class=\"image image_resized\" style=\"width:31.36%;\"><img style=\"aspect-ratio:620/349;\" src=\"/imgs/upload/172844641455858.jpg\" width=\"620\" height=\"349\"></figure><p>&nbsp;</p><p>&nbsp;</p><p><u>また「完成見学会」という言葉は住宅会社での広告でよく目にしますが、</u></p><p><u>私たちは「住宅体感会」と名付けさせて頂いています。</u></p><p><u>なぜなら、家づくりのとても大切な本質は目に見えるものではないからです。</u></p><p><u>そして家庭とは完成がなく、これから人生がはじまるものです。</u></p><p><u>そしてこの目に見えないものを大切にされた建主様だからこそ、</u></p><p><u>お越しいただけるご縁があった方だからこそ、</u></p><p><u>体感を大切にしていただきたいとの想いで、「住宅体感会」と名付けています。</u></p><p>&nbsp;</p><figure class=\"image image_resized\" style=\"width:27.8%;\"><img style=\"aspect-ratio:620/620;\" src=\"/imgs/upload/172844644264059.png\" width=\"620\" height=\"620\"></figure><p><u>​</u></p><p>建主様とは弊社のモデルハウスにお越しいただいて、土地探しのお手伝いをさせていただきました。</p><p>土地のご縁がきっかけでご依頼頂きました。</p><p>対話を重ねながら、建主様と私たちの共に歩んできたストーリーがあり、</p><p>この竣工を迎えることができました。</p><p>だからこそ、この住宅体感会では</p><p>ご縁のある方にしか感じることのできないことがあります。</p><p>それだけでなく、</p><p>ご縁がなければ伝えることのできないことがあります。</p><p>ここに足を運べんでいただけたらきっと、家づくりのお役に立てると存じます。</p><p>お会いできるのを心より楽しみにしております。</p><p>&nbsp;</p><p>―――――――――――――――――――――――――――――――――――――――――――――――</p><p>&nbsp;</p><p>場所の詳細については、別途ご案内させていただきます。</p><p>駐車場もございますのでご安心ください。</p><p>&nbsp;</p><p>またこの住宅体感会は完全予約制となっております。</p><p>何卒、よろしくお願いいたします。</p><p>&nbsp;</p><p>以上</p>', NULL, '設定しない', '2024-10-09 12:54:00', '2024-11-28 10:23:55', NULL, 1);
INSERT INTO `events` VALUES (151, 8, '≪姶良市平松≫　新築体感会', '完成見学会', '予約制', '[{\"date\":\"2024-03-30\",\"time\":[600,1020]},{\"date\":\"2024-03-31\",\"time\":[600,1020]},{\"date\":\"2024-04-02\",\"time\":[600,1020]},{\"date\":\"2024-04-04\",\"time\":[600,1020]},{\"date\":\"2024-04-05\",\"time\":[600,1020]},{\"date\":\"2024-04-06\",\"time\":[600,1020]},{\"date\":\"2024-04-07\",\"time\":[600,1020]},{\"date\":\"2024-04-09\",\"time\":[600,1020]},{\"date\":\"2024-04-11\",\"time\":[600,1020]},{\"date\":\"2024-04-12\",\"time\":[600,1020]},{\"date\":\"2024-04-13\",\"time\":[600,1020]},{\"date\":\"2024-04-14\",\"time\":[600,1020]},{\"date\":\"2024-04-16\",\"time\":[600,1020]},{\"date\":\"2024-04-18\",\"time\":[600,1020]},{\"date\":\"2024-04-19\",\"time\":[600,1020]},{\"date\":\"2024-04-20\",\"time\":[600,1020]},{\"date\":\"2024-04-21\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '平松', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172845373813259.jpg,/imgs/events/172845374244560.jpg', 0, NULL, '平屋住宅, デザイン住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 住宅ローン相談可, 夫婦+子供, 夫婦のみ, 子育て, 庭あり, 木造住宅, 家事動線, 収納', '<h3><strong>新築体感会開催</strong></h3><p>&nbsp;</p><p>姶良市平松にて、建主様のご厚意で、新築住宅体感会を開催することになりました。</p><p>建主様、誠にありがとうございます。</p><p>私たちは、家づくりは人生づくり、空間づくり</p><p>をコンセプトに家づくりのお手伝いをさせていただいております。</p><p>​​</p><figure class=\"image image_resized\" style=\"width:31.22%;\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/172845916670261.jpg\" width=\"620\" height=\"465\"></figure><figure class=\"image image_resized\" style=\"width:30.65%;\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/172845919387862.jpg\" width=\"620\" height=\"465\"></figure><p>&nbsp;</p><p><strong>-みどころ-</strong></p><h4><span style=\"color:hsl(0, 0%, 0%);\"><strong>・家づくりとは人生づくり</strong></span></h4><p><strong>・建主様と職人様、私たちが共に手掛けたお家</strong></p><p><strong>・家族の健康を守る清浄な空氣、空間</strong></p><p><strong>・土間でつながる開放感、収納力もある「２３坪の平屋」</strong></p><h4><span style=\"color:hsl(0, 0%, 0%);\"><strong>・アウトドアの趣味を活かした、猫ちゃんと暮らす豊かなプランニング</strong></span></h4><p>​</p><figure class=\"image image_resized\" style=\"width:23.16%;\"><img style=\"aspect-ratio:620/826;\" src=\"/imgs/upload/172845927958163.jpg\" width=\"620\" height=\"826\"></figure><p>&nbsp;</p><p><u>また「完成見学会」という言葉は住宅会社での広告でよく目にしますが、</u></p><p><u>私たちは「新築体感会」と名付けさせて頂いています。</u></p><p><u>なぜなら、家づくりのとても大切な本質は目に見えるものではないからです。</u></p><p><u>そして家庭とは完成がなく、これから人生がはじまるものです。</u></p><p><u>そしてこの目に見えないものを大切にされた建主様だからこそ、</u></p><p><u>お越しいただけるご縁があった方だからこそ、</u></p><p><u>体感を大切にしていただきたいとの想いで、「新築体感会」と名付けています。</u></p><p>&nbsp;</p><p>&nbsp;</p><p>建主様とは弊社のモデルハウスにお越しいただいたのがきっかけです。</p><p>対話を重ねながら、建売を見に行ったり、さまざまな土地を見に行ったり</p><p>建主様と私たちの共に歩んできたストーリーがありました。</p><p>そのような大切なご縁とご恩があり、この竣工を迎えることができました。</p><p>ありがとうございます。</p><p>だからこそ、この住宅体感会では</p><p>ご縁のある方にしか感じることのできないことがあります。</p><p>それだけでなく、</p><p>ご縁がなければ伝えることのできないことがあります。</p><p>ここに足を運べんでいただけたらきっと、家づくりのお役に立てると存じます。</p><p>「絶対に後悔しない家づくり」の極意がここにはあります。</p><p>お会いできるのを心より楽しみにしております。</p><p>&nbsp;</p><p>―――――――――――――――――――――――――――――――――――――――――――――――</p><p>&nbsp;</p><p>場所の詳細については、別途ご案内させていただきます。</p><p>駐車場もございますのでご安心ください。</p><p>&nbsp;</p><p>またこの新築体感会は予約制となっております。</p><p>何卒、よろしくお願いいたします。</p><p>&nbsp;</p><p>以上</p>', NULL, '設定しない', '2024-10-09 14:59:00', '2024-11-28 10:23:56', NULL, 1);
INSERT INTO `events` VALUES (152, 8, '≪霧島市国分≫　～愛犬と暮らす、自然と呼吸する家～新築体感会', '完成見学会', '予約制', '[{\"date\":\"2024-05-18\",\"time\":[600,1020]},{\"date\":\"2024-05-19\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '霧島市', '国分郡田', '957-2', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172845951426364.jpg,/imgs/events/172845951778465.jpg,/imgs/events/172845952109866.jpg', 0, NULL, '平屋住宅, デザイン住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 住宅ローン相談可, ナチュラル, 夫婦+子供, 家事動線, 収納', '<h3 style=\"text-align:center;\">​<strong>新築住宅体感会開催</strong></h3><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">霧島市国分郡田にて、建主様のご厚意で、新築住宅体感会を開催することになりました。</p><p style=\"text-align:center;\">建主様、誠にありがとうございます。</p><p style=\"text-align:center;\">私たちは、家づくりは人生づくり、空間づくり</p><p style=\"text-align:center;\">をコンセプトに家づくりのお手伝いをさせていただいております。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\"><strong>-みどころ-</strong></p><p style=\"text-align:center;\">&nbsp;</p><h4 style=\"text-align:center;\"><span style=\"color:hsl(0, 0%, 0%);\"><strong>「家づくりとは人生づくり、空間づくり」</strong></span></h4><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\"><strong>友喜のしるしマシュマロタッチで、生活に欠かせない綺麗な空氣感</strong></p><p style=\"text-align:center;\"><strong>家づくりで後悔しないための、お水もやっぱり空氣だった</strong></p><p style=\"text-align:center;\"><strong>愛犬との暮らしをイメージしながら、明るく開放的なプランニング</strong></p><p style=\"text-align:center;\"><strong>無駄のないストレスフリーな家事動線、家族団らんを生む豊かな回遊動線</strong></p><p style=\"text-align:center;\"><strong>家から家「庭」へ</strong></p><figure class=\"image image_resized\" style=\"width:39.26%;\"><img style=\"aspect-ratio:620/620;\" src=\"/imgs/upload/172845967355967.jpg\" width=\"620\" height=\"620\"></figure><p style=\"text-align:center;\">↑建主様と共にお家をつくりました！</p><figure class=\"image image_resized\" style=\"width:39.29%;\"><img style=\"aspect-ratio:620/420;\" src=\"/imgs/upload/172845970725905.png\" width=\"620\" height=\"420\"></figure><p style=\"text-align:center;\">↑お水が変われば自らが、暮らしが変わる</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\"><u>また「完成見学会」という言葉は住宅会社での広告でよく目にしますが、</u></p><p style=\"text-align:center;\"><u>私たちは「新築体感会」と名付けさせて頂いています。</u></p><p style=\"text-align:center;\"><u>なぜなら、家づくりのとても大切な本質は目に見えるものではないからです。</u></p><p style=\"text-align:center;\"><u>そして家庭とは完成がなく、これから人生がはじまるものです。</u></p><p style=\"text-align:center;\"><u>そしてこの目に見えないものを大切にされた建主様だからこそ、</u></p><p style=\"text-align:center;\"><u>お越しいただけるご縁があった方だからこそ、</u></p><p style=\"text-align:center;\"><u>体感を大切にしていただきたいとの想いで、「新築体感会」と名付けています。</u></p><p style=\"text-align:center;\">&nbsp;</p><figure class=\"image image_resized\" style=\"width:38.66%;\"><img style=\"aspect-ratio:620/349;\" src=\"/imgs/upload/172845973785868.jpg\" width=\"620\" height=\"349\"></figure><p style=\"text-align:center;\">↑建主様とご両親、大工さんとわたし</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">建主様とは…土地選び、マシュマロタッチアートワークショップ</p><p style=\"text-align:center;\">からの大切なご縁があり</p><p style=\"text-align:center;\">この竣工を迎えることができました</p><p style=\"text-align:center;\">ありがとうございます。</p><p style=\"text-align:center;\">だからこそ、この新築住宅体感会では</p><p style=\"text-align:center;\">ご縁のある方にしか感じることのできないことがあります。</p><p style=\"text-align:center;\">それだけでなく、</p><p style=\"text-align:center;\">ご縁がなければ伝えることのできないことがあります。</p><p style=\"text-align:center;\">ここに足を運べんでいただけたらきっと、家づくりのお役に立てると存じます。</p><p style=\"text-align:center;\">「絶対に後悔しない家づくり」の極意がここにはあります。</p><p style=\"text-align:center;\">お会いできるのを心より楽しみにしております。</p><p style=\"text-align:center;\">―――――――――――――――――――――――――――――――――――――――――――――――</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">駐車場もございます</p><p style=\"text-align:center;\">お子様連れでも問題ありません</p><p style=\"text-align:center;\">のでご安心ください。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">またこの新築体感会は予約無しでも問題ありませんが、</p><p style=\"text-align:center;\">予約者優先となっております。</p><p style=\"text-align:center;\">ご来場者数によってはお待ちいただく場合が</p><p style=\"text-align:center;\">ありますのでご注意ください。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">何卒、よろしくお願いいたします。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">以上</p>', NULL, '設定しない', '2024-10-09 16:36:00', '2024-11-28 10:23:56', NULL, 1);
INSERT INTO `events` VALUES (153, 8, '≪志布志市志布志町帖≫　～志合わせの家～新築体感会', '完成見学会', '予約制', '[{\"date\":\"2024-06-15\",\"time\":[600,1020]},{\"date\":\"2024-06-16\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '志布志市', '志布志町帖', '3592-6', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172845993825069.jpg,/imgs/events/172845994245570.jpg', 0, NULL, '平屋住宅, デザイン住宅, ハイグレード住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 住宅ローン相談可, ナチュラル, 夫婦+子供, 木造住宅', '<h3 style=\"text-align:center;\"><strong>新築体感会開催</strong></h3><p>&nbsp;</p><p>この度はこのページをご覧くださり、</p><p>誠にありがとうございます。</p><p>株式会社アイランドホームの山口と申します。</p><p>アイランドホーム史上初めて、志布志での</p><p>新築体感会を開催します。</p><p>&nbsp;</p><p>約3年前、たまたま姶良市の弊社モデルハウス</p><p>を通りかかった建主様。</p><p>お立ち寄り頂いて、私とモデルハウス</p><p>にて初めてお会いしました。</p><p>さらに、大変有難いことに建主様は</p><p>モデルハウスや私たちの家づくりを</p><p>ずっと忘れられなかったようで、</p><p>約1年前、</p><p>私にご連絡頂き、本格的に</p><p>私たちとの家づくりがスタートしました。</p><p>&nbsp;</p><p>建主様との家づくりでは、たくさんお話しをして</p><p>議論を重ねてきました。</p><p>私が特に心に残っているのは、</p><p>いつも幸せそうな建主様ご夫婦と</p><p>お子様の明るいお姿。</p><p>奥様はいつも笑顔で私たちに親切にして頂き、</p><p>ご主人様は真剣ながらもいつも和やかな雰囲氣</p><p>を作ってくださいました。</p><p>ご契約の時も笑顔で握手をしてくださり、</p><p>手がとても温かく、建主様の想いが</p><p>心に沁みたのを思い出します。</p><p>&nbsp;</p><p>そして、温かくて素敵なご家族の家づくりを</p><p>任せていただいただけでなく、</p><p>今回、建主様のご厚意で大変有難い</p><p>新築体感会の機会まで頂きました。</p><p>建主様、本当にありがとうございます。</p><p>&nbsp;</p><p>私は</p><p>こんな幸せそうな建主様ご家族が建てた</p><p>お家を多くの方に体感してほしい…</p><p>建主様のような笑顔溢れるご家庭が</p><p>もっともっと増えますように...</p><p>家づくりを通じて、1人でも多く</p><p>幸せな人生を送ってほしい…</p><p>建主様のような尊い</p><p>ご縁がありますように…</p><p>&nbsp;</p><p>そんな想いで、新築体感会を開催させて頂きます。</p><p>&nbsp;</p><p>どうぞ、お時間があれば、私と建主様のお家に会いに来てください。</p><p>素敵な空間をご体感頂けます。</p><p>&nbsp;</p><p>&nbsp;</p><h4 style=\"text-align:center;\"><span style=\"color:hsl(0, 0%, 0%);\"><strong>-共にお家をつくりました-</strong></span></h4><figure class=\"image image_resized\" style=\"width:24.45%;\"><img style=\"aspect-ratio:620/826;\" src=\"/imgs/upload/172846013942071.jpg\" width=\"620\" height=\"826\"></figure><figure class=\"image image_resized\" style=\"width:24.4%;\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/172846014817272.jpg\" width=\"620\" height=\"465\"></figure><p style=\"text-align:center;\">ここでしか聞けない。宝樹の紙芝居</p><p style=\"text-align:center;\">ぜひ聞いてみてください！</p><p style=\"text-align:center;\">聞いていただけたらわかる！</p><p style=\"text-align:center;\">&nbsp;</p><h4 style=\"text-align:center;\"><span style=\"color:hsl(0, 0%, 0%);\"><strong>-お家のみどころ-</strong></span></h4><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">・機械に頼らなくても快適な高氣密高断熱住宅</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">・友喜のしるしマシュマロタッチ</p><p style=\"text-align:center;\">生活に欠かせない綺麗な空氣感</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">・無駄のないストレスフリーな家事動線</p><p style=\"text-align:center;\">家族団らんを生む豊かな回遊動線</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">・美しくてかっこいいコバルトブルーの外観</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">―――――――――――――――――――――――――――――――――――――――――――――――</p><p style=\"text-align:center;\">会場マップ</p><figure class=\"image image_resized\" style=\"width:36.35%;\"><img style=\"aspect-ratio:620/412;\" src=\"/imgs/upload/172846019710873.jpg\" width=\"620\" height=\"412\"></figure><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">駐車場もございます</p><p style=\"text-align:center;\">お子様連れでも問題ありません</p><p style=\"text-align:center;\">のでご安心ください。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">またこの新築体感会は予約無しでも問題ありませんが、</p><p style=\"text-align:center;\">予約者優先となっております。</p><p style=\"text-align:center;\">ご来場者数によってはお待ちいただく場合が</p><p style=\"text-align:center;\">ありますのでご注意ください。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">お会いできることを楽しみにしています。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">何卒、よろしくお願いいたします。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">以上</p>', NULL, '設定しない', '2024-10-09 16:43:00', '2024-11-28 10:23:57', NULL, 1);
INSERT INTO `events` VALUES (154, 8, '≪出水市高尾野町≫完成見学会「共に手掛けた家」', '完成見学会', '予約承認制', '[{\"date\":\"2023-06-17\",\"time\":[600,1020]},{\"date\":\"2023-06-18\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '出水市', '高尾野町下高尾野', '1016-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172846039949674.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 夫婦+子供, 4K/DK/LDK, 庭あり, 耐震住宅, デザイン住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 子育て, 家事動線, 収納, DIY, 駐車場あり', '<h3><strong>普通、お家は工務店やハウスメーカー</strong></h3><h3><strong>がつくるんじゃないの？</strong></h3><h3>&nbsp;</h3><p>間違いではないですが、正解でもありません。</p><p>高度経済成長期前の家づくりは工務店だけやハウスメーカーだけがつくるのではなく、「みんなで一緒につくる」が当たり前でした。それが市場経済発展、住宅ローンが導入され、ハウスメーカー中心のお家づくりになりました。するとお家が、つくるもの、から商品へと変わりました。</p><p>&nbsp;</p><p>わたしたちアイランドホームは家づくりは人生づくりだと考えています。</p><p>&nbsp;</p><p>建てたお家は「アイランドホームのお家」ではなく、「わたしたちのお家」と思っていただきたい。担当した私としても、お家を家族と同じように愛して育ててほしい、そんな想いも込めています。だからこそ、可能な範囲で、建主様も一緒に手掛けていただいています。そして今回の建主様は土地の造成工事、電氣工事、給排水設備工事、内装工事をしていただきました。</p><p>&nbsp;</p><p>枠にとらわれないプランニングや豊かな開放感、ぬくもりを感じる自然素材、空氣を整えるぬりかべ等魅力を感じられる住まいになっています。それはどこの住宅メーカーでもできます。</p><p>&nbsp;</p><h4><span style=\"color:hsl(0,0%,0%);\"><strong>「共に手掛けたお家」だからこそ、</strong></span></h4><h4><span style=\"color:hsl(0,0%,0%);\"><strong>素晴らしく、尊い「もの」がこのお家にはあります。</strong></span></h4><figure class=\"image image_resized\" style=\"width:33.34%;\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/172846056445075.jpg\" width=\"620\" height=\"465\"></figure><p>&nbsp;</p><p>この見学会に参加することで、あなたの理想の住まいを実現するためのヒントが得られるかもしれません。ぜひ、この機会にご家族でお越しください。皆様のご来場をお待ちしております。</p>', '<p>​</p><p>&nbsp;同時開催！</p><h4><span style=\"color:hsl(0,0%,0%);\"><strong>友喜のしるし　マシュマロタッチぬりかべ体験会開催</strong></span></h4><figure class=\"image image_resized\" style=\"width:28.69%;\"><img style=\"aspect-ratio:620/620;\" src=\"/imgs/upload/172846062657476.jpg\" width=\"620\" height=\"620\"></figure><p><strong>​​</strong></p><p>このお家でも使われている「友喜のしるし　マシュマロタッチ」のぬりかべ体験も同時開催いたします。ご予約制になっておりますので、見学会で体感いただき、塗って体験ください。</p><p>&nbsp;</p><p>ご縁のある「わかる方」には体験の楽しさ、わかりますよ～♪</p><p>&nbsp;</p><p>ぜひご予約ください。</p><p>※雨天時は中止とさせていただきます。</p>', '設定しない', '2024-10-09 16:51:00', '2024-11-28 10:23:59', NULL, 1);
INSERT INTO `events` VALUES (155, 8, '≪姶良市平松≫3棟同時！オープンハウス', '建売販売会', '予約制', '[{\"date\":\"2024-07-06\",\"time\":[600,1020]},{\"date\":\"2024-07-07\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172846080782377.jpg', 0, NULL, '平屋住宅, ハイグレード住宅, 自然素材使用, 高気密・高断熱素材使用, 住宅ローン相談可, ナチュラル, 戸建て・一軒家, 木造住宅, 家事動線, 収納, 4K/DK/LDK, 駐車場あり', '<h4><span style=\"color:hsl(0, 0%, 0%);\">​ ようこそ！3棟同時オープンハウスの予約ページへ</span></h4><p>&nbsp;</p><p>こんにちは。アイランドホームの山口です。</p><p>チラシを手に取って頂いてこのページにお越しくださった方…</p><p>HPをたどっていたら偶然このページにたどり着いてしまった方…</p><p>元々当社や家づくりに興味を持ってくださっていた方…</p><p>このページに来ていただき誠にありがとうございます。</p><p>チラシを見ていただいた方は重複してしまいますが、私たちの氣持ちを書かせてください。</p><p>&nbsp;</p><p style=\"text-align:justify;\"><strong>～24時間365日吸い続けるものだから～</strong></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">約3年前、私は地球の空氣に戻す塗り壁</p><p style=\"text-align:justify;\">「友喜のしるしマシュマロタッチ」</p><p style=\"text-align:justify;\">に出会いました。これまでたくさん勉強</p><p style=\"text-align:justify;\">しないと氣が済まず、そして疑い深く、</p><p style=\"text-align:justify;\">難しく考えるタイプの私でしたが、</p><p style=\"text-align:justify;\">どういうわけか出会ったときはこう思いました。</p><p style=\"text-align:justify;\">「こんな家づくりがしたかった！」とビビッと</p><p style=\"text-align:justify;\">感動したのを覚えています。なぜなら湿氣っぽく、</p><p style=\"text-align:justify;\">かび臭い空間がまるで森の中にいるような</p><p style=\"text-align:justify;\">清浄な空氣感に変わったからです。</p><p style=\"text-align:justify;\">なんとも言えない心地よさ。今まで何やってたんだろうと</p><p style=\"text-align:justify;\">思わされるほど。</p><p style=\"text-align:justify;\">そしてそれから家づくりだけでなく、私の人生が大きく変わり始めました。。。</p><p style=\"text-align:justify;\">&nbsp;</p><figure class=\"image image_resized\" style=\"width:30.11%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172846095158978.jpg\" width=\"620\" height=\"827\"></figure><p style=\"text-align:justify;\">​</p><p style=\"text-align:justify;\"><strong>～せっかくお金を掛けるなら～</strong></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">「壁紙」という言葉を聞いたことがあるでしょうか？</p><p style=\"text-align:justify;\">お家の中に使われる内装材ですね。壁紙といいますが、</p><p style=\"text-align:justify;\">実は「紙」ではありません。</p><p style=\"text-align:justify;\">正式名称は「ビニールクロス」といいます。</p><p style=\"text-align:justify;\">日本の新築の95％以上の住宅は</p><p style=\"text-align:justify;\">ビニールクロスだと言われています。</p><p style=\"text-align:justify;\">知っていただきたいのは、</p><p style=\"text-align:justify;\">ビニールクロスはビニール袋の兄弟だということです。</p><p style=\"text-align:justify;\">子どもの頃、ビニール袋をかぶって遊んで、</p><p style=\"text-align:justify;\">両親から叱られた経験はないでしょうか？</p><p style=\"text-align:justify;\">かぶったことがある方は分かると思いますが呼吸できず苦しいですよね。</p><p style=\"text-align:justify;\">今回ご紹介するお家は、</p><p style=\"text-align:justify;\">地球の空氣に戻す塗り壁のお家です。</p><p style=\"text-align:justify;\">鹿児島県内、姶良市で唯一、</p><p style=\"text-align:justify;\">建売で採用しているのはなんと当社のお家だけ。</p><p style=\"text-align:justify;\">ここに来れば呼吸する空間を体験できちゃいます。</p><p style=\"text-align:justify;\">誰でも簡単に素手でも</p><p style=\"text-align:justify;\">塗れてビニールクロスの上からも直接塗れるので、</p><p style=\"text-align:justify;\">社員だけで塗ったお家もあります。</p><p style=\"text-align:justify;\">それでは、毎日家族で過ごすお家が、ビニール袋に包まれて</p><p style=\"text-align:justify;\">呼吸できない空間だったらどうでしょうか？</p><p style=\"text-align:justify;\">子どもの頃ビニール袋をふざけてかぶる私に母はこう叱りました。</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">「そんなことしてたら息できなくて死んじゃうでしょ！」</p><p style=\"text-align:justify;\">&nbsp;</p><figure class=\"image image_resized\" style=\"width:30.37%;\"><img style=\"aspect-ratio:620/826;\" src=\"/imgs/upload/172846098632679.jpg\" width=\"620\" height=\"826\"></figure><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\"><strong>～人生が変わる、後悔しない家づくり～</strong></p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">当社に限らず、この建築業界ではある課題がつきまといます。</p><p style=\"text-align:justify;\">それは家づくりをされた、買われたほとんどの方が</p><p style=\"text-align:justify;\">「失敗した」「後悔した」と思われていること。</p><p style=\"text-align:justify;\">技術も進歩したのになぜ？</p><p style=\"text-align:justify;\">みんな後悔しないように建てたのになぜ？</p><p style=\"text-align:justify;\">これだけ情報があって、</p><p style=\"text-align:justify;\">誰でも簡単にその情報を得られる時代なのになぜ？</p><p style=\"text-align:justify;\">家づくりに絶対に必要なことは一つもでてこないのか？</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">◆家づくりって何を基準にしたらいいの？</p><p style=\"text-align:justify;\">◆住宅会社の選び方がわからない？</p><p style=\"text-align:justify;\">◆間違いだらけの土地、建物選び…</p><p style=\"text-align:justify;\">◆高氣密高断熱はどうして必要なのか？</p><p style=\"text-align:justify;\">◆地震、災害が氣になる…</p><p style=\"text-align:justify;\">◆予算の決め方がわからない</p><p style=\"text-align:justify;\">◆間取りをどうしたらいいのかわからない…</p><p style=\"text-align:justify;\">◆家は何年もてばいいのか…</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">ほとんどの人がこんなことに</p><p style=\"text-align:justify;\">悩みながら結局、</p><p style=\"text-align:justify;\">家づくりの本質に触れることなく、</p><p style=\"text-align:justify;\">住宅計画を進め、家を購入するのです。</p><p style=\"text-align:justify;\">建築のプロがいなくなってしまった現代では、</p><p style=\"text-align:justify;\">家づくりではおろか</p><p style=\"text-align:justify;\">さらに不安を感じる情報が飛び込んできます。</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">★日本経済、先行き不透明で不安ばかり…</p><p style=\"text-align:justify;\">　ローンを組んでもいいのか？</p><p style=\"text-align:justify;\">★いいことばかり、不安なことばかり言う</p><p style=\"text-align:justify;\">　営業マンの話や広告にはうんざり、どうしていいものか</p><p style=\"text-align:justify;\">★ネットやSNSで情報収集すればするほど</p><p style=\"text-align:justify;\">　結局どうしたらいいのかわからない…</p><p style=\"text-align:justify;\">★昔は夢のマイホーム…、今は不安のマイホーム…、</p><p style=\"text-align:justify;\">　そもそもなぜ不安ばかりよぎるのか？</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">一生暮らす家なのに、家づくりが根本的に間違っています。</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">&nbsp;</p><p style=\"text-align:justify;\">私自身住宅業界に12年近く携わらせていただき、</p><p style=\"text-align:justify;\">間違い、誤解、勘違いしていたことがあります。</p><p style=\"text-align:justify;\">それは家づくりが本当の意味で分かっていなかったこと</p><p style=\"text-align:justify;\">でした。これまでも真剣におひとり、</p><p style=\"text-align:justify;\">おひとりの人生を考えながら家づくりをしていたつもりでした。</p><p style=\"text-align:justify;\">だからこそ氣づいてしまった家づくりの本質があります。</p><p style=\"text-align:justify;\">ただし、これから家づくりをする方も、家を買われる方も、</p><p style=\"text-align:justify;\">すでにお家を持っていらっしゃる方も安心してください。</p><p style=\"text-align:justify;\">このオープンハウスにたどり着いただけで、</p><p style=\"text-align:justify;\">後悔しない家づくりの第一歩を歩みはじめていますよ。</p><figure class=\"image image_resized\" style=\"width:29.59%;\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/172846108393780.jpg\" width=\"620\" height=\"465\"></figure><p style=\"text-align:justify;\">​</p><p style=\"text-align:justify;\">【オープンハウス受付場所】</p><p style=\"text-align:justify;\">平屋の分譲住宅にスタッフが待機しております。</p><p style=\"text-align:justify;\">姶良市平松のつながり整骨院を曲がっていただき真っ直ぐ。</p><p style=\"text-align:justify;\">付近に目じるし看板を設置する予定です。</p><p style=\"text-align:justify;\">グーグルマップでは〒899-5652　姶良市平松4919-4付近になります。</p><p style=\"text-align:justify;\">&nbsp;</p><h4 style=\"text-align:justify;\"><span style=\"color:hsl(0, 0%, 0%);\">皆様にお会いできるのを心より楽しみにしております。</span></h4>', NULL, '設定しない', '2024-10-09 16:58:00', '2024-11-28 10:23:59', NULL, 1);
INSERT INTO `events` VALUES (156, 8, '≪姶良市平松≫構造見学会＆洗車体験会', '構造見学会', '予約制', '[{\"date\":\"2024-08-10\",\"time\":[540,900]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '平松', '2087-15', '地図にピンを表示する', '住所を全て記載する', NULL, 0, NULL, 'デザイン住宅, ハイグレード住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, シンプル, ナチュラル, 夫婦+子供, 庭あり, 木造住宅, 家事動線, 収納, 駐車場あり', '<p style=\"text-align:center;\">この度、建物様のご厚意により</p><p style=\"text-align:center;\">ご挨拶と感謝。上棟式に伴う餅まき会</p><p style=\"text-align:center;\">いい空間づくりを体感できる構造見学会</p><p style=\"text-align:center;\">空氣のはたらき、水のありがたみを体験できる洗車体験</p><p style=\"text-align:center;\">.</p><p style=\"text-align:center;\">餅まき会は17時からスタートです。自由参加となっております。</p><p style=\"text-align:center;\">また餅まきについてはお車でのお越しはお控えください。</p><p style=\"text-align:center;\">.</p><p style=\"text-align:center;\">構造見学会と洗車体験はご予約頂きますとスムーズに</p><p style=\"text-align:center;\">ご案内可能でございます。</p><p style=\"text-align:center;\">ご予約無しでの来場も問題ありませんが、</p><p style=\"text-align:center;\">ご予約優先ではありますのでお待ち頂く場合もありますので、</p><p style=\"text-align:center;\">ご予約をおすすめ致します。</p><p style=\"text-align:center;\">多少お水がかかっても大丈夫な格好でお越しください。</p><p style=\"text-align:center;\">.</p><p style=\"text-align:center;\">皆様にお会いできるのを楽しみにしております！</p>', NULL, '設定しない', '2024-10-09 17:06:00', '2024-11-28 10:24:00', NULL, 1);
INSERT INTO `events` VALUES (157, 8, '≪姶良市≫8棟同時！オープンハウス！', 'モデルハウス', '予約制', '[{\"date\":\"2023-07-08\",\"time\":[600,1020]},{\"date\":\"2023-07-09\",\"time\":[600,1020]},{\"date\":\"2023-07-15\",\"time\":[600,1020]},{\"date\":\"2023-07-16\",\"time\":[600,1020]},{\"date\":\"2023-07-17\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172846179078211.png,/imgs/events/172846179542312.png,/imgs/events/172846179899513.png,/imgs/events/172846180296514.png,/imgs/events/172846180657615.png,/imgs/events/172846181020016.png,/imgs/events/172846181395517.png,/imgs/events/172846181721718.png,/imgs/events/172846182075119.png', 0, NULL, '平屋住宅, デザイン住宅, ハイグレード住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 住宅ローン相談可, シンプル, ナチュラル, リフォーム住宅, リノベーション住宅, 庭あり, 家事動線, 収納, DIY, 駐車場あり', '<p>​</p><p>住まいの出発店。アイランドホームです✨</p><p>この度8棟同時オープンハウスを開催！</p><p>&nbsp;</p><p>個性あふれる物件をぜひ現地でご体感ください♪</p><p>ネットや紙だけでは感じることのできない空間がここにあります！</p><p>&nbsp;</p><p>ぜひご予約ください♪</p><p>&nbsp;</p><p>①≪姶良市平松≫2階建　2,780万円</p><figure class=\"image image_resized\" style=\"width:51.35%;\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172846191822212.png\" width=\"1024\" height=\"768\"></figure><p>​</p><p>②≪姶良市平松≫2階建　2,783万円</p><figure class=\"image image_resized\" style=\"width:51.77%;\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172846193746213.png\" width=\"1024\" height=\"768\"></figure><p>&nbsp;</p><p>③≪姶良市平松≫平屋　2,938万円</p><figure class=\"image image_resized\" style=\"width:51.81%;\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172846195661214.png\" width=\"1024\" height=\"768\"></figure><p>&nbsp;</p><p>④≪姶良市平松≫2階建　3,220万円​</p><figure class=\"image image_resized\" style=\"width:52.16%;\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172846198829015.png\" width=\"1024\" height=\"768\"></figure><p>&nbsp;</p><p>⑤≪姶良市西餅田≫平屋　3,680万円</p><figure class=\"image image_resized\" style=\"width:52.58%;\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172846200382216.png\" width=\"1024\" height=\"768\"></figure><p>​</p><p>⑥≪姶良市東餅田≫リフォーム平屋　980万円</p><figure class=\"image image_resized\" style=\"width:52.55%;\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172846203372717.png\" width=\"1024\" height=\"768\"></figure><p>​</p><p>⑦≪姶良市東餅田≫リフォーム2階建　1,750万円</p><figure class=\"image image_resized\" style=\"width:52.53%;\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172846204398618.png\" width=\"1024\" height=\"768\"></figure><p>​</p><p>⑧≪姶良市加治木町≫リフォーム平屋　1,890万円</p><figure class=\"image image_resized\" style=\"width:52.77%;\"><img style=\"aspect-ratio:1024/768;\" src=\"/imgs/upload/172846206034919.png\" width=\"1024\" height=\"768\"></figure><p>​</p><p>皆様のご予約お待ちしております✨</p><p>&nbsp;</p><p>※お詫びと訂正※</p><p>チラシをご覧頂いてアクセス頂きましたお客様へ</p><p>&nbsp;</p><p>友喜のしるしマシュマロタッチの説明に「漆喰」という表記がありますがこちらは「健康」の誤りです。厳密にいえば友喜のしるしマシュマロタッチは漆喰ではなく、塗料になりますので全く違うものになります。</p><p>&nbsp;</p><p>この度は記載に誤りがあり、誠に申し訳ございません。</p><p>&nbsp;</p><p>この件について聞きたいことがある方は担当山口大貴（080-4133-2543）まで直接お問い合わせください。</p>', NULL, '設定しない', '2024-10-09 17:07:00', '2024-11-28 10:24:00', NULL, 1);
INSERT INTO `events` VALUES (158, 8, '≪姶良市船津≫オープンハウス‐26坪の平屋 新築お披露目会-', '完成見学会', '予約制', '[{\"date\":\"2024-09-14\",\"time\":[840,1020]},{\"date\":\"2024-09-15\",\"time\":[600,1020]},{\"date\":\"2024-09-16\",\"time\":[780,1020]},{\"date\":\"2024-09-17\",\"time\":[600,1020]},{\"date\":\"2024-09-19\",\"time\":[780,1020]},{\"date\":\"2024-09-20\",\"time\":[600,1020]},{\"date\":\"2024-09-21\",\"time\":[600,900]},{\"date\":\"2024-09-22\",\"time\":[600,1020]},{\"date\":\"2024-09-23\",\"time\":[780,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '船津126-2', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172846240060981.jpg,/imgs/events/172846240403182.jpg', 0, NULL, '新築, 家づくりは人生づくり, 呼吸する空間, 居心地のいい空間, 友喜のしるしマシュマロタッチ, ウルトラファインバブル, 絶対に後悔しない家づくり, ありがとう, 平屋, 26坪, 明るく開放的, ココでしか伝えられないことがある', '<p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">&nbsp;こんにちは。</p><p style=\"text-align:center;\">主催者のアイランドホームの山口と申します。</p><p style=\"text-align:center;\">ご予約ページにお越しくださり</p><p style=\"text-align:center;\">誠にありがとうございます。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">この度、建主様のご厚意により9月14日から23日まで</p><p style=\"text-align:center;\">新築お披露目会を開催させて頂くことになりました。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">皆様にお会いできるのを</p><p style=\"text-align:center;\">心より楽しみにしております。</p><p style=\"text-align:center;\">​</p><figure class=\"image image_resized\" style=\"width:28.38%;\"><img style=\"aspect-ratio:620/438;\" src=\"/imgs/upload/172846253570820.png\" width=\"620\" height=\"438\"></figure><p style=\"text-align:center;\"><span style=\"background-color:#16a085;color:#ffffff;\">◆明るくて居心地の良い空間を体感してほしい</span></p><p style=\"text-align:center;\">家づくりは人生づくり、空間づくりです。</p><p style=\"text-align:center;\">建主様は、お見事、幸せな家づくりをされました！</p><p style=\"text-align:center;\">さかのぼること約1年前、</p><p style=\"text-align:center;\">建主様が、家づくりをしようと思われたとき</p><p style=\"text-align:center;\">一番最初に出会ったのが私たちでした。</p><p style=\"text-align:center;\">モデルハウスを見学するのも</p><p style=\"text-align:center;\">初めてだったようです。</p><p style=\"text-align:center;\">その後数社回られそうなのですが、</p><p style=\"text-align:center;\">大変有難いことにご縁を頂きました。</p><p style=\"text-align:center;\">まさに運命の出会いですね。</p><p style=\"text-align:center;\">笑顔が素敵な奥様、思いやりのあるご主人、</p><p style=\"text-align:center;\">元氣いっぱいのお子様で、</p><p style=\"text-align:center;\">私どもにもとても親切にしていただきました。</p><p style=\"text-align:center;\">お打合せの際もたくさんの氣遣い、</p><p style=\"text-align:center;\">心遣いをしてくださり、その空氣感だけでも</p><p style=\"text-align:center;\">本当にいい家づくりをされているなと感じていました。</p><p style=\"text-align:center;\">塗り壁体感会では共に施工をしていただき</p><p style=\"text-align:center;\">このご家族にしかデザインすることのできない</p><p style=\"text-align:center;\">空間をつくってくださいました。</p><p style=\"text-align:center;\">唯一無二の世界にひとつだけの空間。</p><p style=\"text-align:center;\">建主様の心があらわれた、ココにしかないお家です。</p><p style=\"text-align:center;\">建主様はおひとりでも多くの方に</p><p style=\"text-align:center;\">「明るくて、居心地のいい空間・空氣」</p><p style=\"text-align:center;\">を感じ、家づくりやリフォームで悩んでいる方</p><p style=\"text-align:center;\">のお力になれたらという想いもあり、</p><p style=\"text-align:center;\">この度、新築お披露目会を</p><p style=\"text-align:center;\">開催させてただくことになりました。</p><p style=\"text-align:center;\">貴重で、二度とない機会をありがとうございます。</p><p style=\"text-align:center;\">&nbsp;</p><figure class=\"image image_resized\" style=\"width:27.11%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172846257245483.jpg\" width=\"620\" height=\"827\"></figure><figure class=\"image image_resized\" style=\"width:27.1%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172846260485084.jpg\" width=\"620\" height=\"827\"></figure><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\"><span style=\"background-color:#16a085;color:#ffffff;\">◆家づくりには極意がある</span></p><p style=\"text-align:center;\">これまで後悔しない家づくりをするためには</p><p style=\"text-align:center;\">家の条件が大切だと思っていました。</p><p style=\"text-align:center;\">例えば高気密高断熱、太陽光、耐震</p><p style=\"text-align:center;\">耐久性の高い外壁、利便性の高い設備</p><p style=\"text-align:center;\">おしゃれなデザイン、家事ラクな動線</p><p style=\"text-align:center;\">広いリビング、かっこいい内装など、</p><p style=\"text-align:center;\">お客様のためにという想いで</p><p style=\"text-align:center;\">たくさんの条件を揃えようととしていました。</p><p style=\"text-align:center;\">ただ、そうしていく中で私たちは</p><p style=\"text-align:center;\">様々な現象を見させられました。</p><p style=\"text-align:center;\">一例として、そういった条件をほぼ完璧にそろえて</p><p style=\"text-align:center;\">お金もかかっているお家なのに</p><p style=\"text-align:center;\">「お客様が心底、喜んでいらっしゃらない」</p><p style=\"text-align:center;\">ということがありました。</p><p style=\"text-align:center;\">なんででしょうか？</p><p style=\"text-align:center;\">そして住宅業界全体で氣がかりなこともあります。</p><p style=\"text-align:center;\">それは家を建てたほとんどの方が</p><p style=\"text-align:center;\">「後悔」「失敗」と感じていることでした。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">こんなに条件をそろえて建てたのになぜ？</p><p style=\"text-align:center;\">お客様の要望を叶えたのになぜ？</p><p style=\"text-align:center;\">お客様の不安にひとつひとつ答えてきたのになぜ？</p><p style=\"text-align:center;\">後悔したくないという思いで建てたはずなのになぜ？</p><p style=\"text-align:center;\">誰でも簡単に情報を得られるのになぜ？</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">私自身、住宅業界に11年近く携わらせていただき</p><p style=\"text-align:center;\">誤解、間違い、勘違いをしていたことがあります。</p><p style=\"text-align:center;\">それは家づくりが本当の意味で</p><p style=\"text-align:center;\">わかっていなかったことでした。</p><p style=\"text-align:center;\">だからこそ氣付いてしまった</p><p style=\"text-align:center;\">家づくりの本質、極意があります。</p><p style=\"text-align:center;\">家づくり、絶対に後悔してほしくありません。</p><p style=\"text-align:center;\">この新築お披露目会では、家づくりの極意のヒント</p><p style=\"text-align:center;\">を感じることができるかもしれません。</p><figure class=\"image image_resized\" style=\"width:27.35%;\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/172846263729385.jpg\" width=\"620\" height=\"465\"></figure><p style=\"text-align:center;\">​</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">◆空氣のはたらきのありがたみ</p><p style=\"text-align:center;\">私たち人間は、空氣とお水がなければ</p><p style=\"text-align:center;\">生きていくことはできません。</p><p style=\"text-align:center;\">空氣の中にお水があり、</p><p style=\"text-align:center;\">そしてお水の中にも空氣が入っています。</p><p style=\"text-align:center;\">実はお水の中の空氣の大きさを小さくすると</p><p style=\"text-align:center;\">私たちの暮らしにとても有難い</p><p style=\"text-align:center;\">はたらきをしてくれます。</p><p style=\"text-align:center;\">目に見えない本当に小さな氣泡、</p><p style=\"text-align:center;\">それがウルトラファインバブルです。</p><p style=\"text-align:center;\">このお家は全ての水道から</p><p style=\"text-align:center;\">ウルトラファインバブル水が出ます。</p><p style=\"text-align:center;\">特にびっくりするのが味です。</p><p style=\"text-align:center;\">塩素が匂うお水が、</p><p style=\"text-align:center;\">一瞬でリフレッシュになります。</p><p style=\"text-align:center;\">また私個人が体験してびっくりしたのが洗車です。</p><p style=\"text-align:center;\">ウルトラファインバブル水で洗車をすると</p><p style=\"text-align:center;\">「まるで赤ちゃんのお肌のようにお水を弾くようになった」</p><p style=\"text-align:center;\">のです！</p><p style=\"text-align:center;\">空氣のはたらきのおかげ様で</p><p style=\"text-align:center;\">汚れが付着しづらくなり</p><p style=\"text-align:center;\">コーティングのような効果が約2週間続きました。</p><p style=\"text-align:center;\">ご希望の方は、洗車体験も可能です。</p><p style=\"text-align:center;\">ご予約の際にお伝えくださいませ。</p><figure class=\"image image_resized\" style=\"width:28.09%;\"><img style=\"aspect-ratio:620/349;\" src=\"/imgs/upload/172846267098286.jpg\" width=\"620\" height=\"349\"></figure><figure class=\"image image_resized\" style=\"width:27.82%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172846267970687.jpg\" width=\"620\" height=\"827\"></figure><p style=\"text-align:center;\">↑コーティングしたかのように水を弾いています</p><p style=\"text-align:center;\">（洗車をしたのは左側のみ）</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">≪ご案内≫</p><p style=\"text-align:center;\">グーグルマップで検索！：姶良市船津118-1</p><p style=\"text-align:center;\">マンションの隣分譲地です♪</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">※ご予約の方優先になるためお時間を無駄に</p><p style=\"text-align:center;\">されたくない場合はご予約をおすすめします。</p><p style=\"text-align:center;\">※土日はスタッフが駐在していますが、</p><p style=\"text-align:center;\">平日は駐在していないためご予約くださいませ。</p><p style=\"text-align:center;\">※ご予約された方は一度お電話にて</p><p style=\"text-align:center;\">確認させていただく場合がございます。</p><p style=\"text-align:center;\">※お披露目には最低1時間は要しますので</p><p style=\"text-align:center;\">お時間にゆとりをもってご来場ください。</p><p style=\"text-align:center;\">※近隣に来ていただきますと</p><p style=\"text-align:center;\">案内看板と旗がございます。</p><p style=\"text-align:center;\">※お子様連れOK、駐車場完備しています。</p><p style=\"text-align:center;\">※ご飲食はできませんのでご注意ください。</p><p style=\"text-align:center;\">※お手洗いはありませんので済ませて</p><p style=\"text-align:center;\">ご来場ください。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">≪担当者の連絡先≫</p><p style=\"text-align:center;\">山口　080-4133-2543</p><p style=\"text-align:center;\"><a href=\"https://line.me/ti/p/bcg495v8wA\">ラインからもお問い合わせできます！</a></p><p style=\"text-align:center;\">&nbsp;</p>', NULL, '設定しない', '2024-10-09 17:24:00', '2024-11-28 10:24:03', NULL, 1);
INSERT INTO `events` VALUES (159, 8, '株式会社アイランドホーム　展示場モデルハウス', '展示会', '予約制', '[{\"date\":\"2024-10-01\",\"time\":[600,1020]},{\"date\":\"2024-10-03\",\"time\":[600,1020]},{\"date\":\"2024-10-04\",\"time\":[600,1020]},{\"date\":\"2024-10-05\",\"time\":[600,1020]},{\"date\":\"2024-10-06\",\"time\":[600,1020]},{\"date\":\"2024-10-07\",\"time\":[600,1020]},{\"date\":\"2024-10-08\",\"time\":[600,1020]},{\"date\":\"2024-10-10\",\"time\":[600,1020]},{\"date\":\"2024-10-11\",\"time\":[600,1020]},{\"date\":\"2024-10-12\",\"time\":[600,1020]},{\"date\":\"2024-10-13\",\"time\":[600,1020]},{\"date\":\"2024-10-14\",\"time\":[600,1020]},{\"date\":\"2025-01-28\",\"time\":[600,1020]},{\"date\":\"2025-01-30\",\"time\":[600,1020]},{\"date\":\"2025-01-31\",\"time\":[600,1020]},{\"date\":\"2025-02-01\",\"time\":[600,1020]},{\"date\":\"2025-02-02\",\"time\":[600,1020]},{\"date\":\"2025-02-03\",\"time\":[600,1020]},{\"date\":\"2025-02-04\",\"time\":[600,1020]},{\"date\":\"2025-02-06\",\"time\":[600,1020]},{\"date\":\"2025-02-07\",\"time\":[600,1020]},{\"date\":\"2025-02-08\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田', '2511-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172846314251188.jpg', 0, '/imgs/events/172846342214221.png', '平屋住宅, デザイン住宅, ハイグレード住宅, 無垢材使用, 自然素材使用, 高気密・高断熱素材使用, 住宅ローン相談可, 保険相談可, 税金相談可, 仲介手数料相談可, 補助金相談可, シンプル, ナチュラル', '<h4><span style=\"color:hsl(0, 0%, 0%);\"><strong>ようこそ</strong></span></h4><p>&nbsp;</p><p>アイランドホームの家づくりに興味</p><p>持ってくださった方へ</p><p>よくぞこのページに来ていただきました！</p><p>このモデルハウスの担当しています、</p><p>山口大貴（やまぐち　ひろたか）と申します。</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_7086-599x800.jpg\" alt=\"\" width=\"223\" height=\"298\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080420image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>微力ながらも私にできることはないか考え、</p><p>私の家づくりに対する想いをこのモデルハウスに</p><p>込めさせていただきました。</p><p>&nbsp;</p><p>私たちの想い</p><p>&nbsp;</p><p>それは、</p><p><strong>★家づくりは人生づくり、空間づくり。</strong></p><p>&nbsp;</p><p><strong>★家は本来呼吸している。</strong></p><p><strong>人間も建築も大切なのは空氣を整えること</strong></p><p>&nbsp;</p><p><strong>★今までの固定観念を柔らかくして、</strong></p><p><strong>より豊かな暮らしがあることに氣付いてほしい。</strong></p><p>&nbsp;</p><p>という想いを込めさせていただきました。</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_6028-1-800x600.jpg\" alt=\"\" width=\"349\" height=\"262\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080420image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>共に、みんなで手掛けました</p><p>&nbsp;</p><p>建築がはじまります。</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4647-1-800x600.jpg\" alt=\"\" width=\"471\" height=\"353\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080420image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4649-1-800x600.jpg\" alt=\"\" width=\"539\" height=\"404\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080420image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4654-1-600x800.jpg\" alt=\"\" width=\"443\" height=\"591\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080420image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4655-1-800x600.jpg\" alt=\"\" width=\"566\" height=\"425\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080420image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4641-1-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080512image.gif\" width=\"15\" height=\"15\"></span>​</p><p>↑私たちの頼りになる大工さん</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4655-800x600.jpg\" alt=\"\" width=\"581\" height=\"436\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080550image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4645-1-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080550image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_5424-1-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080550image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_5423-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080551image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>モデルハウスの空氣をととのえる</p><p>呼吸する塗壁は、</p><p>私とスタッフで想いを込めて、</p><p>仕上げております</p><p>塗壁の師匠にもお手伝いいただきました。</p><p>&nbsp;</p><p>だれでも簡単に素手でも塗れる。</p><p>塗るとわかりますが、空氣が塗り替わり、</p><p>体と心が反応して</p><p>とにかく素直に楽しくなれるのです</p><p>&nbsp;</p><p>新築を建築いただいたお客様には</p><p>必ずご体験いただいています</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_5696-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080551image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_5701-800x600.jpg\" alt=\"\" width=\"616\" height=\"462\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080607image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1882-599x800.jpg\" alt=\"\" width=\"599\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080668image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1887-1-599x800.jpg\" alt=\"\" width=\"599\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080761image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1889-2-599x800.jpg\" alt=\"\" width=\"599\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080761image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1891-599x800.jpg\" alt=\"\" width=\"599\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080761image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><strong>グループスタッフみんなで、共につくった</strong></p><p>&nbsp;</p><p><strong>まさに、ここにしかない空氣、空間を体感できます。</strong></p><p>&nbsp;</p><p>こんな方にも来ていただきたい。</p><p>&nbsp;</p><p>家づくりは大きいお買い物、家づくりは</p><p>一生に一度とも言われています。</p><p>だからこそ情報を集めようとすることは</p><p>当たり前です。</p><p>最近ではインスタグラム、YouTube、ブログなど、</p><p>家づくりに関する情報はちょっと検索するだけで</p><p>たくさん出てきます。</p><p>&nbsp;</p><p>&nbsp;</p><p>しかしながら</p><p>&nbsp;</p><p>&nbsp;</p><p>これだけ情報があって、誰でも簡単に</p><p>その情報を得られる時代なのに</p><p>なぜ？</p><p>家づくりに絶対に必要なことは</p><p>ひとつも出てこないのか？・・・</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/26624853_s.jpg\" alt=\"\" width=\"416\" height=\"278\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080761image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>このような時代、</p><p><strong>家づくりはおろかさらに不安を感じる</strong></p><p><strong>情報ばかり目に飛び込んできます。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p>・先行き不透明な日本経済、家を建ててもいいの？</p><p>・住宅ローンを組んでも大丈夫？どうしたらいい？</p><p>・いいことばかり、不安なことばかり言う営業マン</p><p>・さらに住宅会社によって違うことを言われる</p><p>・何を信じたらいいのかわからない</p><p>・検索して情報を集めようとすればするほど、</p><p>　結局どうしたらいいのかわからない</p><p>・夢のマイホームがまるで不安のマイホーム</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/26881209_m-800x533.jpg\" alt=\"\" width=\"597\" height=\"398\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080833image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>もし上記のような感覚を持っていらっしゃる方</p><p>は、ぜひ一度はこのモデルハウスを体感</p><p>していただきたい。</p><p>&nbsp;</p><p>&nbsp;</p><p>私自身この業界12年近く携わらせていただき、</p><p>誤解、間違い、勘違いをしていたことがあります。</p><p>それは本当の意味で「家づくり」がわかって</p><p>いなかったことでした。</p><p>もちろんこれまでも真剣に一人一人の方の人生を</p><p>考えながら家づくりをしていたつもりでした。</p><p>だからこそ<strong>氣付いてしまった</strong>ことがあります。</p><p>私とお話をしてみませんか？</p><p><strong>家づくりにも本質、極意があるのです。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1880-800x533.jpg\" alt=\"\" width=\"527\" height=\"351\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080886image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><h3>このご縁とご恩に感謝</h3><p>&nbsp;</p><p>&nbsp;</p><p>スマイルビルダーズ出展企業様</p><p>建築家木内さん</p><p>山口大工さん</p><p>姶良電設さん</p><p>塩満板金さん</p><p>宮脇内装さん</p><p>加治木基礎さん</p><p>㈱FORUMさん</p><p>プロジェクト彰さん</p><p>トータルハラダさん</p><p>ハイアス・アンド・カンパニーさん</p><p>ワイテックサツマさん</p><p>本田住器さん</p><p>小園硝子さん</p><p>ウルトジャパンさん</p><p>サンワカンパニーさん</p><p>YKKAPさん</p><p>ガッキーさん</p><p>ちかこさん</p><p>羽柴師匠、はじめNURIKAETAIの皆様</p><p>そして弊社</p><p>山口俊彦（代表）はじめ</p><p>アイランドホームグループ全スタッフ</p><p>&nbsp;</p><p>そしてこれまで私やアイランドホームで</p><p>家づくりをしてくださったお客様。</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>ありがとうございます。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p>私たちアイランドホームスタッフはお客様の家を、</p><p>「自分の家」「大切な友人、家族」だと思って</p><p>「ありがとう」を込め</p><p>家づくりのパートナーとして</p><p>一生のお付き合いをさせていただきます。</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1881-800x533.jpg\" alt=\"\" width=\"476\" height=\"317\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080918image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>みんなでモデルハウスに想いを込めました。</p><p>それは、</p><p><strong>★家づくりは人生づくり、空間づくり。</strong></p><p>&nbsp;</p><p><strong>★家は本来呼吸している。</strong></p><p><strong>人間も建築も大切なのは空氣を整えること</strong></p><p>&nbsp;</p><p><strong>★今までの固定観念を柔らかくして、</strong></p><p><strong>より豊かな暮らしがあることに氣付いてほしい。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p>そしてただただ<strong>ありがとうございます</strong>という氣持ち。</p><p>&nbsp;</p><p>&nbsp;</p><p>私たちみんなで込めた想いが</p><p><strong>輪（和）のようにひろがれば</strong>うれしいです。</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/4CD05221-9D02-432C-812F-16DD97D458E7-636x800.jpg\" alt=\"\" width=\"345\" height=\"434\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477080918image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>ひろがるいえ～自然と共存～　</strong></p><p><strong>私たちのモデルハウスへぜひ</strong></p><p><strong>体感にお越しください。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p><strong>※またモデルハウス内では安全性の高い中洋水</strong></p><p><strong>（中性電解除菌機能水）を噴霧しているため、</strong></p><p><strong>お客様はマスクを外してご見学ができます。</strong></p><p><strong>ぜひマスクをはずして私たちのつくった空氣、</strong></p><p><strong>空間をご体感ください。</strong></p>', '<h4><span style=\"color:hsl(0, 0%, 0%);\">​<strong> 来場特典</strong></span></h4><p>&nbsp;</p><p>中洋水（中性除菌機能電解水）</p><p>のお試しボトルをプレゼント♪</p><p>&nbsp;</p><p>～効果～</p><p>・空氣をととのえる</p><p>・臭いをとってくれる</p><p>・化粧水替わりになる</p><p>などなど♪とっても便利♪</p><figure class=\"image image_resized\" style=\"width:23.25%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172846347043989.jpg\" width=\"620\" height=\"827\"></figure><p>​</p><p>合言葉は「<strong>共に手掛ける</strong>」です！</p><p>総合展示場のスタッフにお声掛けください！</p>', '設定しない', '2024-10-09 17:35:00', '2024-11-28 10:24:04', NULL, 1);
INSERT INTO `events` VALUES (160, 8, '株式会社アイランドホーム　展示場モデルハウス', '展示会', '予約制', NULL, NULL, '非公開', 0, 0, '鹿児島県', '姶良市', '加治木町木田', NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172847739852490.jpg', 0, '/imgs/events/172847788508721.png', NULL, '<h3><strong>ようこそ</strong></h3><p>&nbsp;</p><p>アイランドホームの家づくりに興味</p><p>持ってくださった方へ！</p><p>よくぞこのページに来ていただきました！</p><p>ありがとうございます。</p><p>このモデルハウスの担当しています、</p><p>山口大貴（やまぐち　ひろたか）と申します。</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_7086-599x800.jpg\" alt=\"\" width=\"223\" height=\"298\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671242image.gif\" width=\"15\" height=\"15\"></span>​</p><p>↑私。最近第一子が誕生しました( •̀ ω •́ )✧</p><p>&nbsp;</p><p>「スマイルビルダーズ姶良総合住宅展示場」は</p><p>弊社アイランドホームが運営している展示場です。</p><p>地元の仲間である住宅会社様のご賛同のおかげで、</p><p>出展、事業運営ができております。</p><p>誠にありがとうございます。</p><p>&nbsp;</p><p>&nbsp;</p><p>そして私はこのような有難い機会を頂き、</p><p>この総合展示場のアイランドホームモデルハウス</p><p>の「担当者」として任されることになりました。</p><p>微力ながらも私にできることはないか考え、</p><p>私の家づくりに対する想いをこのモデルハウスに</p><p>込めさせていただきました。</p><p>&nbsp;</p><p>私たちの想い</p><p>&nbsp;</p><p>それは、</p><p><strong>★家づくりは人生づくりだと伝えたい</strong></p><p><strong>★人間も建築も大切なのは空氣を整えること</strong></p><p><strong>★今までの固定観念を柔らかくして、より豊かな暮らしがあることに氣付いてほしい</strong></p><p><strong>★ありがとうございます。</strong></p><p>&nbsp;</p><p>という想いを込めさせていただきました。</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_6028-1-800x600.jpg\" alt=\"\" width=\"349\" height=\"262\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671241image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>企画から設計、仕様選び、そして施工まで</p><p>本当に楽しく、ワクワクしてつくることができました。</p><p>正直、辛いこときついこともたくさんありました。</p><p>が！家づくりはまさにドラマだなと</p><p>実感させられます！</p><p>だからこそ人生なのですね。</p><p>&nbsp;</p><p>&nbsp;</p><p>共に、みんなで手掛けました</p><p>&nbsp;</p><p>&nbsp;</p><p>建築がはじまります。</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4647-1-800x600.jpg\" alt=\"\" width=\"471\" height=\"353\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671241image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4649-1-800x600.jpg\" alt=\"\" width=\"539\" height=\"404\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671241image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4654-1-600x800.jpg\" alt=\"\" width=\"443\" height=\"591\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671242image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4655-1-800x600.jpg\" alt=\"\" width=\"566\" height=\"425\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671241image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4641-1-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671365image.gif\" width=\"15\" height=\"15\"></span>​</p><p>↑私たちの頼りになる大工さん</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4655-800x600.jpg\" alt=\"\" width=\"581\" height=\"436\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671366image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_4645-1-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671366image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_5424-1-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671367image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_5423-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671368image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>モデルハウスの空氣をととのえる塗壁は、</p><p>私とスタッフで想いを込めて、</p><p>仕上げております！</p><p>塗壁の師匠にもお手伝い</p><p>いただきました。</p><p>ありがとうございます！</p><p>だれでも簡単に素手でも塗れる。</p><p>塗るとわかりますが、空氣が塗り替わり、</p><p>体と心が反応して</p><p>とにかく素直に楽しくなれます！</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_5696-600x800.jpg\" alt=\"\" width=\"600\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671368image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_5701-800x600.jpg\" alt=\"\" width=\"616\" height=\"462\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671488image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1882-599x800.jpg\" alt=\"\" width=\"599\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671489image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1887-1-599x800.jpg\" alt=\"\" width=\"599\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671489image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1889-2-599x800.jpg\" alt=\"\" width=\"599\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671490image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1891-599x800.jpg\" alt=\"\" width=\"599\" height=\"800\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671490image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>グループスタッフみんなで、共につくった</strong></p><p><strong>まさに、ここにしかない空氣、空間を体感できます。</strong></p><p>&nbsp;</p><p>こんな方にも来ていただきたい。</p><p>&nbsp;</p><p>&nbsp;</p><p>家づくりは大きいお買い物、家づくりは</p><p>一生に一度とも言われています。</p><p>だからこそ情報を集めようとすることは</p><p>当たり前ですよね。</p><p>最近ではインスタグラム、YouTube、ブログなど、</p><p>家づくりに関する情報はちょっと検索するだけで</p><p>たくさん出てきます。</p><p>&nbsp;</p><p>&nbsp;</p><p>しかしながら</p><p>&nbsp;</p><p>&nbsp;</p><p>これだけ情報があって、誰でも簡単に</p><p>その情報を得られる時代なのに</p><p>なぜ？</p><p>家づくりに絶対に必要なことは</p><p>ひとつも出てこないのか？・・・</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/26624853_s.jpg\" alt=\"\" width=\"416\" height=\"278\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671490image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>このような時代、</p><p><strong>家づくりはおろかさらに不安を感じる</strong></p><p><strong>情報ばかり目に飛び込んできます。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p>・先行き不透明な日本経済、家を建ててもいいの？</p><p>・住宅ローンを組んでも大丈夫？どうしたらいい？</p><p>・いいことばかり、不安なことばかり言う営業マン</p><p>・さらに住宅会社によって違うことを言われる</p><p>・何を信じたらいいのかわからない</p><p>・検索して情報を集めようとすればするほど、</p><p>　結局どうしたらいいのかわからない</p><p>・夢のマイホームがまるで不安のマイホーム</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/26881209_m-800x533.jpg\" alt=\"\" width=\"597\" height=\"398\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671598image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>もし上記のような感覚を持っていらっしゃる方</p><p>は、ぜひ一度はこのモデルハウスを体感</p><p>していただきたい。</p><p>&nbsp;</p><p>&nbsp;</p><p>私自身この業界11年近く携わらせていただき、</p><p>誤解、間違い、勘違いをしていたことがあります。</p><p>それは本当の意味で「家づくり」がわかって</p><p>いなかったことでした。</p><p>もちろんこれまでも真剣に一人一人の方の人生を</p><p>考えながら家づくりをしていたつもりでした。</p><p>だからこそ<strong>氣付いてしまった</strong>ことがあります。</p><p>私とお話をしてみませんか？</p><p><strong>家づくりにも本質、極意があるのです。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1880-800x533.jpg\" alt=\"\" width=\"527\" height=\"351\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671598image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>このご縁とご恩に感謝</p><p>&nbsp;</p><p>&nbsp;</p><p>スマイルビルダーズ出展企業様</p><p>建築家木内さん</p><p>山口大工さん</p><p>姶良電設さん</p><p>塩満板金さん</p><p>宮脇内装さん</p><p>加治木基礎さん</p><p>㈱FORUMさん</p><p>プロジェクト彰さん</p><p>トータルハラダさん</p><p>ハイアス・アンド・カンパニーさん</p><p>ワイテックサツマさん</p><p>本田住器さん</p><p>小園硝子さん</p><p>ウルトジャパンさん</p><p>サンワカンパニーさん</p><p>YKKAPさん</p><p>ガッキーさん</p><p>ちかこさん</p><p>羽柴師匠、はじめNURIKAETAIの皆様</p><p>そして弊社</p><p>山口俊彦（代表）</p><p>吉岡（工務担当）</p><p>岩正（設計担当）</p><p>上西　（設計担当）</p><p>堂下　（見積担当）</p><p>佐川（インテリア担当）</p><p>芝（工務・アフター担当）</p><p>松田（経理担当）</p><p>山下（アドバイザー）</p><p>木内（アドバイザー）</p><p>内西（アドバイザー）</p><p>前田（案内所受付担当）</p><p>&nbsp;</p><p>&nbsp;</p><p>そしてこれまで私やアイランドホームで</p><p>家づくりをしてくださったお客様。</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>ありがとうございます。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p>私たちアイランドホームスタッフはお客様の家を、</p><p>「自分の家」と思って</p><p>「大切な友人」だと思って</p><p>「ありがとう」を込めて</p><p>家づくりのパートナーとして</p><p>一生のお付き合いをさせていただきます。</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/IMG_1881-800x533.jpg\" alt=\"\" width=\"476\" height=\"317\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671598image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p>みんなでモデルハウスに想いを込めました。</p><p>&nbsp;</p><p><strong>★家づくりは人生づくりだと伝えたい</strong></p><p>&nbsp;</p><p><strong>★人間も建築も大切なのは空氣を整えること</strong></p><p>&nbsp;</p><p><strong>★今までの固定観念を柔らかくして、より豊かな暮らしがあることに氣付いてほしい</strong></p><p>&nbsp;</p><p>&nbsp;</p><p>そしてただただ<strong>ありがとうございます</strong>という氣持ち。</p><p>&nbsp;</p><p>&nbsp;</p><p>私たちみんなで込めた想いが</p><p><strong>輪（和）のようにひろがれば</strong>うれしいです。</p><p>&nbsp;</p><p>&nbsp;</p><p><img src=\"https://www.iland-rh.com/wp-content/uploads/2022/04/4CD05221-9D02-432C-812F-16DD97D458E7-636x800.jpg\" alt=\"\" width=\"345\" height=\"434\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728477671598image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>ひろがるいえ～自然と共存～　</strong></p><p><strong>私たちのモデルハウスへぜひ</strong></p><p><strong>体感にお越しください。</strong></p><p>&nbsp;</p><p>&nbsp;</p><p><strong>※またモデルハウス内では安全性の高い中洋水</strong></p><p><strong>（中性電解除菌機能水）を噴霧しているため、</strong></p><p><strong>お客様はマスクを外してご見学ができます。</strong></p><p><strong>ぜひマスクをはずして私たちのつくった空氣、</strong></p><p><strong>空間をご体感ください。</strong></p><p>&nbsp;</p><p>​</p>', '<p>​</p><p><strong>&nbsp;来場特典</strong></p><p>中洋水（中性除菌機能電解水）</p><p>のお試しボトルをプレゼント♪</p><p>～効果～</p><p>・空氣をととのえる</p><p>・臭いをとってくれる</p><p>・化粧水替わりになる</p><p>などなど♪とっても便利♪</p><figure class=\"image image_resized\" style=\"width:20.18%;\"><img style=\"aspect-ratio:620/827;\" src=\"/imgs/upload/172847784981589.jpg\" width=\"620\" height=\"827\"></figure><p>​</p><p>合言葉は「<strong>共に手掛ける</strong>」です！</p><p>総合展示場のスタッフにお声掛けください！</p><p><br>&nbsp;</p><p>​</p>', '設定しない', '2024-10-09 21:35:00', '2024-11-02 04:17:32', NULL, 1);
INSERT INTO `events` VALUES (161, 10, '【サンプル】いくら借りれる?! 資金計画相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172837990302570.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりの前から資金計画や住宅ローンのご相談を頂ける「資金計画相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>実績のある住まいのプロが住宅ローンや資金計画の悩みを解消致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物総額でいくらまでなら不安なく払えるのか知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分はいくら借りることが出来るのかローン金額を知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■大きな買い物なので色々相談したいけど、誰に聞けば良いのか分からない方</strong></span></p><p><span style=\"color:#000000;\">家づくりには大きなお金がかかります。だからこそ住宅ローンや資金計画についての不安や悩みは誰もが抱えています。</span></p><p><span style=\"color:#000000;\">住宅ローンの選択やその金利の検討、借入額の検討や毎月の支払額。建ててから後悔しない為に、失敗しない準備が大切です。</span></p><p><span style=\"color:#000000;\">ですが、誰に相談すればよいか分からない、特定の銀行に聞きに行ってもいいものなのか、、、</span></p><p><span style=\"color:#000000;\">そこで頼りになるのが、これまで多くの住宅建築に関わった私たち工務店です。</span></p><p><span style=\"color:#000000;\">私たちは、理想の住まいを実現するために住宅を設計し建築するのが仕事ですが、お客様からいつもお金の悩みも伺います。</span></p><p><span style=\"color:#000000;\">どの銀行にも属さない私たちだからこそ、お話しできることをお伝えし、不安を払拭して頂く為に相談会を開催しています。</span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅のプロがお客様の理想のイメージを元に総額をお答えします</strong></span></p><p><span style=\"color:#000000;\">家づくりの検討初期から銀行にローンの相談に行く方はほとんどいません。自分たちの理想の住まいがいくらくらいかかるか分からないからです。</span></p><p><span style=\"color:#000000;\">まずはお客様の理想の住まいのイメージ（立地や建築プラン、仕様等）を伺い、概算の総額をお答えします。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅ローンあっせんや保険加入が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">私たちは工務店として住宅建築を行う会社ですので、ローンのあっせんや生命保険のかけ替えによる利益はございません。</span></p><p><span style=\"color:#000000;\">お客様の不安が解消され、当社のプランを気に入って頂いた場合に限り、建築請負契約を締結しお仕事をさせて頂ければと思っております（もちろん強引な営業はいたしません）</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;これまで理想の住まいを実現された他の方の事例をご紹介します</strong></span></p><p><span style=\"color:#000000;\">お客様とご年齢や家族構成が近いお客様の事例をご紹介することができますので、その方々の総額や住宅ローンなどについても可能な限り共有させて頂くことが可能です。</span></p><p><span style=\"color:#000000;\">同じような不安を持たれたていた別のお客様の事例をお知りいただくことで、イメージが沸きやすくなると、大変好評です。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#2980b9;\"><strong>資金計画相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:31:00', '2024-10-29 10:18:48', NULL, 1);
INSERT INTO `events` VALUES (162, 10, '【サンプル】家族の理想の間取りプラン相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172838005477173.png,/imgs/events/172838005854374.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりのご相談の一環としてる「間取りプラン相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望のイメージをもとにこれまで手掛けた間取り事例や３Dパースをご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■こんな土地だけどどんな間取りで建てればいいの？と考えている方</strong></span></p><p><span style=\"color:#000000;\"><strong>■地震に強い、性能の良い家ってどんな間取りなの？という方</strong></span></p><p><span style=\"color:#000000;\"><strong>■子育て・家事をスムーズにする間取りを知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■間取り設計の基本を知りたい方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを伺いながら間取り検討を無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社は工務店として多くのお客様の理想の住まいを叶えてきました。</span></p><p><span style=\"color:#000000;\">お客様の理想の暮らしのイメージをお教え頂きながら、事例をご覧頂いたり、手描きの間取りをお見せしたりしながら、イメージを固めるお手伝いをいたします。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;間取りプランニングは無料を行いますのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">プランニングをする段階で当社は費用を頂くことは一切ございません。</span></p><p><span style=\"color:#000000;\">ですが、お客様に理想の家を叶えて頂くため、一生懸命親身にお話しをお伺いさせて頂きますので、是非お気軽に相談会にお越しください。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地だったらどうだろう？」と思う土地がおありでしたら、是非物件資料をお持ちください。プランをご提案させて頂きます。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#16a085;\"><strong>間取りプラン相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-08 18:34:00', '2024-10-29 10:18:48', NULL, 1);
INSERT INTO `events` VALUES (163, 10, '【EYEFULHOME】物価高騰、円安だからこそ建てられる！住宅ローンセミナー（無料）4日間限定！', 'セミナー', '予約制', '[{\"date\":\"2023-01-14\",\"time\":[600,1080]},{\"date\":\"2023-01-15\",\"time\":[600,1080]},{\"date\":\"2023-01-21\",\"time\":[600,1080]},{\"date\":\"2023-01-22\",\"time\":[600,1080]}]', '2023/1/14.15 21.22 2week スマイルビルダーズ用', '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田 ', '2511−1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172847968419791.jpg', 0, NULL, NULL, '<p>​</p><p><strong>&nbsp;&nbsp;- サクッとわかる！- 住宅ローンセミナー</strong></p><hr><p>フラット 35、ネット銀行、地方銀行？<br>たくさんあるけど、どれがお得なの？？<br>そのローンで本当に大丈夫？？？</p><p>保険も見直したほうがいい？？？</p><figure class=\"image image_resized\" style=\"width:15.93%;\"><img style=\"aspect-ratio:620/663;\" src=\"/imgs/upload/172847972533922.png\" width=\"620\" height=\"663\"></figure><p>​</p><p><strong>ファイナンシャルプランナーによる</strong></p><p><strong>「 – サクッとわかる！- 住宅ローンセミナー 」をなんと無料で開催します！</strong></p><p>&nbsp;</p><p><strong>事前予約制となります。</strong></p><p>セミナー後、個別相談も可能。<br>この機会に住宅ローンのことをなんでも聞いて下さい！！</p><hr><p>■開催場所<br>スマイル・ビルダーズ　姶良総合住宅展示場<br>EYEFULHOME(株式会社Life plus home)</p><p>■開催日時（各回3組）<br>・1/14(土)10:00～/14:00～<br>・1/15(日)10:00～/14:00～<br>・1/21(土)10:00～/14:00～<br>・1/22(日)10:00～/14:00～</p><p>■参加費<br>無料<br>飲み物・お菓子付き</p><p>■所要時間<br>1時間～2時間</p><hr><p>​</p>', NULL, '設定しない', '2024-10-09 22:12:00', '2024-11-28 10:24:06', NULL, 1);
INSERT INTO `events` VALUES (164, 10, 'EYEFULHOME姶良【期間限定・300棟限定】Lodina（ロディナ）誕生フェア', '相談会', '予約制', '[{\"date\":\"2023-03-19\",\"time\":[600,1020]},{\"date\":\"2023-03-20\",\"time\":[600,1020]},{\"date\":\"2023-03-21\",\"time\":[600,1020]},{\"date\":\"2023-03-23\",\"time\":[600,1020]},{\"date\":\"2023-03-24\",\"time\":[600,1020]},{\"date\":\"2023-03-25\",\"time\":[600,1020]},{\"date\":\"2023-03-26\",\"time\":[600,1020]},{\"date\":\"2023-03-27\",\"time\":[600,1020]},{\"date\":\"2023-03-30\",\"time\":[600,1020]},{\"date\":\"2023-03-31\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田 ', '2511−1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172847999879823.png,/imgs/events/172848000391024.png,/imgs/events/172848001220925.png,/imgs/events/172848001830026.png,/imgs/events/172848002144727.png,/imgs/events/172848002471128.png', 0, NULL, '20代向け, 30代向け, 夫婦+子供, スマートハウス・省エネ住宅,  平屋住宅,  デザイン住宅, 高気密・高断熱素材使用, 住宅ローン相談可, 子育て, 家事動線, 収納', '<p>​<img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBNnduQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--8c743dc2563b4918decb0374e7a8bc93d652f0b0/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/1080%C3%971080.jpg\" alt=\"\" width=\"620\" height=\"415\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116042image.gif\" width=\"15\" height=\"15\"></span>​</p><p>自分好みに『選ぶ楽しさ』&nbsp;を満喫できるLodina</p><p>お気に入りの間取りを決めて、外壁•設備•仕様などを選ぶだけ。</p><p>少ない打合せで効率よく理想の住まいを実現できます。</p><p>&nbsp;</p><h3><strong>▶︎スムーズな家づくりステップ</strong></h3><p>①建物の大きさと間取りを決める</p><p>↓</p><p>②外観デザインを決める</p><p>↓</p><p>③内観テイストを決める</p><p>↓</p><p>④性能(断熱グレード)を決める</p><p>&nbsp;</p><p>忙しい共働き夫婦の方や無理なく家づくりをしたい方にぴったりの商品です。</p><p>&nbsp;</p><h3><strong>お家づくり提案例</strong></h3><p>Lodinaは、お家づくりを楽しめる安心の定額制です。</p><p>家の大きさが同じなら、間取りを変更しても価格は同じ！</p><p>一定のルールの範囲内であれば間取りを変えても価格は変わりません。</p><p>決められた予算の中で家族の暮らしに合わせた間取りにすることができます。</p><p>※壁の長さや数などには上限があります。</p><p>&nbsp;</p><p><strong>【27坪2階建てプラン例】</strong></p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBNjRuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--858d780d18f880e26667c728d6171b01b9f454f6/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/1F.png\" alt=\"\" width=\"500\" height=\"480\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116041image.gif\" width=\"15\" height=\"15\"></span>​</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBN0VuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--69b468783e4b7e681e7b5a078a71f17c79712edc/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/2F.png\" alt=\"\" width=\"500\" height=\"458\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116042image.gif\" width=\"15\" height=\"15\"></span>​</p><p><strong>◎建物本体価格　1,390万円</strong></p><p>※付帯工事費/その他費用が別途必要になります。</p><p>&nbsp;</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>【24坪平屋プラン例】</strong></p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBN01uQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--f375487dcd66f327640c48589a941c4605d6845b/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/24..png\" alt=\"\" width=\"500\" height=\"652\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116042image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;<strong>◎建物本体価格　1,370万円</strong></p><p>&nbsp;※付帯工事費/その他費用が別途必要になります。</p><p>&nbsp;</p><h3><strong>外観/内観</strong></h3><p><strong>①選べる屋根デザイン</strong></p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBN1VuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--67308c4d5c8613b5ba95287ad18f6b2990fbc629/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/%E7%89%87%E6%B5%81%E3%82%8C.png\" alt=\"\" width=\"239\" height=\"283\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116042image.gif\" width=\"15\" height=\"15\"></span>​</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBN2duQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--8986dc42a9c4e5ce70fcc160dcc675bbcd4aa6e9/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/%E5%AF%84%E6%A3%9F%E3%83%BB%E5%88%87%E5%A6%BB.png\" alt=\"\" width=\"500\" height=\"303\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116042image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>②組み合わせ自由で豊富な外観カラ―&nbsp;</strong></p><p>&nbsp;</p><p><strong><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBNzhuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--7b29e6ec006d6ca8ee16dda7a9e61f3a4f356988/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/%E5%A4%96%E8%A6%B3%E3%83%86%E3%82%99%E3%82%B5%E3%82%99%E3%82%A4%E3%83%B32.png\" alt=\"\" width=\"500\" height=\"195\"></strong><span style=\"background-color:rgba(220,220,220,0.5);\"><strong><img src=\"/imgs/upload/1728480116186image.gif\" width=\"15\" height=\"15\"></strong></span><strong>​</strong></p><p>&nbsp;</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOEluQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--4ba2dfc76d46271717efc3ba95315617f48e220a/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/%E4%B8%80%E8%A6%A7.png\" alt=\"\" width=\"500\" height=\"733\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116268image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>&nbsp;</p><p><strong>③選べる4つのインテリアテイスト</strong></p><p>&nbsp;▶01　メイプルスタイル</p><p>明るく柔らかなストーンです。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOFluQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--057cf8952c7f20509b6d11132856746801363347/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/21_04%E8%AD%9B%E3%83%BB_0401_01.jpg\" alt=\"\" width=\"500\" height=\"333\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116268image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>▶オークスタイル</p><p>明るい木目の色合いのナチュラルテイストです。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOGduQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--a9fc9dce35bfe8029f748923e1327d0615638adc/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/%E3%82%AA%E3%83%BC%E3%82%AF%E3%82%B9%E3%82%BF%E3%82%A4%E3%83%AB.jpg\" alt=\"\" width=\"500\" height=\"750\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116269image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>▶マロンスタイル</p><p>クールで落ち着いたトーンの色合いです。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBODBuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--6ddca6327bc2d6cbc5f108ce75c43f045eec92ca/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/20_9%E8%AD%9B%E3%83%BB_0928_04.jpg\" alt=\"\" width=\"500\" height=\"369\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116272image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>▶ウォルナットスタイル</p><p>温かみのあるトーンの色合いです。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOTBuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--e743c0bb90e071518e918a82e979a5dc35cb933b/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/20_12%E8%AD%9B%E3%83%BB_1203_03.jpg\" alt=\"\" width=\"500\" height=\"752\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116273image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><h3>オールLIXILの使いやすい設備</h3><p>&nbsp;<strong>▶家事ラクを叶えるシステムキッチン</strong></p><p>子どもが触っても火傷の心配がない安心のIHヒーター。</p><p>食器を洗う・拭く手間が省ける食器洗い乾燥機付きキッチンです。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBOThuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--c24b25ad01cc6b566b5e29601a6f0ac06719a18a/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/%EF%BC%92.jpg\" alt=\"\" width=\"500\" height=\"500\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116418image.gif\" width=\"15\" height=\"15\"></span>​</p><p>※画像はイメージです。</p><p>&nbsp;</p><p><strong>▶高性能バスルーム</strong></p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBK0VuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--2896319d939d0d321afee0fccf2d6b4273b9818a/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/%EF%BC%94.jpg\" alt=\"\" width=\"500\" height=\"447\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116491image.gif\" width=\"15\" height=\"15\"></span>​</p><p>※画像はイメージです。</p><p>&nbsp;</p><p><strong>▶使い勝手のよい洗面台</strong></p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBK01uQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--031389795401433917e6f20c4a5051e31c6148a3/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/%EF%BC%93.jpg\" alt=\"\" width=\"500\" height=\"693\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116492image.gif\" width=\"15\" height=\"15\"></span>​</p><p>※画像はイメージです。</p><p>&nbsp;</p><p><strong>▶お手入れ簡単なフチなし形状のトイレ</strong></p><p>頑固な水アカや汚れが落ちやすいアクアセラミックを採用。</p><p>フチを丸ごとなくした便器は、お手入れが簡単です。</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBK1VuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--a633315159ea0ef888e259c8b4b3c40b5c6ec4f1/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/229409702.jpg\" alt=\"\" width=\"500\" height=\"639\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116492image.gif\" width=\"15\" height=\"15\"></span>​</p><p>※画像はイメージです。</p><p>&nbsp;</p><h3>快適な暮らしを実現する断熱仕様</h3><p><strong>▶選べる２つの断熱グレード</strong></p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBK2NuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--f4a9c5ff4d63ba38ae409df9c842918cfec716c5/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/%EF%BC%97.png\" alt=\"\" width=\"500\" height=\"452\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116492image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBK2tuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--5b414c09bed6f944920337326ed67b52cc365416/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/%EF%BC%98.png\" alt=\"\" width=\"500\" height=\"451\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116492image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p><strong>太陽光発電の搭載で家計にも環境にもやさしく</strong></p><p>LIXILの「建て得」でお得に太陽光が設置できます。</p><p>ランニングコストもお得です。</p><p>&nbsp;</p><p><strong>地震に強い安全な家をご提供</strong></p><p>&nbsp;<strong>▶実物大実験により安全性の高さを実証</strong></p><p>アイフルホームは、阪神・淡路大震災クラスの大きな揺れと、その余震を想定した実物大実験を防災科学技術研究所にて行い、地震に対する高い安全性を実<br>証しました。</p><p><strong>▶「耐震等級３」相当の耐震性能を実現</strong></p><p>アイフルホーム加盟店が耐震設計マニュアルと構造設計CADシステムにより、設計するすべてのプランの壁量、壁の配置バランス、接合強度などの耐震性能</p><p>チェックを重ね、より安全性の高いプランをつくります。</p><p>さらに株式会社LIXIL住宅研究所にて「耐震等級3」相当の構造チェックを行い「構造チェック結果報告書」を発行します。</p><p>&nbsp;</p><p><strong>大切な住まいを守る充実の各種保証とアフターメンテナンス</strong></p><p>▶安心の保証が充実しています！</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBKzhuQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--1a44057ae805ea101dc94ee40d8e27136bed9d2b/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/11.png\" alt=\"\" width=\"500\" height=\"256\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/imgs/upload/1728480116634image.gif\" width=\"15\" height=\"15\"></span>​</p><p>&nbsp;</p><p>気になる方はお気軽にお問い合わせ/ご来場ください！</p><p>​</p>', NULL, '設定しない', '2024-10-09 22:16:00', '2024-11-28 10:24:06', NULL, 1);
INSERT INTO `events` VALUES (165, 10, 'EYEFULHOME川内【新生活応援】見学予約から来場で最大1万円GET！', 'キャンペーン', '予約制', '[{\"date\":\"2023-03-10\",\"time\":[600,1020]},{\"date\":\"2023-03-11\",\"time\":[600,1020]},{\"date\":\"2023-03-12\",\"time\":[600,1020]},{\"date\":\"2023-03-13\",\"time\":[600,1020]},{\"date\":\"2023-03-14\",\"time\":[600,1020]},{\"date\":\"2023-03-16\",\"time\":[600,1020]},{\"date\":\"2023-03-17\",\"time\":[600,1020]},{\"date\":\"2023-03-18\",\"time\":[600,1020]},{\"date\":\"2023-03-19\",\"time\":[600,1020]},{\"date\":\"2023-03-20\",\"time\":[600,1020]},{\"date\":\"2023-03-21\",\"time\":[600,1020]},{\"date\":\"2023-03-23\",\"time\":[600,1020]},{\"date\":\"2023-03-24\",\"time\":[600,1020]},{\"date\":\"2023-03-25\",\"time\":[600,1020]},{\"date\":\"2023-03-26\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '薩摩川内市', '平佐町', '3674-2', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172848145700501.jpg,/imgs/events/172848146038002.jpg,/imgs/events/172848146379903.jpg,/imgs/events/172848146764104.jpg,/imgs/events/172848147153905.jpg,/imgs/events/172848147502906.jpg,/imgs/events/172848147833907.jpg,/imgs/events/172848148142208.jpg,/imgs/events/172848148483909.jpg,/imgs/events/172848148827210.jpg', 0, '/imgs/events/172848124524093.jpg', '20代向け, 30代向け, 夫婦+子供, スマートハウス・省エネ住宅, 平屋住宅, 高気密・高断熱素材使用, 住宅ローン相談可, 子育て, 家事動線, 収納, 庭あり, 無垢材使用, モダン, 和モダン', '<p>伸びやかな空間で暮らす。</p><p>小高い敷地に建ち、水平線のラインが美しく見えるよう設計された外観。</p><p>住まう人の視点や生活上の動きひとつひとつにこだわったプラン。<br>充実した収納や玄関からそのままつながる土間、<br>回遊性のある間取にすることで、ストレスのない家事動線。<br>空間の伸びやかさを感じることができる光と風が廻る家。</p><p>広さよりも広がり。視点よりも低いもので揃えられた空間。</p><p>ぜひ一度、実物をご覧いただき家づくりのヒントにされてみませんか？</p><p>&nbsp;</p><p>ちなみに、このモデル<br>丸ごとぜんぶ、そのままお譲りいたします。</p><p><strong>Price&nbsp;3,980万円&nbsp;</strong></p><p>資材価格の高騰・ウッドショック・需要の増加により戸建住宅の価格は<br>2020年後半より約20％近く上昇し、今後も上がり続けると推測されます。</p><p>今回販売することになった川内モデルハウスは、価格上昇前に建てられたもので、<br>今全く同じ建物を建てると<strong>4,500万円</strong>オーバー！<br>建築直後4,180万円でしたが、大幅に値下げし3,980万円に！！</p><p><br>住宅価格の高騰に完成した建物なのでとてもお買い得な物件となります！</p><p>人気の平佐町エリア！<br>好立地！</p>', '<p>​</p><p><strong><u>特典１</u></strong></p><p><strong><u>&nbsp;<img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBMytLQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--572ec8729b81e30ab09bfd62c7fde566e6937d20/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/ribbon1-5.png\" alt=\"\" width=\"24\" height=\"22\"></u></strong><span style=\"background-color:rgba(220,220,220,0.5);\"><strong><u><img src=\"/imgs/upload/1728480485094image.gif\" width=\"15\" height=\"15\"></u></strong></span><strong><u>​</u>&nbsp;見学予約特典最大1万円プレゼントキャンペーン<u><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBMytLQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--572ec8729b81e30ab09bfd62c7fde566e6937d20/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/ribbon1-5.png\" alt=\"\" width=\"24\" height=\"22\">​</u></strong></p><figure class=\"image image_resized\" style=\"width:39.4%;\"><img style=\"aspect-ratio:620/324;\" src=\"/imgs/upload/172848113173692.jpg\" width=\"620\" height=\"324\"></figure><p>来場日：2023年3月6日～3月26日</p><p>ご好評につき期間延長中?</p><p>Amazonギフト券8,000円分をプレゼント！</p><p>　　　　　＋</p><p>見学予約でQUOカードプレゼント</p><p>(平日2,000円、土日祝1,000円)</p><p>【プレゼント条件】</p><p>『来場時のアンケート回答』と『来場者カードへの回答』<br>※メールアドレスの記入必須</p><p>▼注意事項▼</p><p>下記に該当するお客様1組様につき1回の進呈とさせていただきます。</p><ul><li>１）マイホームをご検討中の方。​</li><li>２）はじめて、アイフルホームのイベント、展示場にお越しいただいた方。​</li><li>３）2023年3月6日から3月26日の期間中に、ご来場いただき、アンケートに回答いただいた方。</li><li>４）お渡しするカードの応募フォームから、2023年3月6日から3月26日の期間中に、カード記載のシリアルナンバーをいれてご応募された方。</li><li>※複数店舗へご来場いただいた場合でも、ご来場プレゼントは1回限り。</li><li>※他イベントおよびキャンペーンの来場特典との併用は不可となります。</li><li>※その他、不正行為と弊社がみなした場合、プレゼント提供をお断りする場合がございます。</li><li>※一部店舗では実施せず、プレゼント内容が変更となる場合があります。</li><li>※ご本人確認の為、身分証明書のご提示をお願いする場合があります。</li><li>※プレゼントの進呈数は限りがあり、なくなり次第終了となります。（開催期間中・先着 各店20名様）</li><li>※他人への譲渡、転売行為はおやめください。</li><li>※ご来場時のアンケートに記載されたお名前で、ご応募ください。<br>（店舗の管理表と応募情報を確認させていただいています。）</li><li>※ご見学いただいた店舗の管理表と、ご応募時ご記入のお名前、シリアルナンバーが<br>一致しない場合、プレゼントの提供をお断りする場合がございます。</li><li>※未成年だけのグループのお客様については、本キャンペーンの対象外とし、プレゼント提供をお断りする場合がございます。</li><li>※プレゼントメールに関しましては、いかなる理由でも再送信できません。​<br>メールアドレスの間違いなどないよう、ご注意ください。</li><li>※Amazonギフトカード番号が記載された電子メールは、Amazon Gift Cards Japan合同会社より送信されます。<br>gc-orders@gc.email.amazon.co.jpから受信できるよう設定ください。</li><li>※クオカードの来場プレゼントを実施していない店舗では、8000円のAmazonギフト（メールタイプ）のみのプレゼントになります。</li><li><figure class=\"image\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/172848116464501.jpeg\" width=\"620\" height=\"465\"></figure></li></ul><p>　&nbsp;</p><p><strong><u>特典２</u></strong></p><p><strong><u>&nbsp;<img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBMytLQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--572ec8729b81e30ab09bfd62c7fde566e6937d20/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/ribbon1-5.png\" alt=\"\" width=\"24\" height=\"22\"></u></strong><span style=\"background-color:rgba(220,220,220,0.5);\"><strong><u><img src=\"/imgs/upload/1728480485440image.gif\" width=\"15\" height=\"15\"></u></strong></span><strong><u>​</u>コーディネーターが選んだ家電・家具付<u><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBMytLQlE9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--572ec8729b81e30ab09bfd62c7fde566e6937d20/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/ribbon1-5.png\" alt=\"\" width=\"24\" height=\"22\">​</u></strong></p><p>　・テレビ</p><p>　・エアコン4台</p><p>　・照明</p><p>　・ソファー</p><p>　・ソファーテーブル</p><p>　・ダイニングセット</p><p>　・ダブルベッド(リネン付)</p><p>　・テレビボード</p><p>　・ラグ</p><p>​</p>', '設定しない', '2024-10-09 22:24:00', '2024-11-28 10:24:07', NULL, 1);
