INSERT INTO `events` VALUES (167, 10, 'EYEFULHOME川内【初夏のお出かけに！！】見学予約から来場で1万円GET！', 'キャンペーン', '予約制', '[{\"date\":\"2023-05-14\",\"time\":[600,960]},{\"date\":\"2023-05-15\",\"time\":[600,960]},{\"date\":\"2023-05-18\",\"time\":[600,960]},{\"date\":\"2023-05-19\",\"time\":[600,960]},{\"date\":\"2023-05-20\",\"time\":[600,960]},{\"date\":\"2023-05-21\",\"time\":[600,960]},{\"date\":\"2023-05-22\",\"time\":[600,960]},{\"date\":\"2023-05-23\",\"time\":[600,960]},{\"date\":\"2023-05-25\",\"time\":[600,960]},{\"date\":\"2023-05-26\",\"time\":[600,960]},{\"date\":\"2023-05-27\",\"time\":[600,960]},{\"date\":\"2023-05-28\",\"time\":[600,960]},{\"date\":\"2023-05-29\",\"time\":[600,960]},{\"date\":\"2023-05-30\",\"time\":[600,960]},{\"date\":\"2023-06-02\",\"time\":[600,960]},{\"date\":\"2023-06-03\",\"time\":[600,960]},{\"date\":\"2023-06-04\",\"time\":[600,960]},{\"date\":\"2023-06-05\",\"time\":[600,960]},{\"date\":\"2023-06-06\",\"time\":[600,960]},{\"date\":\"2023-06-08\",\"time\":[600,960]},{\"date\":\"2023-06-09\",\"time\":[600,960]},{\"date\":\"2023-06-10\",\"time\":[600,960]},{\"date\":\"2023-06-11\",\"time\":[600,960]}]', NULL, '非公開', 0, 0, '鹿児島県', '薩摩川内市', '平佐町', '3674-2', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172851793290120.jpg,/imgs/events/172851793650321.jpg,/imgs/events/172851793967022.jpg,/imgs/events/172851794286423.jpg,/imgs/events/172851794619524.jpg,/imgs/events/172851794914025.jpg', 0, '/imgs/events/172851791978719.jpg', '20代向け, 30代向け, 夫婦+子供, スマートハウス・省エネ住宅, 平屋住宅, 高気密・高断熱素材使用, 住宅ローン相談可, 子育て, 家事動線, 収納, 庭あり, 無垢材使用, モダン, 和モダン', '<p>伸びやかな空間で暮らす。</p><p>小高い敷地に建ち、水平線のラインが美しく見えるよう設計された外観。</p><p>住まう人の視点や生活上の動きひとつひとつにこだわったプラン。<br>充実した収納や玄関からそのままつながる土間、<br>回遊性のある間取にすることで、ストレスのない家事動線。<br>空間の伸びやかさを感じることができる光と風が廻る家。</p><p>広さよりも広がり。視点よりも低いもので揃えられた空間。</p><p>ぜひ一度、実物をご覧いただき家づくりのヒントにされてみませんか？</p><p>&nbsp;</p><p>ちなみに、このモデル<br>丸ごとぜんぶ、そのままお譲りいたします。</p><p><strong>Price&nbsp;3,980万円&nbsp;</strong></p><p>資材価格の高騰・ウッドショック・需要の増加により戸建住宅の価格は<br>2020年後半より約20％近く上昇し、今後も上がり続けると推測されます。</p><p>今回販売することになった川内モデルハウスは、価格上昇前に建てられたもので、<br>今全く同じ建物を建てると<strong>4,500万円</strong>オーバー！<br>建築直後4,180万円でしたが、大幅に値下げし3,980万円に！！</p><p><br>住宅価格の高騰に完成した建物なのでとてもお買い得な物件となります！</p><p>人気の平佐町エリア！<br>好立地！</p>', '<p>​</p><p><strong><u>特典１</u></strong></p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBNnUrQnc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--b96fb2e5b7f752fb326c305fb9a379c933a7508f/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/807-2.png\" alt=\"\" width=\"437\" height=\"15\">​</p><p><i><strong>見学予約特典最大1万円プレゼントキャンペーン</strong></i></p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBNnUrQnc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--b96fb2e5b7f752fb326c305fb9a379c933a7508f/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJY0c1bkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--8e680cffc9b97c3de5ceb51b5978f41cc8b7488b/807-2.png\" alt=\"\" width=\"437\" height=\"15\">​</p><p>&nbsp;</p><p>来場日：2023年5月14日～6月11日</p><p>★<strong>ご好評につき期間延長中★</strong></p><p>Amazonギフト券<strong>8,000円分</strong>をプレゼント！</p><p>　　　　　＋</p><p>見学予約でQUOカードプレゼント</p><p>(平日2,000円、土日祝1,000円)</p><p>【プレゼント条件】</p><p>『来場時のアンケート回答』と『来場者カードへの回答』<br>※メールアドレスの記入必須</p><p><img src=\"https://www.ie-miru.jp/rails/active_storage/representations/redirect/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaHBBNisrQnc9PSIsImV4cCI6bnVsbCwicHVyIjoiYmxvYl9pZCJ9fQ==--84e105ada6446bb2ece30e4f334437b143847b27/eyJfcmFpbHMiOnsibWVzc2FnZSI6IkJBaDdCem9MWm05eWJXRjBTU0lJYW5CbkJqb0dSVlE2QzNKbGMybDZaVWtpQ0RZeU1BWTdCbFE9IiwiZXhwIjpudWxsLCJwdXIiOiJ2YXJpYXRpb24ifX0=--3aa7fa4a6fc7ec12436cd1adb029feb19fad8dcb/SNS_1200x628.jpg\" alt=\"\" width=\"620\" height=\"324\"><span style=\"background-color:rgba(220,220,220,0.5);\"><img src=\"/im