600,1020]},{\"date\":\"2024-11-19\",\"time\":[600,1020]},{\"date\":\"2024-11-21\",\"time\":[600,1020]},{\"date\":\"2024-11-22\",\"time\":[600,1020]},{\"date\":\"2024-11-23\",\"time\":[600,1020]},{\"date\":\"2024-11-24\",\"time\":[600,1020]},{\"date\":\"2024-11-25\",\"time\":[600,1020]},{\"date\":\"2024-11-26\",\"time\":[600,1020]},{\"date\":\"2024-11-28\",\"time\":[600,1020]},{\"date\":\"2024-11-29\",\"time\":[600,1020]},{\"date\":\"2024-11-30\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田2511-1', '姶良総合住宅展示場スマイルビルダーズ内', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172856814429801.png,/imgs/events/172856814918362.jpg,/imgs/events/172856815411263.jpg,/imgs/events/172856815798564.jpg,/imgs/events/172856816090565.jpg,/imgs/events/172856816404566.jpg,/imgs/events/172856816707367.jpg,/imgs/events/172856816992368.jpg', 0, NULL, '20代向け, 30代向け, 夫婦+子供, 平屋住宅, デザイン住宅, 姶良市, 土地探し, 点検, 自社大工', '<p><strong>四季を感じ自然に触れ、やすらぎと楽しさの暮らしに身を置く。</strong><br><strong>自然の恵みを活用する設計手法(パッシブデザイン)で、省エネ、光熱費削減、快適で健康な暮らしをご提案します。</strong></p><p>&nbsp;</p><p><span style=\"color:#e74c3c;\"><strong>平屋モデルハウス、随時ご見学受付中。</strong></span></p><p><span style=\"color:#e74c3c;\"><strong>事前予約をされる場合は、予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-10-10 22:44:00', '2024-11-28 10:24:34', NULL, 1);
INSERT INTO `events` VALUES (197, 7, '【サンプル】いくら借りれる?! 資金計画相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172655998718801.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりの前から資金計画や住宅ローンのご相談を頂ける「資金計画相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>実績のある住まいのプロが住宅ローンや資金計画の悩みを解消致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物総額でいくらまでなら不安なく払えるのか知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■自分はいくら借りることが出来るのかローン金額を知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■大きな買い物なので色々相談したいけど、誰に聞けば良いのか分からない方</strong></span></p><p><span style=\"color:#000000;\">家づくりには大きなお金がかかります。だからこそ住宅ローンや資金計画についての不安や悩みは誰もが抱えています。</span></p><p><span style=\"color:#000000;\">住宅ローンの選択やその金利の検討、借入額の検討や毎月の支払額。建ててから後悔しない為に、失敗しない準備が大切です。</span></p><p><span style=\"color:#000000;\">ですが、誰に相談すればよいか分からない、特定の銀行に聞きに行ってもいいものなのか、、、</span></p><p><span style=\"color:#000000;\">そこで頼りになるのが、これまで多くの住宅建築に関わった私たち工務店です。</span></p><p><span style=\"color:#000000;\">私たちは、理想の住まいを実現するために住宅を設計し建築するのが仕事ですが、お客様からいつもお金の悩みも伺います。</span></p><p><span style=\"color:#000000;\">どの銀行にも属さない私たちだからこそ、お話しできることをお伝えし、不安を払拭して頂く為に相談会を開催しています。</span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅のプロがお客様の理想のイメージを元に総額をお答えします</strong></span></p><p><span style=\"color:#000000;\">家づくりの検討初期から銀行にローンの相談に行く方はほとんどいません。自分たちの理想の住まいがいくらくらいかかるか分からないからです。</span></p><p><span style=\"color:#000000;\">まずはお客様の理想の住まいのイメージ（立地や建築プラン、仕様等）を伺い、概算の総額をお答えします。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅ローンあっせんや保険加入が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">私たちは工務店として住宅建築を行う会社ですので、ローンのあっせんや生命保険のかけ替えによる利益はございません。</span></p><p><span style=\"color:#000000;\">お客様の不安が解消され、当社のプランを気に入って頂いた場合に限り、建築請負契約を締結しお仕事をさせて頂ければと思っております（もちろん強引な営業はいたしません）</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;これまで理想の住まいを実現された他の方の事例をご紹介します</strong></span></p><p><span style=\"color:#000000;\">お客様とご年齢や家族構成が近いお客様の事例をご紹介することができますので、その方々の総額や住宅ローンなどについても可能な限り共有させて頂くことが可能です。</span></p><p><span style=\"color:#000000;\">同じような不安を持たれたていた別のお客様の事例をお知りいただくことで、イメージが沸きやすくなると、大変好評です。</span></p><p><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#2980b9;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#2980b9;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#2980b9;\"><strong>資金計画相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-09-17 16:59:29', '2024-10-29 10:18:50', NULL, 1);
INSERT INTO `events` VALUES (198, 7, '【サンプル】一緒に探します！理想の土地探し相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172658414209702.png,/imgs/events/172658415600703.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、土地探しから家づくりのご相談を頂ける「土地探し相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望の住まいに適した土地をご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■土地と建物を一緒にご相談されたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■建売分譲等とは異なり、自分たちだけの理想の家を考えている方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:rgb(231,76,60);color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:rgb(231,76,60);color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを共有しながら土地探しを無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社へご相談へお越しの7割以上が、土地探しからご相談頂くお客様です。</span></p><p><span style=\"color:#000000;\">エリア内の土地をご紹介できる不動会社と連携し、お客様に最適な土地をご提案してきた実績がございますので、是非まずはご予約の上ご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;不動産販売が目的ではありませんのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">土地探しからのご相談の場合でも、理想の住まいを建築させて頂くことを生業としているのが私たち工務店です。</span></p><p><span style=\"color:#000000;\">設計の視点も取り入れ、土地に理想の建築プランがしっかり納まるように、サポートさせて頂くことが可能です。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地は良くないかな？」と思う前に、まず私たちにご相談ください。</span></p><p><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#e74c3c;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#e74c3c;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。土地情報だけでなく、学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#e74c3c;\"><strong>土地探し相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-09-17 23:40:11', '2024-10-29 10:18:50', NULL, 1);
INSERT INTO `events` VALUES (199, 7, '【サンプル】家族の理想の間取りプラン相談会（無料）', '相談会', '予約制', NULL, NULL, '非公開', 0, 0, NULL, NULL, NULL, NULL, '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172658441803304.png,/imgs/events/172658442343105.png', 0, NULL, NULL, '<p><span style=\"color:#000000;\"><strong>当社では、家づくりのご相談の一環としてる「間取りプラン相談会」を開催しております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご相談は無料でお受けしております。</strong></span></p><p><span style=\"color:#000000;\"><strong>ご要望のイメージをもとにこれまで手掛けた間取り事例や３Dパースをご提案致しますので、是非ご予約ください。</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>こんな方は是非お越しください</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>■住宅購入（家づくり）を検討され始めた方</strong></span></p><p><span style=\"color:#000000;\"><strong>■こんな土地だけどどんな間取りで建てればいいの？と考えている方</strong></span></p><p><span style=\"color:#000000;\"><strong>■地震に強い、性能の良い家ってどんな間取りなの？という方</strong></span></p><p><span style=\"color:#000000;\"><strong>■子育て・家事をスムーズにする間取りを知りたい方</strong></span></p><p><span style=\"color:#000000;\"><strong>■間取り設計の基本を知りたい方</strong></span></p><hr><p><span style=\"color:#000000;\"><strong>当社にご相談頂くメリット</strong></span></p><hr><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>１</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;住宅建築のプロが建築のイメージを伺いながら間取り検討を無料でサポート</strong></span></p><p><span style=\"color:#000000;\">当社は工務店として多くのお客様の理想の住まいを叶えてきました。</span></p><p><span style=\"color:#000000;\">お客様の理想の暮らしのイメージをお教え頂きながら、事例をご覧頂いたり、手描きの間取りをお見せしたりしながら、イメージを固めるお手伝いをいたします。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>２</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;間取りプランニングは無料を行いますのでご安心ください</strong></span></p><p><span style=\"color:#000000;\">プランニングをする段階で当社は費用を頂くことは一切ございません。</span></p><p><span style=\"color:#000000;\">ですが、お客様に理想の家を叶えて頂くため、一生懸命親身にお話しをお伺いさせて頂きますので、是非お気軽に相談会にお越しください。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>３</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;自由設計なので狭小地や変形地も対応可能です</strong></span></p><p><span style=\"color:#000000;\">一般的に正方形に近く、南道路の土地が良いと言われることが多くありますが、私たちは設計からご提案する工務店として、どんな土地でもお客様の理想の暮らしが叶うようにプランニングさせて頂きます。「この土地だったらどうだろう？」と思う土地がおありでしたら、是非物件資料をお持ちください。プランをご提案させて頂きます。</span></p><p><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"background-color:#16a085;color:#ffffff;\"><strong>４</strong></span><span style=\"background-color:#16a085;color:#000000;\"><strong>&nbsp;</strong></span><span style=\"color:#000000;\"><strong>&nbsp;地域密着でエリア内の情報を多く持っています</strong></span></p><p><span style=\"color:#000000;\">大手ハウスメーカーと異なり、私たちは地域密着でエリア内の情報を多く持っています。学校、医療、お買い物など様々な観点でアドバイスをさせて頂くことが出来ますので、これからの住まいや暮らし全体を一生涯サポートさせて頂きます。</span></p><p><span style=\"color:#16a085;\"><strong>間取りプラン相談会は随時受付中。ご予約カレンダーよりご都合の良い日時をお選びください。</strong></span></p>', NULL, '設定しない', '2024-09-17 23:45:56', '2024-10-29 10:18:50', NULL, 1);
INSERT INTO `events` VALUES (200, 7, '鹿児島市伊敷方面！完全2世帯‼　完成見学会開催!!!', '完成見学会', '予約制', '[{\"date\":\"2022-05-14\",\"time\":[600,1020]},{\"date\":\"2022-05-15\",\"time\":[600,1020]},{\"date\":\"2022-05-21\",\"time\":[600,1020]},{\"date\":\"2022-05-22\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '鹿児島市', '伊敷台', '4丁目1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172857020942069.jpg', 0, NULL, '20代向け, 30代向け, 40代向け, 50代以上向け, 夫婦+子供, 二世帯, 戸建て・一軒家, 木造住宅, 二世帯住宅, 分離型二世帯住宅, デザイン住宅, 高気密・高断熱素材使用, 住宅ローン相談可, 子育て, 家事動線', NULL, NULL, '設定しない', '2024-10-10 23:21:00', '2024-11-28 10:24:35', NULL, 1);
INSERT INTO `events` VALUES (201, 7, '【都城市神之山町】建売販売会', '建売販売会', '予約承認制', NULL, NULL, '非公開', 0, 0, '宮崎県', '都城市', '神之山', '2275-6', '地図にピンを表示する', '住所を全て記載する', NULL, 0, '/imgs/events/172857050860770.jpg', '20代向け, 30代向け, 40代向け, 夫婦+子供, 夫婦のみ, 3K/DK/LDK, 4K/DK/LDK, 戸建て・一軒家, 木造住宅, スマートハウス・省エネ住宅, 平屋住宅, デザイン住宅, ツーバイフォー工法, 高気密・高断熱素材使用, 仲介手数料相談可, モダン, 50代以上向け', '<p>①日当たり抜群な好立地！</p><p>②近くにコンビニ。ドラッグストアのある</p><p>　生活しやすい環境！</p><p>③車で5分圏内に国道１０号線があり、</p><p>　大型飲食店が多い為、生活しやすい環境！</p><p>④車で５分圏内に都城ICがある為、</p><p>　交通アクセス抜群！</p>', '<p>加治木総合展示場オープン記念！</p><p>ご来場特典で先着：10組様限定！</p><p>マックカード：1,000円分プレゼント‼</p>', '設定しない', '2024-10-10 23:25:00', '2024-10-29 10:18:50', NULL, 1);
INSERT INTO `events` VALUES (202, 7, '【都城市祝吉町】建売販売会', '建売販売会', '予約承認制', NULL, NULL, '非公開', 0, 0, '宮崎県', '都城市', '祝吉町', '3/12/2023', '地図にピンを表示する', '住所を全て記載する', NULL, 0, '/imgs/events/172857069838471.jpg', '20代向け, 30代向け, 40代向け, 夫婦+子供, 夫婦のみ, 3K/DK/LDK, 4K/DK/LDK, 戸建て・一軒家, 木造住宅, デザイン住宅, ツーバイフォー工法, 高気密・高断熱素材使用, 仲介手数料相談可, モダン', '<p>①徒歩５分圏内に祝吉小学校と祝吉中学校が</p><p>　ある為、子育て世代の方に安心な環境！</p><p>②車で５分圏内に都城イオンモールが</p><p>　ある為、生活しやすい環境！</p><p>③閑静な住宅街で快適に暮らせる環境！</p>', '<p>加治木総合展示場オープン記念！</p><p>ご来場特典で先着：10組様限定！</p><p>マックカード：1,000円分プレゼント‼</p>', '設定しない', '2024-10-10 23:29:00', '2024-10-29 10:18:50', NULL, 1);
INSERT INTO `events` VALUES (203, 7, '加治木平屋モデル、グランドオープン記念～霧島市新町分譲販売会！～', '建売販売会', '予約承認制', NULL, NULL, '非公開', 0, 0, '鹿児島県', '霧島市', '国分新町', '936', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172857080843102.png,/imgs/events/172857081167503.png', 0, '/imgs/events/172857082463104.png', '20代向け, 30代向け, 40代向け, 50代以上向け, 夫婦+子供, 二世帯, 夫婦のみ, 戸建て・一軒家, 木造住宅, 平屋住宅, 二世帯住宅, デザイン住宅, 高気密・高断熱素材使用, 仲介手数料相談可, モダン, 家事動線, 収納', NULL, '<p>加治木総合展示場オープン記念！</p><p>100万ポイントキャンペーン実施中！！</p><p>100万ポイントを使い、ご自由にお選び下さい。</p>', '設定しない', '2024-10-10 23:32:00', '2024-10-29 10:18:50', NULL, 1);
