INSERT INTO `events` VALUES (236, 7, '新春お年玉フェア～スマイルビルダーズ加治木展示場～', '展示場', '予約制', '[{\"date\":\"2024-01-05\",\"time\":[600,1020]},{\"date\":\"2024-01-06\",\"time\":[600,1020]},{\"date\":\"2024-01-07\",\"time\":[600,1020]},{\"date\":\"2024-01-08\",\"time\":[600,1020]},{\"date\":\"2024-01-11\",\"time\":[600,1020]},{\"date\":\"2024-01-12\",\"time\":[600,1020]},{\"date\":\"2024-01-13\",\"time\":[600,1020]},{\"date\":\"2024-01-14\",\"time\":[600,1020]},{\"date\":\"2024-01-15\",\"time\":[600,1020]},{\"date\":\"2024-01-18\",\"time\":[600,1020]},{\"date\":\"2024-01-19\",\"time\":[600,1020]},{\"date\":\"2024-01-20\",\"time\":[600,1020]},{\"date\":\"2024-01-21\",\"time\":[600,1020]},{\"date\":\"2024-01-22\",\"time\":[600,1020]},{\"date\":\"2024-01-25\",\"time\":[600,1020]},{\"date\":\"2024-01-26\",\"time\":[600,1020]},{\"date\":\"2024-01-27\",\"time\":[600,1020]},{\"date\":\"2024-01-28\",\"time\":[600,1020]},{\"date\":\"2024-01-29\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田', '2515-1', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172866014378680.jpg,/imgs/events/172866014844881.jpg,/imgs/events/172866015202282.jpg,/imgs/events/172866015568383.jpg,/imgs/events/172866015904984.jpg,/imgs/events/172866016320185.jpg,/imgs/events/172866016708886.jpg,/imgs/events/172866017030787.jpg', 0, NULL, 'シアタールームあり, 戸建て・一軒家, 木造住宅, 平屋住宅, デザイン住宅, 高気密・高断熱素材使用, モダン, シンプル, 家事動線, 収納, 住宅ローン相談可, ガレージあり, 洋風スタイル, 在来工法, 間取り, 外観, 水廻り', '<p>新しい年の幕開けに、スマイルビルダーズ加治木展示場で新春お年玉フェアを開催します！<br>この機会に、お得な情報をゲットしましょう。</p><p>新春お年玉フェアでは、様々な特典をご用意しています。家づくりに必要な情報が満載のフェアをお楽しみください。また、今回は加治木展示場限定の特別プランもご紹介します。この機会に、あなたの理想の家づくりを実現させましょう。</p><p>フェア期間中は、住宅ローンの相談も受け付けています。専門のアドバイザーがお客様に合ったプランをご提案いたします。お気軽にご相談ください。</p><p>さらに、フェア期間中にご成約いただいたお客様には、スペシャルプレゼントをご用意しています。</p><p>この機会に、スマイルビルダーズ加治木展示場にお越しください。皆様のご来場をお待ちしております。</p>', NULL, '設定しない', '2024-10-12 00:18:00', '2024-11-28 10:25:05', NULL, 1);
INSERT INTO `events` VALUES (237, 7, '平屋モデルハウス限定公開！姶良市で2ヶ月間の見学会！', '完成見学会', '予約承認制', '[{\"date\":\"2024-01-08\",\"time\":[600,1020]},{\"date\":\"2024-01-11\",\"time\":[600,1020]},{\"date\":\"2024-01-12\",\"time\":[600,1020]},{\"date\":\"2024-01-13\",\"time\":[600,1020]},{\"date\":\"2024-01-14\",\"time\":[600,1020]},{\"date\":\"2024-01-15\",\"time\":[600,1020]},{\"date\":\"2024-01-18\",\"time\":[600,1020]},{\"date\":\"2024-01-19\",\"time\":[600,1020]},{\"date\":\"2024-01-20\",\"time\":[600,1020]},{\"date\":\"2024-01-21\",\"time\":[600,1020]},{\"date\":\"2024-01-22\",\"time\":[600,1020]},{\"date\":\"2024-01-25\",\"time\":[600,1020]},{\"date\":\"2024-01-26\",\"time\":[600,1020]},{\"date\":\"2024-01-27\",\"time\":[600,1020]},{\"date\":\"2024-01-28\",\"time\":[600,1020]},{\"date\":\"2024-01-29\",\"time\":[600,1020]},{\"date\":\"2024-02-01\",\"time\":[600,1020]},{\"date\":\"2024-02-02\",\"time\":[600,1020]},{\"date\":\"2024-02-03\",\"time\":[600,1020]},{\"date\":\"2024-02-04\",\"time\":[600,1020]},{\"date\":\"2024-02-05\",\"time\":[600,1020]},{\"date\":\"2024-02-08\",\"time\":[600,1020]},{\"date\":\"2024-02-09\",\"time\":[600,1020]},{\"date\":\"2024-02-10\",\"time\":[600,1020]},{\"date\":\"2024-02-11\",\"time\":[600,1020]},{\"date\":\"2024-02-12\",\"time\":[600,1020]},{\"date\":\"2024-02-15\",\"time\":[600,1020]},{\"date\":\"2024-02-16\",\"time\":[600,1020]},{\"date\":\"2024-02-17\",\"time\":[600,1020]},{\"date\":\"2024-02-18\",\"time\":[600,1020]},{\"date\":\"2024-02-19\",\"time\":[600,1020]},{\"date\":\"2024-02-22\",\"time\":[600,1020]},{\"date\":\"2024-02-23\",\"time\":[600,1020]},{\"date\":\"2024-02-24\",\"time\":[600,1020]},{\"date\":\"2024-02-25\",\"time\":[600,1020]},{\"date\":\"2024-02-26\",\"time\":[600,1020]},{\"date\":\"2024-02-29\",\"time\":[600,1020]}]', NULL, '公開', 1, 0, '鹿児島県', '姶良市', '下名', '1106', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/172866053113888.jpg,/imgs/events/172866053439989.jpg', 0, NULL, '戸建て・一軒家, 木造住宅, 平屋住宅, デザイン住宅, 高気密・高断熱素材使用, モダン, シンプル, 家事動線, 住宅ローン相談可, 子育て', '<p>【タイトル】<br>平屋モデルハウス限定公開！姶良市で2ヶ月間の見学会！</p><p>【本文】<br>姶良市で、平屋モデルハウスの限定公開が決定しました！<br>この機会に、ぜひ一度足を運んでみてください。</p><p>平屋ならではの広々とした空間、開放感、そして暮らしやすさを実感できます。<br>家族のコミュニケーションを大切にした間取り、使いやすい収納スペース、そして高い耐震性能など、機能性にも優れています。</p><p>当社の平屋モデルハウスは、デザインや設備、仕様にもこだわりを持っています。<br>家づくりに悩んでいる方、家族のライフスタイルに合わせた住まいを探している方には、必見のイベントです。</p><p>会場では、専門スタッフがお客様のご要望やご質問にお答えします。<br>また、ご来場いただいた方には、特別なプレゼントもご用意しています。</p><p>この機会に、ぜひ当社の平屋モデルハウスをご覧いただき、快適な暮らしを実現してください。<br>2ヶ月間の期間限定公開ですので、お早めにご予約ください。お待ちしております</p>', NULL, '設定しない', '2024-10-12 00:25:00', '2024-11-28 10:25:06', NULL, 1);
