INSERT INTO `events` VALUES (245, 4, '＜完成見学会＞薩摩川内市天辰町', '完成見学会', '予約制', '[{\"date\":\"2024-10-26\",\"time\":[600,1020]},{\"date\":\"2024-10-27\",\"time\":[600,1020]}]', '', '公開', 1, 0, '鹿児島県', '薩摩川内市', '天辰町', '', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/173047461747801.jpg,/imgs/events/173047462163502.jpg,/imgs/events/173047462496003.jpg', 0, '', '健康住宅, 音響熟成木材, 幻の漆喰, 健康素材, 自然素材, 木造住宅, 完成見学会, オープンハウス, きれいな空気, 平屋', '<p>&nbsp;</p><p><span style=\"background-color:transparent;\"><strong>【薩摩川内市天辰町】完成見学会</strong></span></p><p>&nbsp;</p><p><span style=\"background-color:transparent;\">10/26(土)、27(日)の二日間、薩摩川内市天辰町にて完成見学会を開催します。</span><br><span style=\"background-color:transparent;\">会場は、薩摩川内モデルハウスのお隣。</span></p><p><span style=\"background-color:transparent;\">何年、何十年経っても、夫婦がゆったりとくつろぎ心置きなく趣味をたのしめるお家です。</span></p><p><span style=\"background-color:transparent;\">「家の中の空気が圧倒的に綺麗」「生きた木材や自然素材が呼吸している家」</span><br><span style=\"background-color:transparent;\">旭住宅のコンセプトである「健康住宅」を体感できる二日間。</span></p><p><span style=\"background-color:transparent;\">隣接する薩摩川内モデルハウスも見学が可能です。</span><br><span style=\"background-color:transparent;\">大壁造りのオーナーハウス、真壁造りのモデルハウス、2棟の違いをお楽しみください。</span></p><p><span style=\"background-color:transparent;\">土地探しから完成まで2年を費やし、</span><br><span style=\"background-color:transparent;\">旭住宅とお客様で、心地よい空間と暮らしをとことん追求して完成した住まい。</span></p><p><span style=\"background-color:transparent;\">みなさんの住まいづくりの参考になると思いますので、是非ご来場下さい。</span></p><p>&nbsp;</p><p><span style=\"background-color:transparent;\">みどころ</span></p><p><span style=\"background-color:transparent;\">■オーブン機能も備えた、お料理が楽しくなる広々Ⅱ型キッチン。</span><br><span style=\"background-color:transparent;\">■大壁ですっきりとした健康住宅。</span><br><span style=\"background-color:transparent;\">■木の香りに包まれ、心地よくゆったりと生活できるLDK。</span></p><p><span style=\"background-color:transparent;\">健康住宅の芳醇な木の香り、すっきりした空気、気持ちの良い肌触りをぜひご体感ください。</span><br><span style=\"background-color:transparent;\">皆様のご来場を心よりお待ちしております。</span></p><figure class=\"image\"><img style=\"aspect-ratio:620/413;\" src=\"/imgs/upload/173047649683004.png\" width=\"620\" height=\"413\"></figure><p><span style=\"background-color:transparent;\">※写真は薩摩川内モデルの一部です。</span></p><p>&nbsp;</p><p>健康住宅の芳醇な木の香り、すっきりした空気、気持ちの良い肌触りをぜひご体感ください。<br>皆様のご来場を心よりお待ちしております。</p>', '', '設定しない', '2024-11-02 00:33:54', '2024-11-02 00:55:44', '0000-00-00 00:00:00', 1);
INSERT INTO `events` VALUES (246, 4, '【イシンスタイル】ハロウィン家づくり相談会', 'イベント', '予約制', '[{\"date\":\"2024-11-02\",\"time\":[600,1020]},{\"date\":\"2024-11-03\",\"time\":[600,1020]},{\"date\":\"2024-11-04\",\"time\":[600,1020]}]', '', '公開', 1, 0, '鹿児島県', '姶良市', '松原町２丁目28-18', '', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/173047678838005.jpg,/imgs/events/173047679448907.jpg,/imgs/events/173047679775908.png', 0, NULL, '平屋, 駐車場有り, 家事動線, 長期優良住宅, 耐震等級3, 高気密, 高断熱, デザイン住宅, 省エネ住宅, 住宅ローン相談可', '<p>​</p><h3 style=\"text-align:center;\"><span style=\"color:#9b59b6;\"><strong>&nbsp;＼　ハロウィン家づくり相談会　／</strong></span></h3><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">イシンスタイルでは、<br>家づくりに関する疑問やお悩みを抱えている方のために<br><span style=\"color:#f39c12;\">「家づくり相談会」</span>を開催いたします。</p><p style=\"text-align:center;\">はじめての家づくり。</p><p style=\"text-align:center;\">何から始めたら良いの？<br>土地の探し方は？<br>価格はどれくらい？<br>わからないことだらけで、不安はつきもの。</p><p style=\"text-align:center;\">何も決まっていなくても大丈夫です。<br>気兼ねなくご相談ください。</p><p style=\"text-align:center;\">これまでの経験を元に、<br>専門のスタッフがお客様に合わせた<br>理想の家づくりをご提案いたします。</p><p style=\"text-align:center;\">この機会をぜひご活用ください。</p><p style=\"text-align:center;\">&nbsp;</p><h4 style=\"text-align:center;\"><span style=\"color:#f39c12;\"><strong>相談会のポイント</strong></span></h4><p style=\"text-align:center;\">・モデルハウスを見学しながら相談できる</p><p style=\"text-align:center;\">・過去の施工事例を紹介しながらアドバイス</p><p style=\"text-align:center;\">・予算やローンのシミュレーションもOK</p><p style=\"text-align:center;\">&nbsp;</p><figure class=\"image\"><img style=\"aspect-ratio:620/451;\" src=\"/imgs/upload/173047692801209.png\" width=\"620\" height=\"451\"></figure><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">狭さを全く感じない、ちょうどいい30坪の平屋。<br>開放感たっぷりの広々LDKにより、暮らしやすく、ゆとりのある空間が出来ました。<br>性能にもこだわり、スタイリッシュなデザインが特徴のモデルハウスです。</p><p style=\"text-align:center;\">&nbsp;</p><p style=\"text-align:center;\">皆様のご来場お待ちしております。</p><p>​</p>', '<figure class=\"image\"><img style=\"aspect-ratio:620/867;\" src=\"/imgs/upload/173047698657210.jpg\" width=\"620\" height=\"867\"></figure>', '設定しない', '2024-11-02 00:57:37', '2024-11-02 03:55:33', NULL, 1);
INSERT INTO `events` VALUES (247, 4, '【姶良市加治木町木田】完成見学会', '完成見学会', '予約制', '[{\"date\":\"2024-11-02\",\"time\":[600,1020]},{\"date\":\"2024-11-03\",\"time\":[600,1020]},{\"date\":\"2024-11-04\",\"time\":[600,1020]},{\"date\":\"2024-11-09\",\"time\":[600,1020]},{\"date\":\"2024-11-10\",\"time\":[600,1020]}]', '', '公開', 1, 0, '鹿児島県', '姶良市', '加治木町木田', '', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/173047911559211.jpg,/imgs/events/173047912108712.png', 0, NULL, '平屋, 駐車場有り, 家事動線, 長期優良住宅, 耐震等級3, 高気密, 高断熱, デザイン住宅, 省エネ住宅, 住宅ローン相談可', '<h4><span style=\"background-color:transparent;color:hsl(0, 0%, 0%);\"><strong>【姶良市加治木町木田】癒しの平屋。＜完成見学会＞</strong></span></h4><p>&nbsp;</p><p><span style=\"background-color:transparent;\">11月2日(土)、3日(日)、4日(月祝)、9日(土)、10日(日)の5日間、</span><br><span style=\"background-color:transparent;\">姶良市加治木町木田にて完成見学会を開催します。</span></p><p>&nbsp;</p><p><span style=\"background-color:transparent;\">今回の住まいは、</span><br><span style=\"background-color:transparent;\">自然素材のあたたかみが心地よく、暮らしの変化に永く寄り添える平屋。</span></p><p><span style=\"background-color:transparent;\">広々とした開放感のあるリビングで、ゆっくり、のんびり、ぼーっとくつろげる。</span><br><span style=\"background-color:transparent;\">心と身体が癒される「健康住宅」を心ゆくまでご堪能ください。</span></p><p><span style=\"background-color:transparent;\">旭住宅とお客様で、心地よい空間と暮らしをとことん追求した住まい。</span><br><span style=\"background-color:transparent;\">みなさんの住まいづくりの参考になると思いますので、是非ご来場下さい。</span></p><p>&nbsp;</p><p><span style=\"background-color:transparent;\"><strong>みどころ</strong></span></p><p><span style=\"background-color:transparent;\">■家族の気配をいつでも近くに感じられる、開放感のある平屋。</span><br><span style=\"background-color:transparent;\">■広々としたリビング、和室、ロフトなど、随所に「くつろげる空間」。</span><br><span style=\"background-color:transparent;\">■ライフスタイルの変化にも柔軟に対応できる大容量のファミリークローゼット。</span></p><figure class=\"image\"><img style=\"aspect-ratio:620/414;\" src=\"/imgs/upload/173047923498712.jpg\" width=\"620\" height=\"414\"></figure><p><span style=\"background-color:transparent;\">一人一人のライフスタイルが違うように、家づくりや暮らしのあり方の望むものは千差万別です。</span><br><span style=\"background-color:transparent;\">私たちはお客様としっかり向き合い、「憧れ」や「想い」をカタチにしていきます。</span><br><span style=\"background-color:transparent;\">この鹿児島の風土に馴染む心地よい空間と暮らしを、お客様と一緒に創造しています。</span></p><p>&nbsp;</p><p><span style=\"background-color:transparent;\">健康住宅の芳醇な木の香り、すっきりした空気、気持ちの良い肌触りをぜひご体感ください。</span><br><span style=\"background-color:transparent;\">皆様のご来場を心よりお待ちしております。</span></p>', NULL, '設定しない', '2024-11-02 01:36:41', '2024-11-02 01:41:16', NULL, 1);
INSERT INTO `events` VALUES (248, 10, '【応募終了しました】ちびっこ建築家', 'ワークショップ', 'オープン制', '[{\"date\":\"2024-10-26\",\"time\":[600,960]},{\"date\":\"2024-10-27\",\"time\":[600,960]}]', '', '公開', 1, 0, '鹿児島県', '霧島市', '加治木町木田2511-1姶良総合展示場スマイル・ビルダーズ内', '', '地図にピンを表示する', '住所を全て記載する', '/imgs/events/173047994511418.jpg,/imgs/events/173047994949419.jpg,/imgs/events/173047995272220.jpg,/imgs/events/173047995597021.jpg', 0, NULL, 'ものづくり, ミニハウス, ダンボールハウス, ワークショップ, ちびっこ建築家', '<p>​</p><p style=\"text-align:center;\"><span style=\"background-color:#ecf0f1;\"><strong>子どもたちの理想をカタチに。</strong></span></p><p>&nbsp;</p><p>今回、スマイルビルダーズ姶良総合展示場・総合案内所内にて、『ダンボールハウスワークショップ』を開催します！</p><p>&nbsp;</p><p>みんなの生活スタイルや理想を形にしていく\"家づくり\"体験。</p><p>&nbsp;</p><p>スタッフのサポートのもと、子供たちのアイディアを生かして、ダンボール製のミニチュアハウスを一緒に完成させましょう！?</p><p>ものづくりの楽しさと家づくりの面白さをみんなで共有しませんか？✨</p><p>&nbsp;</p><p>このイベントはLINE公式からの参加応募制です。<br>※ご友人とのお申し込みの場合は、それぞれお申込みいただきLINE公式にてその旨をお知らせくださいませ。<br>　</p><p>&nbsp;</p><p><img src=\"https://lifeplushome.jp/wpr/wp-content/uploads/2024/09/IMG_3182-1024x768.jpg\" alt=\"\">​</p><p>　</p><p><strong>●開催日</strong><br>10月26日(土)・10月27日(日)<br>【1回目】10:00～【2回目】14:00～<br>※所要時間2時間</p><p>&nbsp;</p><p><strong>●会場</strong><br>スマイル・ビルダーズ姶良総合展示場<br>総合案内所</p><p>&nbsp;</p><p><strong>●参加費</strong><br>1,500円（ご参加のお子様1人あたり）</p><p>&nbsp;</p><p><strong>●対象年齢</strong><br>小学校2年生～<br>※兄弟がいる場合は、1家族様2人まで</p><p>&nbsp;</p><p><strong>●イベント当日の流れ</strong><br>・イベントの流れの説明<br>　道具の使い方の説明<br>・お家のテーマ決め、間取りの下書き<br>・1階と2階の組み立て<br>・完成したお家の見学会<br>・最後に飲み物とお菓子をプレゼント<br>※カッターを使うワークショップとなります。</p><p>　　</p><p>※ご友人同士でのお申し込みの場合は、それぞれお申込みいただきLINE公式にてその旨をお知らせくださいませ。<br><br>気になることがございましたら、Life plus home LINE公式からお気軽にお問合せください。</p><p>皆さまのご参加をお待ちしております！</p><p>&nbsp;</p><p><strong>●応募方法</strong></p><p>&nbsp;</p><p style=\"text-align:center;\"><br>＼　LINE公式にて受付中！　／<br>参加組数に限りあり今すぐ応募を！<br>&nbsp;</p><p><a href=\"https://clampy.co.jp/wp-content/uploads/2023/07/1022_color.png\"><img class=\"image_resized\" style=\"aspect-ratio:261/300;width:19.23%;\" src=\"https://clampy.co.jp/wp-content/uploads/2023/07/1022_color-261x300.png\" alt=\"\" width=\"261\" height=\"300\"></a>​</p><p>&nbsp;</p><p>Life plus home LINE公式から<br>LINE公式ID：@853miqdl</p><p>応募フォームからのご応募をお願いいたします。</p><p>&nbsp;</p><p>【第一弾】<br><strong>応募締切</strong>：10月18日(金)11:59まで<br><strong>応募結果のご案内</strong>：10月18日(金)18:00</p><p>&nbsp;</p><p>【第二弾<br><strong>応募締切</strong>：10月25日(金)11:59まで<br><strong>応募結果のご案内</strong>：10月25日(金)18:00</p><p>　</p><p>※当選された方のみにLINE公式にてお知らせします。<br>※応募状況によっては抽選となる場合がございます。</p><p>&nbsp;</p><p>＼<strong> Life plus home LINE公式</strong> ／<br>&nbsp;</p><p><a href=\"https://lin.ee/ZCCLP7C\"><img src=\"https://scdn.line-apps.com/n/line_add_friends/btn/ja.png\" alt=\"友だち追加\" width=\"174\" height=\"55\"></a>​</p><p>&nbsp;</p><p style=\"text-align:center;\"><strong>～イベントの様子～</strong></p><figure class=\"image\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/173048015112922.jpg\" width=\"620\" height=\"465\"></figure><figure class=\"image\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/173048015975023.jpg\" width=\"620\" height=\"465\"></figure><figure class=\"image\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/173048016871724.jpg\" width=\"620\" height=\"465\"></figure><figure class=\"image\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/173048018025925.jpg\" width=\"620\" height=\"465\"></figure><figure class=\"image\"><img style=\"aspect-ratio:620/465;\" src=\"/imgs/upload/173048018762626.jpg\" width=\"620\" height=\"465\"></figure><p><strong>◆</strong><span style=\"color:#e74c3c;\"><strong>注意事項</strong></span><strong>◆</strong><br>・材料道具はすべてご用意いたします。持ち物等は特にありません<br>・こちらのイベントはLINE公式からの《<strong>参加応募制</strong>》となっております。<br>・申込内容はご記入いただいたメールアドレスとLINE公式にてお知らせいたします。<br>・応募が多い場合は抽選となる場合がございます。抽選結果は、<strong>当選の方のみ</strong>にLINE公式にてお知らせいたします。<br>・当日の諸注意・ご連絡はLINE公式にてお知らせします。LINE公式のご登録を必ずお願い致します。<br>・本イベント終了までは メールの削除、LINE公式のブロック等はお控えください。<br>・参加されるお子様にご兄弟がいらっしゃる場合は、1家族2名までの応募となります。<br>・各回にお子様4名までの受付とさせていただきます。<br>・当日のキャンセルはご遠慮ください。<br>・当日のLINE公式の返信は、時間を要する場合がございますので予めご了承ください。<br>・何らかの事情により急遽イベントが中止・延期となった場合は、直ちに LINE公式にてご連絡させていただきます。<br>・参加風景の映像や写真が弊社HP・SNSなどで利用される可能性があります。予めご理解いただいた上でご参加ください。</p><p>&nbsp;</p><p>　</p><p>​</p>', NULL, '設定しない', '2024-11-02 01:50:36', '2024-11-28 10:25:29', NULL, 1);
