DROP TABLE IF EXISTS `events`;
CREATE TABLE `events`  (
  `id` int NOT NULL AUTO_INCREMENT,
  `userID` int NOT NULL,
  `title` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `type` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `format` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL,
  `eventDate` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `note` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `status` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '非公開',
  `statusBit` int NULL DEFAULT 0,
  `priority` tinyint NULL DEFAULT NULL,
  `prefecture` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `address1` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `address2` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `hiddenAddress` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `mapFormat` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '地図にピンを表示する',
  `mailFormat` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '住所を全て記載する',
  `images` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `mainIndex` int NULL DEFAULT NULL,
  `FPImages` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `tag` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `feature` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `benefit` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL,
  `propertyType` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '設定しない',
  `createdAt` timestamp NOT NULL DEFAULT current_timestamp,
  `updatedAt` timestamp NOT NULL DEFAULT current_timestamp ON UPDATE CURRENT_TIMESTAMP,
  `deletedAt` timestamp NULL DEFAULT NULL,
  `isApproved` int NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 252 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

